    log_config log_conf = {LOG_LEVEL_INFO, "stdout"};
    FILE* output_file = NULL;

    while ((c = getopt(argc, argv, "o:v:l:")) != -1) {
        switch (c) {
            case 'o':
                output_file = fopen(optarg, "w");
                break;
            case 'v':
                log_conf.log_target = optarg;
                break;
            case 'l':
                if (strtol(optarg, NULL, 10) > 0) {
                    log_conf.level = strtol(optarg, NULL, 10);
                }
                break;
        }
    }

    if (output_file == NULL) {
        output_file = stdout;
    }

    char* action = "unknown";
    char* input_file_name = argv[optind];

    for (int i = optind; i < argc; i++) {
        if (strcmp(argv[i], "--manpage") == 0) {
            action = "manpage";
            break;
        }
        else if (strcmp(argv[i], "-cs") == 0) {
            action = "cs";
            break;
        }
