        // perform batch processing on the content
    }

    fclose(input_file);
    if (output_file != stdout) {
        fclose(output_file);
    }

    return 0;
}

void log_info(const char* format, ...) {
    va_list ap;
    va_start(ap, format);
    vfprintf(stdout, format, ap);
    va_end(ap);
}

void log_debug(const char* format, ...) {
    if (LOG_LEVEL_DEBUG <= log_conf.level) {
