class RateLimiter {
public:
    RateLimiter() : maxRequestsPerSecond_(0), requestsInFlight_(0) {}

    void setMaxRequestsPerSecond(int maxRequestsPerSecond) {
        maxRequestsPerSecond_ = maxRequestsPerSecond;
    }

    bool isAllowedToMakeRequest() {
        std::unique_lock<std::mutex> lock(mutex_);
        if (requestsInFlight_ >= maxRequestsPerSecond_) {
            return false;
        }
        requestsInFlight_++;
        cv_.wait_for(lock, std::chrono::seconds(1));
        requestsInFlight_--;
        return true;
    }

private:
    int maxRequestsPerSecond_;
    atomic<int> requestsInFlight_;
    std::mutex mutex_;
    std::condition_variable cv_;
};

class RateLimiterService {
public:
    RateLimiterService() : rateLimiter_(new RateLimiter()) {}

    void configureRateLimit(int rate) {
        boost::property_tree::ptree pt;
        pt.put("rate", rate);
        // Update configuration API with new rate limit
        // ...
    }

    bool allowRequest(const std::string& userId) {
        if (!isAllowedToMakeRequest(userId)) {
            return false;
        }
        // Mark request as processed in the anomaly detection system
        // ...
        return true;
    }

private:
    RateLimiter* rateLimiter_;
};

int main() {
