#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <sys/types.h>
#include <sys/socket.h>
#include <netinet/in.h>
#include <arpa/inet.h>
#include <pthread.h>
#include <semaphore.h>

#define BUFFER_SIZE 1024
#define MAX_STREAMS 10

typedef struct {
    int value;
    pthread_mutex_t lock;
} stream_value;

stream_value streams[MAX_STREAMS];
sem_t sem;

void *read_stream(void *arg) {
    int sock = *(int *)arg;
    int buffer[BUFFER_SIZE];
    int bytes_read;
    int max_value = 0;
    pthread_mutex_lock(&streams[sock].lock);
    while ((bytes_read = read(sock, buffer, BUFFER_SIZE)) > 0) {
        for (int i = 0; i < bytes_read; i++) {
            if (buffer[i] > max_value) {
                max_value = buffer[i];
            }
        }
    }
    pthread_mutex_unlock(&streams[sock].lock);
    return NULL;
}

void process_streams() {
    pthread_t threads[MAX_STREAMS];
    for (int i = 0; i < MAX_STREAMS; i++) {
        if (pthread_create(&threads[i], NULL, read_stream, &i) != 0) {
            perror("pthread_create");
            exit(EXIT_FAILURE);
        }
    }
    for (int i = 0; i < MAX_STREAMS; i++) {
        pthread_join(threads[i], NULL);
    }
}

void log_max_value(int max_value) {
    // Integrate with external logging service
    printf("Max value: %d\n", max_value);
}

int main() {
    int s;
    struct sockaddr_in sin;

    sem_init(&sem, 0, 1);

    for (int i = 0; i < MAX_STREAMS; i++) {
        s = socket(AF_INET, SOCK_STREAM, 0);
        sin.sin_family = AF_INET;
        sin.sin_port = htons(12345);
        inet_pton(AF_INET, "127.0.0.1", &sin.sin_addr);
        connect(s, (struct sockaddr *)&sin, sizeof(sin));
        pthread_mutex_init(&streams[i].lock, NULL);
        streams[i].value = 0;
    }

    process_streams();

    sem_destroy(&sem);

    for (int i = 0; i < MAX_STREAMS; i++) {
        close(streams[i].sock);
        pthread_mutex_destroy(&streams[i].lock);
    }
    return 0;
}
