import os
import hashlib
import logging
from flask import Flask, request, jsonify
from werkzeug.utils import secure_filename
from concurrent.futures import ThreadPoolExecutor, as_completed
from celery import Celery

app = Flask(__name__)
app.config['UPLOAD_FOLDER'] = './uploads'
app.config['MAX_CONTENT_LENGTH'] = 16 * 1024 * 1024

celery = Celery('hash_calculator', broker='amqp://guest:guest@localhost')
celery.conf.update({
    'result_backend': 'db+sqlite:///results.db',
})

logging.basicConfig(level=logging.INFO)
logger = logging.getLogger(__name__)

@app.route('/upload', methods=['POST'])
def upload_file():
    if request.method == 'POST':
        file = request.files.get('file')
        filename = secure_filename(file.filename)
        filepath = os.path.join(app.config['UPLOAD_FOLDER'], filename)

        with open(filepath, 'wb') as f:
            f.write(file.stream.read())

        task_id = celery.send_task('calculate_hashes', args=(filepath,))
        return jsonify({'task_id': task_id})

@app.task
def calculate_hashes(filepath):
    try:
        md5_hash = hashlib.md5()
        sha256_hash = hashlib.sha256()

        with open(filepath, 'rb') as f:
            for chunk in iter(lambda: f.read(4096), b''):
                md5_hash.update(chunk)
                sha256_hash.update(chunk)

        md5_hash = md5_hash.hexdigest()
        sha256_hash = sha256_hash.hexdigest()

        return {'md5': md5_hash, 'sha256': sha256_hash}
    except Exception as e:
        logger.error(f'Error calculating hashes: {e}')
        raise

@app.route('/result', methods=['GET'])
def get_result():
    task_id = request.args.get('task_id')
    result = celery.AsyncResult(task_id).result
    return jsonify({'md5': result['md5'], 'sha256': result['sha256']})

if __name__ == '__main__':
    app.run(debug=True)
