#define MAX_CONCURRENCY 5000
#define SEMAPHORE_NAME_SIZE 16

typedef struct {
    sem_t* semaphores;
    int semaphore_count;
} semaphore_t;

typedef struct {
    mqd_t queue;
    int message_size;
    int message_max_priority;
} message_queue_t;

semaphore_t semaphores;
message_queue_t message_queue;

void init_semaophores(const char* config_file) {
    json_object* config = json_load_file(config_file, 0);
    if (!config) {
        printf("Error: Unable to load configuration file.\n");
        exit(EXIT_FAILURE);
    }

    int semaphore_count = json_object_size(config);
    semaphores.semaphore_count = semaphore_count;
    semaphores.semaphores = malloc(semaphore_count * sizeof(sem_t));
    for (int i = 0; i < semaphore_count; i++) {
        sem_init(&semaphores.semaphores[i], 1, 1);
    }
}

void destroy_semaophores() {
    for (int i = 0; i < semaphores.semaphore_count; i++) {
        sem_destroy(&semaphores.semaphores[i]);
    }
    free(semaphores.semaphores);
}

void init_message_queue(const char* config_file) {
    json_object* config = json_load_file(config_file, 0);
    if (!config) {
        printf("Error: Unable to load configuration file.\n");
        exit(EXIT_FAILURE);
    }

    message_queue.message_size = json_object_get_int(config, "message_size");
    message_queue.message_max_priority = json_object_get_int(config, "message_max_priority");

    int ret = mq_open((const char*)config_object_get_string(config, "queue_name"), O_RDWR | O_CREAT, 0666, NULL);
    if (ret < 0) {
        printf("Error: Unable to create message queue.\n");
        exit(EXIT_FAILURE);
    }

    message_queue.queue = mq_open((const char*)config_object_get_string(config, "queue_name"), O_RDONLY);

    json_object_free(config);
}

void destroy_message_queue() {
    mq_close(message_queue.queue);
}

int main(int argc, char* argv[]) {
    init_semaophores("config.json");
    init_message_queue("config.json");

    pthread_t threads[MAX_CONCURRENCY];
    for (int i = 0; i < MAX_CONCURRENCY; i++) {
        pthread_create(&threads[i], NULL, worker_thread, NULL);
    }

