impl Compiler {
    pub fn new() -> Self {
        Compiler {
            grammars: HashMap::new(),
            cache: HashMap::new(),
        }
    }

    pub fn add_grammar(&mut self, name: &str, grammar: Box<grammar::Grammar>) {
        self.grammars.insert(name.to_string(), grammar);
    }

    pub fn compile_file(&self, path: &Path) -> Result<Box<ir_generator::IR>, String> {
        if let Some((cached_ir, is_cached)) = self.cache.get(path) {
            if *is_cached {
                return Ok(*cached_ir);
            }
        }

        let grammar_name = determine_grammar(path)?;
        let grammar = self.grammars.get(&grammar_name).ok_or("Unknown grammar".to_string())?;
        let ir = compile_file_with_grammar(path, grammar)?;

        self.cache.insert(PathBuf::from(path), (ir, true));
        Ok(ir)
    }

    // ... other methods ...
}

fn determine_grammar(path: &Path) -> Result<String, String> {
    // implement logic to determine the grammar based on file extension or content
    // for example:
    let ext = path.extension().unwrap_or_default();
    if ext == "cpp" {
        Ok("C++".to_string())
    } else if ext == "java" {
        Ok("Java".to_string())
    } else {
        Err("Unknown file type".to_string())
    }
}

fn compile_file_with_grammar(path: &Path, grammar: &Box<grammar::Grammar>) -> Result<Box<ir_generator::IR>, String> {
