using System;
using System.Data;
using System.Data.SqlClient;
using System.Threading.Tasks;

namespace ParameterizedQueryService
{
    public class ParameterizedQueryService : IParameterizedQueryService
    {
        private readonly ConnectionSettings _connectionSettings;

        public ParameterizedQueryService(ConnectionSettings connectionSettings)
        {
            _connectionSettings = connectionSettings;
        }

        public async Task ExecuteParameterizedQueryAsync(IList<SqlParameter> parameters, string commandTemplate)
        {
            await ValidateAndConfigureDatabaseConnection();

            try
            {
                using (var connection = new SqlConnection(_connectionSettings.ConnectionString))
                {
                    connection.Open();

                    using (var command = new SqlCommand(commandTemplate, connection))
                    {
                        foreach (var parameter in parameters)
                        {
                            command.Parameters.Add(parameter);
                        }

                        await Task.Run(() => command.ExecuteNonQuery());
                    }
                }
            }
            catch (SqlException ex) when (IsTransientError(ex))
            {
                // Retrying logic for transient database failures
                await RetryExecutionAsync(commandTemplate, parameters);
            }
            catch (TimeoutException)
            {
                // Handling potential timeouts and disconnections gracefully
                throw new QueryTimeoutException("Query timeout exceeded");
            }
            catch (Exception ex)
            {
                // Logging and monitoring for query execution
                await LogErrorAndThrowAsync(ex);
            }
        }

        private async Task ValidateAndConfigureDatabaseConnection()
        {
            if (_connectionSettings == null || string.IsNullOrEmpty(_connectionSettings.ConnectionString))
            {
                throw new ArgumentException("Invalid connection settings", nameof(_connectionSettings));
            }

            try
            {
                using (var connection = new SqlConnection(_connectionSettings.ConnectionString))
                {
                    await connection.OpenAsync();
                }
            }
            catch (SqlException ex)
            {
                // Handling potential connection-related errors
                throw new ConnectionFailedException("Database connection failed", ex);
            }
        }

        private async Task RetryExecutionAsync(string commandTemplate, IList<SqlParameter> parameters)
        {
            const int maxRetries = 3;
            int retries = 0;

            while (retries < maxRetries)
            {
                await ExecuteParameterizedQueryAsync(parameters, commandTemplate);

                if (!IsTransientError(lastException))
                {
                    break;
                }

                // Waiting for a short duration before retrying
                await Task.Delay(500);
            }
        }

        private async Task LogErrorAndThrowAsync(Exception ex)
        {
            // Logging and monitoring for query execution
            await LogErrorAsync(ex);

            throw new QueryExecutionException("Query execution failed", ex);
        }
    }
}
