    {
        // Store processed weather data in Redis cache with a configurable time-to-live (TTL) setting
        int ttl = Convert.ToInt32(_configuration["RedisTTL"]);
        await _redisConnection.ExecuteAsync("SETRNX weather_data", weatherData);
        await _redisConnection.ExecuteAsync("EXPIRE weather_data " + ttl);
    }

