                await FetchAndProcessWeatherDataAsync();

                return await GetWeatherForecastAsync(location); // Recursively fetch updated forecast
            }

            return cachedData;
        }
        catch (Exception ex)
        {
            _logger.LogError(ex, "Error occurred while retrieving weather forecast.");
            return null;
        }
    }

    public async Task StartServiceAsync()
    {
