        {
            // Initialize the service with a configurable interval for fetching and processing weather data
            int interval = Convert.ToInt32(_configuration["Interval"]);

            await Task.Run(() =>
            {
                while (true)
                {
                    await FetchAndProcessWeatherDataAsync();
                    await Task.Delay(interval * 1000);
                }
            });
        }
        catch (Exception ex)
        {
            _logger.LogError(ex, "Error occurred while starting the service.");
        }
    }

    public async Task StopServiceAsync()
    {
        // Disconnect Redis connection and stop the service
        await _redisConnection.ExecuteAsync("QUIT");
    }
}
