namespace UserAccountService;

use Doctrine\DBAL\Connection;
use Doctrine\DBAL\Query\QueryBuilder;
use Ramsey\Uuid\Uuid;
use Symfony\Component\Validator\ConstraintViolationListInterface;
use Symfony\Component\Validator\ValidatorInterface;
use Zend\ServiceManager\AbstractPlugin;

class UserAccountService extends AbstractPlugin
{
    private $connection;
    private $validator;

    public function __construct(Connection $connection, ValidatorInterface $validator)
    {
        $this->connection = $connection;
        $this->validator = $validator;
    }

    public function createUser(array $data): Uuid
    {
        // Validate user data
        $violations = $this->validator->validate($data);
        if ($violations->count()) {
            throw new \Exception('Invalid user data');
        }

        // Create a new user account
        $query = $this->connection->createQueryBuilder('users')
            ->insert()
            ->values([
                'id' => ':id',
                'name' => ':name',
                'email' => ':email',
            ])
            ->setParameter('id', Uuid::uuid4())
            ->setParameter('name', $data['name'])
            ->setParameter('email', $data['email']);
        $query->execute();

        return $query->getResult();
    }

    public function getUser(Uuid $id): array
    {
        // Get a user account by ID
        $query = $this->connection->createQueryBuilder('users')
            ->select(['id', 'name', 'email'])
            ->where('id = :id')
            ->setParameter('id', $id);
        $result = $query->execute()->getOneOrNullResult();

        if (!$result) {
            throw new \Exception('User not found');
        }

        return [
            'id' => $result['id'],
            'name' => $result['name'],
            'email' => $result['email'],
        ];
    }

    public function updateUser(Uuid $id, array $data): void
    {
        // Validate user data and ID
        if ($this->validator->validate($data)->count()) {
            throw new \Exception('Invalid user data');
        }

        if (!$this->getUser($id)) {
            throw new \Exception('User not found');
        }

        // Update a user account
        $query = $this->connection->createQueryBuilder('users')
            ->update()
            ->set('name', ':name')
            ->set('email', ':email')
            ->where('id = :id')
            ->setParameter('id', $id)
            ->setParameter('name', $data['name'])
            ->setParameter('email', $data['email']);
        $query->execute();
    }

    public function deleteUser(Uuid $id): void
    {
        // Delete a user account
        $query = $this->connection->createQueryBuilder('users')
            ->delete()
            ->where('id = :id')
            ->setParameter('id', $id);
        $query->execute();
    }
}
