const { createReadStream } = require('fs');
const { promisify } = require('util');
const got = require('got');
const { performance } = require('perf_hooks');
const { setInterval } = require('timers');
const { setTimeout } = require('timers');
const moment = require('moment-timezone');

const config = {
  directoryPath: './logs',
  filters: {
    size: [10 * 1024, Infinity],
    timestamp: [new Date('2020-01-01T00:00:00.000Z'), new Date()],
    content: ['error', 'warning']
  },
  apiEndpoint: 'https://metadata-api.com/lookup',
  cacheTimeout: 30000,
  concurrentOperations: 5
};

const api = got.extend({
  timeout: { request: 5000, socket: 30000 }
});

async function processFile(file) {
  const fileSize = file.stats.size;
  const fileTimestamp = moment(file.stats.mtime).toISOString();
  const fileContent = await readFileAsync(file.path);

  if (!fileSize || !fileTimestamp || !fileContent) return;

  for (const filter of config.filters) {
    switch (filter.type) {
      case 'size':
        if (fileSize < filter.min || fileSize > filter.max) continue;
        break;
      case 'timestamp':
        if (moment(fileTimestamp).isBefore(filter.min) || moment(fileTimestamp).isAfter(filter.max)) continue;
        break;
      case 'content':
        const fileContentMatch = fileContent.toString().includes(filter.value);
        if (!fileContentMatch) continue;
        break;
    }
  }

  await api.post(`${config.apiEndpoint}/${file.path}`, {
    json: {
      filename: file.path,
      size: fileSize,
      timestamp: fileTimestamp,
      content: fileContent.toString()
    }
  });
}

async function processDirectory(path) {
  const files = await fs.readdirAsync(path);
  for (const file of files) {
    if (!file.isDirectory()) {
      try {
        await processFile(file);
      } catch (error) {
        console.error(`Error processing file ${file.path}: ${error}`);
      }
    }
  }
}

async function main() {
  try {
    await fs.mkdirAsync(config.directoryPath, { recursive: true });
    setInterval(() => {
      processDirectory(config.directoryPath);
    }, config.concurrentOperations * 1000);

    setTimeout(() => {
      console.log('Service started. Processing files in background...');
    }, 1000);
  } catch (error) {
    console.error(`Error starting service: ${error}`);
  }
}

main();
