function executeTests(moduleName, testCases, blueslipMocker, externalDataFetcher) {
  return new Promise((resolve, reject) => {
    // Load module asynchronously
    import(`./${moduleName}`).then((module) => {
      let results = [];
      let externalDataCache = {};

      async function runTestCase(testCase, index) {
        try {
          // Log test start and retrieve required external data
          console.log(`Starting test ${testCase.label} for module ${moduleName}`);
          let externalData;
          if (testCase.requiresExternalData) {
            externalData = await fetchExternalData(testCase, externalDataFetcher);
          }

          // Execute the test case
          try {
            let result = await testCase();
            results.push({ label: testCase.label, status: 'pass' });
            console.log(`Test ${testCase.label} passed`);
          } catch (error) {
            console.error(`Test ${testCase.label} failed`);
            if (!externalData) {
              externalData = {};
            }
            results.push({
              label: testCase.label,
              status: 'fail',
              error: { message: error.message, stack: error.stack },
              externalData: externalData || null
            });
          } finally {
            // Reset blueslip mock after each test
            blueslipMocker();
          }
        } catch (error) {
          reject(`Error running tests for module ${moduleName}: ${error}`);
        }
      }

      // Run all test cases in parallel
      await Promise.all(testCases.map(runTestCase));

      resolve(results);
    }).catch((error) => {
      reject(`Error loading module ${moduleName}: ${error}`);
    });
  });
}

async function fetchExternalData(testCase, externalDataFetcher) {
  if (externalDataCache[testCase.label]) {
    return externalDataCache[testCase.label];
  }

  try {
    let data = await externalDataFetcher();
    externalDataCache[testCase.label] = data;
    return data;
  } catch (error) {
    console.error(`Error fetching external data for test ${testCase.label}: ${error}`);
    return null;
  }
}
