function renderFooterScripts(scripts) {
  const scriptTags = [];

  for (const script of scripts) {
    if (!script.src && !script.text) continue;

    let srcAttr;
    if (script.src) {
      try {
        const response = await fetch(script.src);
        const scriptText = await response.text();
        srcAttr = `src="${scriptText}"`;
      } catch (error) {
        console.error(`Error loading script from ${script.src}: ${error}`);
        continue;
      }
    } else {
      srcAttr = `text="${script.text}"`;
    }

    let asyncAttr = ' async';
    if (!script.async) asyncAttr = '';

    const tag = `
      <script${asyncAttr} ${srcAttr}>
        ${script.onLoad ? script.onLoad() : ''}
      </script>
    `;
    scriptTags.push(tag);
  }

  return scriptTags.join('');
}
