// book-reference-service.js
import { Injectable } from '@angular/core';
import { HttpClient } from '@angular/common/http';

@Injectable({
  providedIn: 'root'
})
export class BookReferenceService {

  private apiEndpoint = 'https://api.example.com/books';
  private config = {
    bookPatterns: [
      { regex: /\bGenesis\b/, mapping: 'GEN' },
      { regex: /\bExodus\b/, mapping: 'EXO' },
      // Add more patterns as needed
    ]
  };
  private cache = {};

  constructor(private http: HttpClient) { }

  async identifyReferences(text: string): Promise<{ [key: string]: any }[]> {
    const references = [];
    for (const pattern of this.config.bookPatterns) {
      if (pattern.regex.test(text)) {
        const bookId = text.match(pattern.regex)[0].toUpperCase();
        const cachedBook = this.cache[bookId];
        if (!cachedBook) {
          try {
            const response = await this.http.get(`${this.apiEndpoint}/${bookId}`);
            this.cache[bookId] = response;
          } catch (error) {
            console.error(`Error fetching book data: ${error}`);
            continue;
          }
        }
        references.push({ ...pattern.mapping, ...cachedBook });
      }
    }
    return references;
  }

}
