#include <stdlib.h>
#include <stdio.h>
#include <string.h>
#include <sys/types.h>
#include <sys/stat.h>
#include <unistd.h>
#include <fcntl.h>

// Define the maximum number of items to load per request
#define MAX_ITEMS_PER_REQUEST 1000

// Define the maximum number of concurrent requests
#define MAX_CONCURRENT_REQUESTS 5

// Structure to represent a resource bundle
typedef struct {
    char* filename;
    char* contents;
} ResourceBundle;

// Function to dynamically load resource bundles from a remote server
ResourceBundle* load_resource_bundles(const char* api_url, int max_items_per_request) {
    // Create a thread pool for efficient concurrency
    pthread_t threads[MAX_CONCURRENT_REQUESTS];
    pthread_mutex_t lock = PTHREAD_MUTEX_INITIALIZER;
    sem_t semaphore = sem_open("/semaphore", O_CREAT, 0644, 0);

    // Initialize the resource bundle array
    ResourceBundle* bundles = (ResourceBundle*)malloc(sizeof(ResourceBundle) * MAX_ITEMS_PER_REQUEST);
    int num_bundles = 0;

    // Loop until all bundles are loaded or the maximum number of concurrent requests is reached
    for(int i = 0; i < MAX_CONCURRENT_REQUESTS && i < max_items_per_request; i++) {
        // Start a new thread to load a bundle concurrently
        pthread_create(&threads[i], NULL, (void*)load_bundle_thread, (void*)api_url);

        // Wait for the thread to finish and add the bundle to the array if successful
        sem_wait(&semaphore);
        ResourceBundle* bundle = bundles + num_bundles++;
        sem_post(&semaphore);

        // Check for errors and exit if any
        if(bundle->filename == NULL || bundle->contents == NULL) {
