['```javascript
// component.js
import { useState, useEffect } from 'react';
import axios from 'axios';

const DynamicDOMProcessor = ({ rootElement, config }) => {
  const [filteredElements, setFilteredElements] = useState([]);
  const [loading, setLoading] = useState(false);

  useEffect(() => {
    const fetchMetadata = async (elements) => {
      setLoading(true);
      try {
        const responses = await Promise.all(
          elements.map(async (element) => {
            const response = await axios.get(`https://api.example.com/metadata/${element.id}`);
            return { ...element, metadata: response.data };
          })
        );
        setFilteredElements(responses.filter((response) => config.filters.some((filter) => filter(response))));
      } catch (error) {
        console.error('Error fetching metadata:', error);
      } finally {
        setLoading(false);
      }
    };

    const processDOM = () => {
      if (loading) return null;

      const elements = Array.from(rootElement.children);
      fetchMetadata(elements);
    };

    rootElement.addEventListener('childAdded', processDOM);
    rootElement.addEventListener('childRemoved', processDOM);

    return () => {
      rootElement.removeEventListener('childAdded', processDOM);
      rootElement.removeEventListener('childRemoved', processDOM);
    };
  }, [config, rootElement]);

  const renderElements = (elements) =>
    elements.map((element) => (
      <div key={element.id} className="processed-element">
        {element.metadata && <span>Metadata: {JSON.stringify(element.metadata)}</span>}
      </div>
    ));

  return (
    <div>
      {filteredElements.length > 0 ? renderElements(filteredElements) : 'No matching elements found'}
    </div>
  );
};

export default DynamicDOMProcessor;
