import java.io.*;
import java.util.*;
import java.net.*;
import com.google.common.collect.*;

public class LargeScaleDatasetProcessor {

    private static final int PARALLEL_THRESHOLD = 100000;
    private static final boolean PRINT_STATS = false;

    public void processLargeScaleDataset(Configuration config, InputStream input) {
        UnionFind uf = new UnionFind(config.getMaxPairs());

        try (BufferedReader reader = new BufferedReader(new InputStreamReader(input))) {
            String line;
            while ((line = reader.readLine()) != null) {
                int[] array = Arrays.stream(line.split(",")).mapToInt(Integer::parseInt).toArray();
                processArray(array, uf);
            }
        } catch (IOException e) {
            logError("Error reading input data", e);
        }

        if (PRINT_STATS) {
            System.out.println("Disjoint pairs found: " + uf.getCount());
            long totalTime = System.nanoTime() - config.getStartTime();
            System.out.println("Processing time: " + TimeUnit.NANOSECONDS.toSeconds(totalTime));
        }
    }

    private void processArray(int[] array, UnionFind uf) {
        int n = array.length;
        if (n > PARALLEL_THRESHOLD) {
            processLargeArray(array, uf);
        } else {
            processSmallArray(array, uf);
        }
    }

    private void processLargeArray(int[] array, UnionFind uf) {
        ExecutorService executor = Executors.newFixedThreadPool(4);

        List<Future<Integer>> futures = new ArrayList<>();
        for (int i = 0; i < array.length; i += PARALLEL_THRESHOLD / 4) {
            int end = Math.min(i + PARALLEL_THRESHOLD / 4, array.length);
            Integer[] chunk = Arrays.copyOfRange(array, i, end);
            Future<Integer> future = executor.submit(() -> processChunk(chunk, uf));
            futures.add(future);
        }

        for (Future<Integer> future : futures) {
            try {
                future.get();
            } catch (InterruptedException | ExecutionException e) {
                logError("Error processing array chunk", e);
            }
        }
    }

    private void processSmallArray(int[] array, UnionFind uf) {
        for (int i = 0; i < array.length - 1; i++) {
            for (int j = i + 1; j < array.length; j++) {
                if (!uf.isConnected(array[i], array[j])) {
                    uf.union(array[i], array[j]);
                }
            }
        }
    }

    private int processChunk(int[] chunk, UnionFind uf) {
        for (int i = 0; i < chunk.length - 1; i++) {
            for (int j = i + 1; j < chunk.length; j++) {
                if (!uf.isConnected(chunk[i], chunk[j])) {
                    uf.union(chunk[i], chunk[j]);
                }
            }
        }
        return uf.getCount();
    }

    private void logError(String message, Throwable e) {
        // Implement logging mechanism to write error messages and stack trace
    }

    public static class Configuration {

        private int maxPairs;
        private long startTime;

        public Configuration(int maxPairs, long startTime) {
            this.maxPairs = maxPairs;
            this.startTime = startTime;
        }

        public int getMaxPairs() {
            return maxPairs;
        }

        public long getStartTime() {
            return startTime;
        }
    }

}
