<?php
declare(strict_types=1);

namespace ClinicStatusUpdater;

use GuzzleHttp\Client;
use Pimple\Container;
use Pimple\ServiceProviderInterface;
use Redis;
use PDO;

class ClinicStatusUpdater implements ServiceProviderInterface {
    public function register(Container $app) {
        $app['guzzle'] = new Client(['base_uri' => 'https://health-records-api.com/']);
        $app['redis'] = new Redis();
        $app['db'] = new PDO('mysql:host=localhost;dbname=clinic_status', 'username', 'password');
    }

    public function boot(Container $app) {
        $app['semaphore'] = new Semaphore($app['redis'], 10);
    }
}

class ClinicStatusUpdaterService {
    private $guzzle;
    private $redis;
    private $db;
    private $semaphore;

    public function __construct(GuzzleClient $guzzle, Redis $redis, PDO $db, Semaphore $semaphore) {
        $this->guzzle = $guzzle;
        $this->redis = $redis;
        $this->db = $db;
        $this->semaphore = $semaphore;
    }

    public function updateStatus(array $data): array {
        try {
            $this->validateInputData($data);

            if (!$this->acquireSemaphore()) {
                return ['error' => 'Semaphore acquisition failed'];
            }

            try {
                $latestClinicDetails = $this->retrieveLatestClinicDetails($data['clinicID']);
                $this->updateClinicStatus($data['newStatus'], $latestClinicDetails);

                if ($this->db->lastInsertId() > 0) {
                    return ['status' => 'updated'];
                } else {
                    return ['error' => 'Update failed'];
                }
            } catch (\Exception $e) {
                $this->logError($e);
                return ['error' => 'Database connection issue: ' . $e->getMessage()];
            } finally {
                $this->releaseSemaphore();
            }
        } catch (\InvalidArgumentException $e) {
            $this->logError($e);
            return ['error' => 'Invalid input data: ' . $e->getMessage()];
        }
    }

    private function validateInputData(array $data): void {
        if (!isset($data['clinicID']) || !is_string($data['clinicID'])) {
            throw new \InvalidArgumentException('Missing or invalid clinic ID');
        } elseif (!isset($data['newStatus']) || !is_string($data['newStatus'])) {
            throw new \InvalidArgumentException('Missing or invalid new status');
        } elseif (!isset($data['lastModifiedIP']) || !is_string($data['lastModifiedIP'])) {
            throw new \InvalidArgumentException('Missing or invalid last modified IP');
        } elseif (!isset($data['lastModifiedDate']) || !is_string($data['lastModifiedDate'])) {
            throw new \InvalidArgumentException('Missing or invalid last modified date');
        }
    }

    private function retrieveLatestClinicDetails(string $clinicID): array {
        while (true) {
            try {
                $response = $this->guzzle->get('clinics/' . $clinicID);
                if ($response->getStatusCode() === 200) {
                    return json_decode($response->getBody(), true);
                } else {
                    sleep(1); // exponential backoff
                    continue;
                }
            } catch (\GuzzleHttp\RuntimeException $e) {
                sleep(2); // exponential backoff for failed API calls
                continue;
            }
        }
    }

    private function updateClinicStatus(string $newStatus, array $latestClinicDetails): void {
        try {
            $stmt = $this->db->prepare('UPDATE clinics SET status = :status WHERE id = :id');
            $stmt->execute([':status' => $newStatus, ':id' => $latestClinicDetails['id']]);
        } catch (\PDOException $e) {
            throw $e;
        }
    }

    private function acquireSemaphore(): bool {
        while (true) {
            if ($this->semaphore->acquire()) {
                return true;
            } elseif (rand(1, 5) === 3) { // exponential backoff for semaphore acquisition failures
                sleep(rand(1, 10));
                continue;
            }
        }
    }

    private function releaseSemaphore(): void {
        $this->semaphore->release();
    }

    private function logError(\Exception $e): void {
        error_log($e->getMessage());
    }
}
