    -- Validate input parameters
    IF @max_results > 100 OR @max_results < 1
        SET @max_results = 10;

    DECLARE @validated_cities TABLE (city nvarchar(50));
    DECLARE @api_timeout int = 5000;  -- 5 seconds
    DECLARE @retries int = 3;
    DECLARE @backoff_time int = 1000;  -- 1 second

    WHILE @retries > 0
    BEGIN
        BEGIN TRY
            -- Validate city names against external API
            INSERT INTO @validated_cities (city)
                EXEC ('SELECT DISTINCT city FROM [ExternalAPI] WHERE city IN (' + QUOTENAME(@external_system_id) + ')');

            BREAK;
        END TRY
        BEGIN CATCH
            IF ERROR_NUMBER() = 10053  -- timeout error
                SET @retries -= 1;

            WAITFOR DELAY '00:00:01';
        END CATCH
    END;

    IF @retries = 0
        RAISERROR('Failed to validate city names. Please check the external API', 16, 1);

    -- Create composite index for performance optimization
    CREATE NONCLUSTERED INDEX IX_Employees_SupervisorId_City ON Employees (supervisor_id, city);

    SELECT TOP (@max_results) 
        e.name,
        e.city,
        e.address
    FROM Employees e
    WHERE e.supervisor_id = @supervisor_id
    AND EXISTS (
        SELECT 1 FROM @validated_cities c
        WHERE c.city = e.city
    );

    IF @@ROWCOUNT = 0
        RAISERROR('No matching records found for supervisor ID %d and cities %s with max results %d.', 16, 1, @supervisor_id, QUOTENAME(@external_system_id), @max_results);
END;
