```php
<?php

class SessionManager {
    private $tokenStore;
    private $apiUrl;
    private $expirationTime;

    public function __construct($tokenStore, $apiUrl, $expirationTime) {
        $this->tokenStore = $tokenStore;
        $this->apiUrl = $apiUrl;
        $this->expirationTime = $expirationTime;
    }

    public function generateToken($userId) {
        $timestamp = time();
        $token = hash('sha256', $userId . $timestamp);
        return array('token' => $token, 'timestamp' => $timestamp);
    }

    public function validateToken($token) {
        if (!$this->tokenStore->hasToken($token)) {
            return false;
        }
        $storedTimestamp = $this->tokenStore->getTokenTimestamp($token);
        if (abs(time() - $storedTimestamp) > $this->expirationTime) {
            return false;
        }
        return true;
    }

    public function invalidateToken($token) {
        $this->tokenStore->removeToken($token);
    }

    public function storeSessionData($token, $data) {
        $this->tokenStore->storeData($token, $data);
    }

    public function retrieveSessionData($token) {
        return $this->tokenStore->getData($token);
    }
}

class TokenStore {
    private $tokens = array();

    public function hasToken($token) {
        return array_key_exists($token, $this->tokens);
    }

    public function getTokenTimestamp($token) {
        return $this->tokens[$token]['timestamp'];
    }

    public function storeData($token, $data) {
        $this->tokens[$token] = $data;
    }

    public function getData($token) {
        if (!$this->hasToken($token)) {
            return null;
        }
        return $this->tokens[$token];
    }

    public function removeToken($token) {
        unset($this->tokens[$token]);
    }
}

class ApiClient {
    private $url;

    public function __construct($url) {
        $this->url = $url;
    }

    public function storeSessionData($token, $data) {
        $curl = curl_init($this->url . '/sessions/' . $token);
        curl_setopt_array($curl, array(
            CURLOPT_RETURNTRANSFER => true,
            CURLOPT_POST => true,
            CURLOPT_POSTFIELDS => json_encode($data)
        ));
        curl_exec($curl);
        curl_close($curl);
    }
}

// Usage example:
$apiUrl = 'https://example.com/session-api';
$expirationTime = 3600; // 1 hour
$tokenStore = new TokenStore();
$sessionManager = new SessionManager($tokenStore, $apiUrl, $expirationTime);

$userToken = $sessionManager->generateToken(123);
echo "Generated token: $userToken\n";

if ($sessionManager->validateToken($userToken)) {
    echo "Token is valid.\n";
} else {
    echo "Token is invalid.\n";
}

$sessionData = array('username' => 'john', 'email' => 'john@example.com');
$sessionManager->storeSessionData($userToken, $sessionData);
echo "Stored session data: " . json_encode($sessionData) . "\n";

// Validate and retrieve session data
$data = $sessionManager->retrieveSessionData($userToken);
echo "Retrieved session data: " . json_encode($data) . "\n";

// Invalidate token
$sessionManager->invalidateToken($userToken);

```

This code provides a basic implementation of the PHP-based session management system, including token generation, validation, and storage. It also includes an API client for storing session data with an external session management API.

Note that this is just one possible approach to implementing the requested features, and you may need to modify or extend it based on your specific requirements and constraints.']

