    void startBackgroundJobs() {
        while (true) {
            std::unique_lock<std::mutex> lock(mutex);
            condVar.wait_for(lock, std::chrono::seconds(1), [&] { return !jobQueue.isEmpty(); });
            jobQueue.dequeueJob();
