        sleep(2);  // wait for 2 seconds before retrying
    }

    // Identify states in the FSA that can be reached from the given last state
    StateList* new_states = (StateList*)malloc(sizeof(StateList));
    if (new_states == NULL) {
        printf("Error: unable to allocate memory for new state list.\n");
        return NULL;
    }
    new_states->states = (int*)calloc(num_states, sizeof(int));
    if (new_states->states == NULL) {
        free(new_states);
        printf("Error: unable to allocate memory for new state list.\n");
        return NULL;
    }
    new_states->num_states = num_states;

    // Update the 'next' pointer of the last state in the original list
    states[last_state]->next = new_states;

    return new_states;
}

