    time_t timestamp;
    int count;
    double sum;
} FilterState;

// Function to process transactions and calculate metrics
FilterState* process_transactions(FilterState* state, void* transaction) {
    // Deserialize the transaction
    Transaction* deserialized = deserialize_transaction(transaction);

    if (deserialized == NULL) {
        // Log an error and return a default transaction ID with low priority
        printf("Error deserializing transaction\n");
        deserialized->id = -1;
        deserialized->value = 0.0;
    }

    // Calculate the transaction's age
    time_t now = time(NULL);
    int age = difftime(now, state->timestamp);

    // Check if the transaction is within the rolling 3-second window
    if (age <= 3) {
        // Update metrics
        state->count++;
        state->sum += deserialized->value;

        // Calculate the weighted sum of transaction values
        double weighted_sum = (state->count / (double)(time(NULL) - state->timestamp)) * state->sum;
    }

    return state;
}

// Function to get the maximum weighted sum and corresponding transaction ID
int get_max_weighted_sum(FilterState* state, Transaction* deserialized) {
    // Calculate the weighted sum of transactions in the past 3 seconds
    double max_weighted_sum = state->sum / (double)(state->count);

    // Check if the transaction's weighted sum is higher than the maximum
    if ((deserialized->value * state->count) > max_weighted_sum) {
        return deserialized->id;
    } else {
        return -1; // Default transaction ID with low priority
    }
}

