class AttackDatabase {
public:
    // Simulated database operation
    void fetchAttackData(std::function<void(const std::string& attackName, const int cooldown)> callback) {
        // Simulate network latency and server unavailability
        for (int i = 0; i < 5 && !callback.empty(); ++i) {
            if (!callback.empty()) {
                callback("Fireball", 2);
            }
            std::this_thread::sleep_for(std::chrono::milliseconds(100));
        }
    }
};

class Character {
public:
    Character(const std::string& name, AttackDatabase* database) : name(name), database(database) {}
    void executeAttack() {
        // Simulated attack execution
        std::cout << name << " executed an attack.\n";
        std::this_thread::sleep_for(std::chrono::seconds(1));
    }
    void scheduleAttack() {
        // Get the next available attack from the database
        auto attackName = database->fetchNextAttack();
        if (attackName.empty()) {
            return;
        }
        executeAttack();
    }

private:
    std::string name;
    AttackDatabase* database;
};

class CharacterPool {
public:
    void addCharacter(const std::string& name) {
        characters[name] = new Character(name, &database);
    }
    void scheduleAllAttacks() {
        for (auto& character : characters) {
            character.second->scheduleAttack();
        }
    }

private:
    AttackDatabase database;
    std::map<std::string, Character*> characters;
};

class Scheduler {
public:
    Scheduler(AttackDatabase* database) : database(database), paused(false) {}
    void scheduleCharacters(std::vector<CharacterPool> pools) {
        for (auto& pool : pools) {
            pool.scheduleAllAttacks();
        }
    }
    void pause() {
        paused = true;
    }
    void resume() {
        paused = false;
    }

private:
    AttackDatabase* database;
    bool paused;
};

int main() {
    // Initialize the attack database
    AttackDatabase database;

    // Create a pool of characters
    CharacterPool characterPool;
    for (int i = 0; i < 10; ++i) {
        characterPool.addCharacter("Character " + std::to_string(i));
    }

    // Schedule all characters to execute attacks
    Scheduler scheduler(&database);
    scheduler.scheduleCharacters({characterPool});

    // Pause and resume attack scheduling
    scheduler.pause();
    for (int i = 0; i < 5; ++i) {
        std::cout << "Resuming attack scheduling.\n";
        scheduler.resume();
        std::this_thread::sleep_for(std::chrono::seconds(2));
    }
}
