using System;
using UnityEngine;

public abstract class DynamicValueProvider : IValueProvider
{
    private readonly RandomValue _randomValue = new RandomValue();

    public DynamicValueProvider(double minValue, double maxValue)
    {
        if (minValue > maxValue) throw new ArgumentException("Min value must be less than or equal to max value.");
        this.MinValue = minValue;
        this.MaxValue = maxValue;
    }

    public virtual double MinValue { get; }
    public virtual double MaxValue { get; }

    public float GetRandomFloat()
    {
        return (float)_randomValue.NextDouble(MinValue, MaxValue);
    }

    public int GetRandomInt()
    {
        return _randomValue.Next((int)MinValue, (int)MaxValue + 1);
    }

    public Vector3 GetRandomVector3()
    {
        return new Vector3(GetRandomFloat(), GetRandomFloat(), GetRandomFloat());
    }

    public Color GetRandomColor()
    {
        float r = GetRandomFloat();
        float g = GetRandomFloat();
        float b = GetRandomFloat();
        return new Color(r, g, b);
    }

    public T GetRandomValue<T>(Func<double, T> conversionFunction)
    {
        double randomValue = _randomValue.NextDouble(MinValue, MaxValue);
        return conversionFunction(randomValue);
    }
}
