            // Parse JSON content in the file
            json_t* root = json_load_file(file, 0);
            if (root != NULL) {
                json_object_foreach(root, key, val) {
                    callback(accumulatedValue, val->str);
                    accumulatedValue += strlen(val->str);
                    itemCount++;
                }
                json_decref(root);

                // Log the final count and metadata
                printf("Loaded %d items from local file '%s'\n", itemCount, filePath);
            } else {
                printf("Error parsing JSON in file '%s'\n", filePath);
            }

            fclose(file);
        } else {
            printf("Failed to open local file '%s'\n", filePath);
        }
    } else if (retryCount < 3) {
        // File not found locally, try fetching it remotely
        FILE* httpFile = fopen(filePath, "r");
        if (httpFile != NULL) {
            // Fetch the file and perform reduction asynchronously
            int itemCount = 0;
            int accumulatedValue = initialValue;

            // Parse JSON content in the file
            json_t* root = json_load_file(httpFile, 0);
            if (root != NULL) {
                json_object_foreach(root, key, val) {
                    callback(accumulatedValue, val->str);
                    accumulatedValue += strlen(val->str);
                    itemCount++;
                }
                json_decref(root);

                // Log the final count and metadata
                printf("Loaded %d items from remote file '%s'\n", itemCount, filePath);
                isRemoteFile = true;
            } else {
                printf("Error parsing JSON in remote file '%s'\n", filePath);
            }

            fclose(httpFile);
        } else {
            // Log the error and increment retry count
            printf("Failed to open remote file '%s' (attempt %d of 3)\n", filePath, retryCount + 1);
            if (++retryCount < 3) {
                sleep(2);  // Wait for a short period before retrying
                loadResourceBundle(filePath, localCacheDir, initialValue, callback);
            } else {
                printf("Permanent failure fetching file '%s'\n", filePath);
            }
        }
    }

    // Return the total number of items and metadata
    printf("Total items: %d\n", itemCount);
    if (isRemoteFile) {
        printf("Source: Remote\n");
    } else {
        printf("Source: Local\n");
    }
}
