#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <pthread.h>

#define MAX_FILENAMES 100
#define TIMESTAMP_FORMAT "%Y%m%d%H%M%S"
#define UNIQUE_ID_LENGTH 32
#define DIR_PATH_MAX_LENGTH 256

typedef struct {
    char path[DIR_PATH_MAX_LENGTH];
    pthread_mutex_t lock;
} DirPath;

void* rename_files(void* arg) {
    DirPath* dir_path = (DirPath*)arg;
    char filename[MAX_FILENAMES][DIR_PATH_MAX_LENGTH];
    int i, count = 0;

    // Read file list from directory
    DIR* dir = opendir(dir_path->path);
    if (!dir) {
        printf("Error opening directory\n");
        return NULL;
    }

    struct dirent* entry;
    while ((entry = readdir(dir)) != NULL) {
        strcpy(filename[count], entry->d_name);
        count++;
    }
    closedir(dir);

    for (i = 0; i < count; i++) {
        // Get unique identifier and timestamp
        char* timestamp = ctime(&time(0));
        sprintf(timestamp, TIMESTAMP_FORMAT, gethostname());
        char unique_id[UNIQUE_ID_LENGTH];
        srand(time(0));
        for (int j = 0; j < UNIQUE_ID_LENGTH - 1; j++) {
            unique_id[j] = (char)(rand() % 26 + 'a');
        }
        unique_id[UNIQUE_ID_LENGTH - 1] = '\0';

        // Append unique identifier and timestamp to filename
        char new_filename[DIR_PATH_MAX_LENGTH];
        sprintf(new_filename, "%s_%s_%s", unique_id, timestamp, filename[i]);

        // Rename file atomically using flock()
        int fd = open(filename[i], O_RDWR);
        if (fd < 0) {
            printf("Error opening file\n");
            continue;
        }
        fcntl(fd, F_SETLK, 0);
        renameat(AT_FDCWD, filename[i], AT_FDCWD, new_filename);
        close(fd);

        // Handle errors and system failures
        if (errno != 0) {
            printf("Error renaming file: %s\n", strerror(errno));
        }
    }

    return NULL;
}

int main(int argc, char* argv[]) {
    DirPath dir_path;

    // Set directory path from command-line arguments or user input
    if (argc > 1) {
        strcpy(dir_path.path, argv[1]);
    } else {
        printf("Enter directory path: ");
        fgets(dir_path.path, DIR_PATH_MAX_LENGTH, stdin);
        dir_path.path[strcspn(dir_path.path, "\n")] = '\0';
    }

    pthread_t thread;
    pthread_create(&thread, NULL, rename_files, &dir_path);

    // Monitor ongoing operations and handle system failures
    while (1) {
        sleep(1);
    }

    return 0;
}
