    }
};

class InitializationRoutine {
public:
    bool init(Logger& logger, NetworkInterface& network, StorageHandler& storage, Factory& factory) {
        std::mutex mtx;
        std::condition_variable cv;

        // start asynchronous operations
        auto logThread = [logger, &cv]() {
            for(int i = 0; i < 5; ++i) {
                logger.log(1, "Async log message");
                std::this_thread::sleep_for(std::chrono::milliseconds(200));
                cv.notify_all();
            }
        };
        auto networkThread = [network, &cv]() {
            for(int i = 0; i < 3; ++i) {
                if(!network.establishConnection("server.com", 1000)) return false;
                cv.notify_all();
            }
            return true;
        };
        auto storageThread = [storage, &cv]() {
            std::string data;
            for(int i = 0; i < 2; ++i) {
                if(!storage.readFromFile("file.txt", data)) return false;
                cv.notify_all();
            }
            return true;
        };
        auto factoryThread = [factory, &cv]() {
            bool success = true;
            for(int i = 0; i < 4; ++i) {
                if(!factory.createObject("ComplexObject", 3)) success = false;
                cv.notify_all();
            }
            return success;
        };

        std::thread logThreadObj(logThread);
        std::thread networkThreadObj(networkThread);
        std::thread storageThreadObj(storageThread);
        std::thread factoryThreadObj(factoryThread);

        // wait for asynchronous operations to complete
        {
            std::unique_lock<std::mutex> lock(mtx);
            cv.wait_for(lock, std::chrono::seconds(10));
        }

        // handle any failures or exceptions
        if(!networkThreadObj.joinable()) return false;
        if(!storageThreadObj.joinable()) return false;
        if(!factoryThreadObj.joinable()) return false;

        return true;
    }
};

int main() {
    Logger logger;
    NetworkInterface network;
    StorageHandler storage;
    Factory factory;
    InitializationRoutine initRtn;

    bool result = initRtn.init(logger, network, storage, factory);
    std::cout << "Initialization Routine Result: " << (result ? "Success" : "Failure") << "\n";
    return 0;
}

