using System;
using System.IO;
using System.Linq;
using System.Security.Cryptography;
using System.Text;

namespace TripleDESModule
{
    public class TripleDESCrypto
    {
        private const int BlockSize = 64;
        private const int KeySize = 192; // Triple DES key size in bits

        public static string Encrypt(int[] integers, byte[] key, byte[] iv)
        {
            using (var des3 = new DESCryptoServiceProvider())
            {
                des3.Key = key;
                des3.IV = iv;

                var encryptedBytes = Encrypt(des3, integers);
                return Convert.ToBase64String(encryptedBytes);
            }
        }

        public static int[][] Decrypt(string base64EncodedString, byte[] key, byte[] iv)
        {
            using (var des3 = new DESCryptoServiceProvider())
            {
                des3.Key = key;
                des3.IV = iv;

                var decryptedBytes = Convert.FromBase64String(base64EncodedString);
                return Decrypt(des3, decryptedBytes).ToArray();
            }
        }

        private static byte[] Encrypt(DESCryptoServiceProvider des3, int[] integers)
        {
            using (var ms = new MemoryStream())
            {
                using (var cs = new CryptoStream(ms, des3.CreateEncryptor(), CryptoStreamMode.Write))
                {
                    foreach (var integer in integers)
                    {
                        var bytes = BitConverter.GetBytes(integer);
                        cs.Write(bytes, 0, BlockSize / 8); // Write data in blocks
                    }
                }

                return ms.ToArray();
            }
        }

        private static int[] Decrypt(DESCryptoServiceProvider des3, byte[] encryptedBytes)
        {
            using (var ms = new MemoryStream())
            {
                using (var cs = new CryptoStream(ms, des3.CreateDecryptor(), CryptoStreamMode.Write))
                {
                    var buffer = new byte[BlockSize / 8];
                    int bytesRead;

                    while ((bytesRead = cs.Read(buffer, 0, buffer.Length)) > 0)
                    {
                        var integerBytes = buffer.Take(bytesRead).ToArray();
                        ms.Write(integerBytes, 0, integerBytes.Length);
                    }
                }

                return Enumerable.Range(0, (int)ms.Length / sizeof(int))
                    .Select(i => BitConverter.ToInt32(ms.GetBuffer(), i * sizeof(int)))
                    .ToArray();
            }
        }
    }
}
