using Microsoft.Extensions.Caching.Distributed;

namespace Md5Service
{
    public class Md5Service
    {
        private readonly IDistributedCache _cache;
        private readonly IExternalApi _externalApi;

        public Md5Service(IDistributedCache cache, IExternalApi externalApi)
        {
            _cache = cache;
            _externalApi = externalApi;
        }

        public async Task<string> ComputeMd5Hash(string input)
        {
            if (string.IsNullOrEmpty(input))
                throw new ArgumentException("Input cannot be null or empty.");

            string cachedHash;
            if (_cache.TryGetValue(input, out cachedHash))
                return cachedHash;

            using (var md5 = MD5.Create())
            {
                var bytes = Encoding.UTF8.GetBytes(input);
                var hashBytes = md5.ComputeHash(bytes);

                // Cache the result
                _cache.SetString(input, Convert.ToBase64String(hashBytes));

                // Verify the hash against external API if not cached
                await VerifyMd5HashAsync(input);
            }

            return Convert.ToBase64String(md5.HashValue);
        }

        private async Task VerifyMd5HashAsync(string input)
        {
            try
            {
                var cacheMiss = _cache.Get<string>(input, 300); // 5 minutes TTL
                if (string.IsNullOrEmpty(cacheMiss))
                {
                    await _externalApi.VerifyMd5Hash(input);
                }
            }
            catch (Exception ex)
            {
                // Handle API errors gracefully with exponential backoff and rate limiting
                await Task.Delay(1000); // initial delay in milliseconds
                for (int i = 1; i <= 3; i++)
                {
                    try
                    {
                        await _externalApi.VerifyMd5Hash(input);
                        break;
                    }
                    catch (Exception)
                    {
                        await Task.Delay(Math.Pow(2, i) * 1000); // exponential backoff
                    }
                }
            }
        }
    }

    public interface IExternalApi
    {
        Task VerifyMd5Hash(string input);
    }

    public class ExternalApi : IExternalApi
    {
        private readonly HttpClient _httpClient;

        public ExternalApi(HttpClient httpClient)
        {
            _httpClient = httpClient;
        }

        public async Task VerifyMd5Hash(string input)
        {
            // Implement your external API call logic here
            await _httpClient.GetAsync("https://your-api.com/verify-md5-hash");
        }
    }
}
