using System;
using System.IO;
using System.Threading.Tasks;
using Newtonsoft.Json;

namespace BinaryDatasetService
{
    public class Service : IService
    {
        private readonly ILogger _logger;
        private readonly IApiClient _apiClient;
        private readonly IFileLoader _fileLoader;

        public Service(ILogger logger, IApiClient apiClient, IFileLoader fileLoader)
        {
            _logger = logger;
            _apiClient = apiClient;
            _fileLoader = fileLoader;
        }

        public async Task UpdateDatasetAsync()
        {
            try
            {
                while (true)
                {
                    await LoadAndUpdateDatasetAsync();
                    await Task.Delay(1000); // Periodic updates every 1 second
                }
            }
            catch (Exception ex)
            {
                _logger.LogError(ex, "Error updating dataset");
            }
        }

        private async Task LoadAndUpdateDatasetAsync()
        {
            try
            {
                string[] files = _fileLoader.GetFiles();
                foreach (string file in files)
                {
                    using (FileStream fs = File.OpenRead(file))
                    {
                        byte[] buffer = new byte[fs.Length];
                        await fs.ReadAsync(buffer, 0, buffer.Length);
                        BinaryDataset dataset = JsonConvert.DeserializeObject<BinaryDataset>(buffer);

                        // Retrieve metadata from API
                        MetadataResponse metadata = await _apiClient.GetMetadataAsync(dataset.Id);

                        // Update dataset with metadata
                        dataset.Update(metadata);

                        // Deserialize and store updated data in memory
                        using (MemoryStream ms = new MemoryStream())
                        {
                            using (StreamWriter writer = new StreamWriter(ms))
                            {
                                writer.Write(JsonConvert.SerializeObject(dataset));
                            }
                            await File.WriteAllBytesAsync(file, ms.ToArray());
                        }
                    }
                }
            }
            catch (Exception ex)
            {
                _logger.LogError(ex, "Error loading and updating dataset");
            }
        }
    }

    public interface IApiClient
    {
        Task<MetadataResponse> GetMetadataAsync(string id);
    }

    public class ApiClient : IApiClient
    {
        private readonly HttpClient _httpClient;

        public ApiClient(HttpClient httpClient)
        {
            _httpClient = httpClient;
        }

        public async Task<MetadataResponse> GetMetadataAsync(string id)
        {
            try
            {
                HttpResponseMessage response = await _httpClient.GetAsync($"metadata/{id}");
                response.EnsureSuccessStatusCode();
                string responseBody = await response.Content.ReadAsStringAsync();
                return JsonConvert.DeserializeObject<MetadataResponse>(responseBody);
            }
            catch (Exception ex)
            {
                throw new Exception("Error retrieving metadata", ex);
            }
        }
    }

    public interface IFileLoader
    {
        string[] GetFiles();
    }

    public class FileLoader : IFileLoader
    {
        private readonly ILogger _logger;

        public FileLoader(ILogger logger)
        {
