  try {
    await uploadFile(file);
  } catch (error) {
    console.error('Error uploading file:', error);
    // Retry with exponential backoff
    setTimeout(() => rateLimit(file, attempts + 1), Math.pow(2, attempts) * 1000);
  }
}

