        public byte[] encryptAttributes() {
            // Get the KMS key ID for AES-256 encryption
            String aesKeyID = kmsClient.getKeyId("AES-256");

            // Get the KMS key ID for Camellia-192 encryption
            String camelliaKeyID = kmsClient.getKeyId("Camellia-192");

            // Encrypt attributes using AES-256 and Camellia-192 algorithms
            byte[] encryptedAttributes = encryptAttributes(aesKeyID, camelliaKeyID);

            return encryptedAttributes;
        }

        // Decrypt vertex attributes using HMAC-SHA256 for data integrity
        public void decryptAttributes(byte[] encryptedAttributes) {
            // Get the KMS key ID for HMAC-SHA256 decryption
            String hmacSha256KeyID = kmsClient.getKeyId("HMAC-SHA256");

            // Decrypt attributes using HMAC-SHA256 algorithm
            byte[] decryptedAttributes = decryptAttributes(encryptedAttributes, hmacSha256KeyID);

            // Update vertex attributes with decrypted values
            updateAttributes(decryptedAttributes);
        }

        // Update vertex attributes with decrypted values
        private void updateAttributes(byte[] decryptedAttributes) {
            this.attributes.clear();
            // Add decrypted attribute to vertex
