                users.extend(get_users_by_username(&client, api_key, &username)?);
            }
            "email" => {
                let email = get_arg_value(&args, 1);
                users.extend(get_users_by_email(&client, api_key, &email)?);
            }
            _ => return Err(reqwest::Error::new("Invalid argument")),
        }
    }
    Ok(users)
}

