import json
from abc import ABCMeta, abstractmethod
from functools import lru_cache
from logging import getLogger
from threading import Lock
from typing import Any, Dict, List, TypeVar, Generic

T = TypeVar('T')

class DataModel(metaclass=ABCMeta):
    @abstractmethod
    def from_json(self, json_obj: dict) -> None:
        pass

class JsonParser(Generic[T]):
    _registry: Dict[str, 'JsonFactory'] = {}
    _logger = getLogger()
    _mutex = Lock()

    @classmethod
    def register(cls, factory_id: str, factory_func: callable) -> None:
        with cls._mutex:
            if factory_id in cls._registry:
                raise ValueError(f"Duplicate registration for {factory_id}")
            cls._registry[factory_id] = JsonFactory(factory_func)

    @classmethod
    @lru_cache(maxsize=None)
    def get_parser(cls, data_model: str) -> 'JsonParser[T]':
        if not data_model:
            raise ValueError("Invalid data model")
        factory = cls._registry.get(data_model)
        if not factory:
            raise ValueError(f"Unknown data model {data_model}")
        return JsonFactory(factory)

class JsonFactory(Generic[T]):
    def __init__(self, factory_func: callable) -> None:
        self.factory_func = factory_func

    def from_json(self, json_obj: dict) -> T:
        try:
            obj = self.factory_func(json_obj)
            return obj
        except Exception as e:
            self._logger.error(f"Error parsing JSON: {str(e)}")
            raise

class JsonLoader(Generic[T]):
    def __init__(self, data_model_id: str) -> None:
        self.data_model_id = data_model_id

    @classmethod
    @lru_cache(maxsize=None)
    def load(cls, json_data: str) -> T:
        try:
            return cls(data_model_id=cls.get_parser(json.loads(json_data)).from_json({'id': json_data})).factory_func(None)
        except Exception as e:
            raise ValueError(f"Invalid JSON or data model {json_data}")

class JsonWriter(Generic[T]):
    def __init__(self, data_model: str) -> None:
        self.data_model = data_model

    def to_json(self, obj: T) -> str:
        if not isinstance(obj, DataModel):
            raise ValueError(f"Invalid data model for {obj}")
        return json.dumps({'id': obj.__class__.__name__}, default=lambda o: o.to_dict())

def load_json(data_model_id: str, json_data: str) -> Any:
    return JsonLoader.load(json_data)

def to_json(obj: DataModel) -> str:
    return JsonWriter(obj.__class__.__name__).to_json(obj)
```']

