import hashlib
from typing import Dict, Any
from datetime import datetime
import requests

class CloudStorageService:
    def __init__(self):
        self.providers = {
            'provider1': {'url': 'https://storage-provider-1.com', 'api_key': 'your_api_key'},
            'provider2': {'url': 'https://storage-provider-2.com', 'api_key': 'your_api_key'}
        }
        self.hashing_service_url = 'https://hashing-service-api.com'

    def store_file(self, file_path: str, cloud_provider: str) -> Dict[str, Any]:
        provider = self.providers[cloud_provider]
        md5_hash = self.get_md5_hash(file_path)
        sha256_hash = self.get_sha256_hash(file_path)

        upload_request = requests.post(
            f'{provider["url"]}/upload',
            headers={'Authorization': f'Bearer {md5_hash}', 'Content-Type': 'application/octet-stream'},
            data=open(file_path, 'rb')
        )
        if upload_request.status_code != 201:
            raise Exception(f"Failed to store file: {upload_request.text}")

        return {'file_id': upload_request.json()['file_id'], 'md5_hash': md5_hash, 'sha256_hash': sha256_hash}

    def get_md5_hash(self, file_path: str) -> str:
        with open(file_path, 'rb') as f:
            return hashlib.md5(f.read()).hexdigest()

    def get_sha256_hash(self, file_path: str) -> str:
        with open(file_path, 'rb') as f:
            return hashlib.sha256(f.read()).hexdigest()

    def validate_oauth_token(self, token_json: Dict[str, Any]) -> bool:
        required_fields = ['access_token', 'expires_in', 'token_type']
        if any(field not in token_json for field in required_fields):
            return False

        if token_json['token_type'] != 'Bearer':
            return False

        # validate expires_in
        if not isinstance(token_json['expires_in'], int) or token_json['expires_in'] < 1:
            return False

        return True

    def get_hashing_service(self) -> requests.Session:
        return requests.Session()

class FileHasher:
    def __init__(self, cloud_storage_service: CloudStorageService):
        self.cloud_storage_service = cloud_storage_service
        self.hashing_service = self.cloud_storage_service.get_hashing_service()

    def calculate_hashes(self, file_path: str) -> Dict[str, Any]:
        md5_hash = self.cloud_storage_service.get_md5_hash(file_path)
        sha256_hash = self.cloud_storage_service.get_sha256_hash(file_path)

        return {'md5_hash': md5_hash, 'sha256_hash': sha256_hash}

    def validate_hashes(self, file_path: str) -> bool:
        hashes = self.calculate_hashes(file_path)
        # validate hashes against hashing service
        response = self.hashing_service.post('validate', data=hashes)
        if response.status_code != 200:
            return False

        return True

class LoggingService:
