#include <iostream>
#include <string>
#include <nlohmann/json.hpp>

using json = nlohmann::json;

bool validateOAuthToken(const std::string& accessTokenJson) {
    json token = json::parse(accessTokenJson);
    if (!token.contains("access_token") || !token["access_token"].is_string()) {
        return false;
    }

    if (!token.contains("expires_in") || !token["expires_in"].is_number_integer()) {
        return false;
    }

    if (!token.contains("token_type") || !token["token_type"].is_string()) {
        return false;
    }

    if (token["token_type"] != "Bearer") {
        return false;

    return true;
}

int main() {
    std::string accessTokenJson = R"({
        "access_token": "your_access_token",
        "expires_in": 3600,
        "token_type": "Bearer"
    })";

    if (!validateOAuthToken(accessTokenJson)) {
        std::cout << "Invalid access token." << std::endl;
    } else {
        std::cout << "Access token is valid." << std::endl;
    }
}
