# Initialize the thread pool for concurrent uploads
thread_pool = ThreadPoolExecutor(max_workers=5)

@app.route('/upload', methods=['POST'])
def handle_upload():
    if request.method == 'POST':
        # Extract file data from the request
        file_data = request.files['file']

        # Validate file extension and size
        if file_data.filename not in ALLOWED_EXTENSIONS or file_data.size > 1048576:
            return jsonify({'error': 'Invalid file type or size'}), 400

        # Compute MD5 and SHA-256 hashes using streaming algorithms
        md5_hash = hashlib.md5(file_data.stream).hexdigest()
        sha256_hash = hashlib.sha256(file_data.stream).hexdigest()

        # Store the file metadata securely
        file_metadata = {'id': str(uuid.uuid4()), 'name': file_data.filename, 'size': file_data.size, 
