const { Transform, PassThrough } = require('stream');
const fs = require('fs');
const path = require('path');
const zlib = require('zlib');
const bunyan = require('bunyan');

class DataStreamer {
  constructor(options) {
    this.options = options;
    this.logger = bunyan.createLogger({ name: 'DataStreamer', level: options.logLevel });
    this.incomingStream = new PassThrough();
    this.outgoingStream = new PassThrough();

    // Initialize buffering and processing
    this.currentBuffer = Buffer.alloc(0);
    this.processedBytes = 0;
    this.errors = [];

    // Set up logging for data throughput and error rates
    this.logger.level(options.logLevel);
    this.incomingStream.pipe(this.getLoggerStream());

    // Start the streaming pipeline
    this.incomingStream.pipe(this.bufferingTransformer())
      .pipe(this.processingTransformer())
      .pipe(this.outgoingStream);

    this.outgoingStream.on('data', (chunk) => {
      this.logger.info(`Outgoing data chunk: ${chunk.toString()}`);
    });

    this.outgoingStream.on('error', (err) => {
      this.logger.error(`Error in outgoing stream: ${err.message}`);
      this.errors.push(err);
    });
  }

  getLoggerStream() {
    const loggerStream = new Transform({
      transform(chunk, encoding, callback) {
        if (chunk.toString().includes('data')) {
          this.logger.info(`Incoming data chunk: ${chunk.toString()}`);
        }
        callback(null, chunk);
      },
    });

    return loggerStream;
  }

  bufferingTransformer() {
    const bufferingStream = new Transform({
      transform(chunk, encoding, callback) {
        if (!this.currentBuffer) {
          this.currentBuffer = Buffer.alloc(0);
        }

        // Check for edge case: negative byte count
        let byteCount = parseInt(this.options.byteCount);
        if (isNaN(byteCount)) {
          throw new Error('Invalid byte count');
        }

        // Copy specified number of bytes into a new buffer without altering the source data
        const processedChunk = chunk.slice(0, Math.min(chunk.length, byteCount));

        // Update current buffer and processed bytes
        this.currentBuffer = Buffer.concat([this.currentBuffer, processedChunk]);
        this.processedBytes += processedChunk.length;

        callback(null, chunk);
      },
    });

    return bufferingStream;
  }

  processingTransformer() {
    const processingStream = new Transform({
      transform(chunk, encoding, callback) {
        // Handle edge case: incomplete data stream
        if (!this.currentBuffer && chunk.length === 0) {
          this.outgoingStream.emit('end');
          callback();
          return;
        }

        // Process the buffered data and send it downstream
        const processedData = zlib.inflateSync(this.currentBuffer);
        this.outgoingStream.write(processedData);

        // Reset current buffer for new chunks
        this.currentBuffer = Buffer.alloc(0);

        callback();
      },
    });

    return processingStream;
  }
}

// Example usage:
const options = {
  logLevel: 'debug',
  byteCount: 1024,
};

const dataStreamer = new DataStreamer(options);
fs.createReadStream('input.txt')
  .pipe(dataStreamer.incomingStream)
  .pipe(fs.createWriteStream('output.txt'));

