FSA *fetch_fsa(char *api_url) {
    CURL *curl;
    CURLcode res;
    struct curl_slist *headers = NULL;
    char errorbuf[CURL_ERROR_SIZE];
    size_t bytes_read;
    FSA *fsa = (FSA *)malloc(sizeof(FSA));

    headers = curl_slist_make("Accept: application/json");

    curl_global_init(CURL_GLOBAL_DEFAULT);
    curl = curl_easy_init();
    if(curl) {
        curl_easy_setopt(curl, CURLOPT_URL, api_url);
        curl_easy_setopt(curl, CURLOPT_WRITEFUNCTION, write_memory);
        curl_easy_setopt(curl, CURLOPT_ERRORBUFFER, errorbuf);
        curl_easy_setopt(curl, CURLOPT_WRITEDATA, &fsa->transitions[0]);
        res = curl_easy_perform(headers);

        if(res != CURLE_OK) {
            printf("curl_easy_perform() failed: %s\n", 
                   curl_easy_strerror(res));
        }

        free(errorbuf);
        curl_slist_free_all(headers);
    } else {
        printf("curl_easy_init() failed!\n");
    }

    return fsa;
}

int main(int argc, char const *argv[]) {
    FSA *fsa = fetch_fsa("http://api.example.com/fsa");

    // Process the fetched FSA data here...

