['Here is a Python-based RESTful API for real-time personalized recommendations:

**Python (FastAPI)**
```python
from fastapi import FastAPI, HTTPException
from pydantic import BaseModel
import asyncio
import aioredis
from redis import StrictRedis

app = FastAPI()

# Redis connection settings
REDIS_HOST = 'localhost'
REDIS_PORT = 6379
REDIS_DB = 0

# Recommendation engine integrations
RECOMMENDATION_ENGINES = {
    'engine1': 'https://api.engine1.com/recommendations',
    'engine2': 'https://api.engine2.com/recs'
}

class Product(BaseModel):
    id: str
    name: str
    description: str

class Recommendation(BaseModel):
    product_id: str
    recommendation_score: float

@app.get("/recommendations/{user_id}")
async def get_recommendations(user_id: int):
    # Connect to Redis
    redis = StrictRedis(host=REDIS_HOST, port=REDIS_PORT, db=REDIS_DB)

    # Check if user has a cached recommendation
    cached_rec = await redis.hgetall(f"user:{user_id}:recommendations")
    if cached_rec:
        return [Recommendation(**rec) for rec in cached_rec.items()]

    # Get product catalog API response
    products_response = requests.get('https://api.product-catalog.com/products')
    products = [Product(**prod) for prod in products_response.json()]

    # Integrate with recommendation engines (async)
    recommendations = []
    for engine in RECOMMENDATION_ENGINES:
        async def get_recs():
            response = await requests.post(RECOMMENDATION_ENGINES[engine], json={'user_id': user_id})
            return [Recommendation(**rec) for rec in response.json()]

        recomms = await asyncio.gather(*[get_recs()])
        recommendations.extend(recomms)

    # Cache the recommendation results
    await redis.hmset(f"user:{user_id}:recommendations", {rec.product_id: {'product_name': prod.name, 'recommendation_score': rec.recommendation_score} for rec in recommendations})

    return [Recommendation(**rec) for rec in recommendations]
```

