		for _, engine := range recommendationEngines {
			go func(engine string) {
				resp, err := http.Post("https://"+engine+"/recommendations", "application/json", strings.NewReader(`{"user_id": `+userID+`}`))
				if err != nil {
					log.Println(err)
					return
				}
				defer resp.Body.Close()
				var recs []Recommendation
				err = json.NewDecoder(resp.Body).Decode(&recs)
				if err != nil {
					log.Println(err)
					return
				}
				recomms = append(recomms, recs...)
			}(engine)
		}

		for _ = range recomms {
			client.HMSet(cTx, "user:"+userID+":recommendations", func() (interface{}, error) {
				return map[string]interface{}{"product_id": recomms[0].ProductID, "recommendation_score": recomms[0].Score}, nil
			})
		}

		c.JSON(200, recomms)
	}
