const express = require('express');
const redis = require('redis');
const { Pool } = require('pg');

const app = express();

// Redis connection settings
const REDIS_HOST = 'localhost';
const REDIS_PORT = 6379;
const REDIS_DB = 0;

// Recommendation engine integrations
const RECOMMENDATION_ENGINES = {
    'engine1': 'https://api.engine1.com/recommendations',
    'engine2': 'https://api.engine2.com/recs'
};

app.get('/recommendations/:user_id', async (req, res) => {
    const user_id = req.params.user_id;
    const client = redis.createClient({ host: REDIS_HOST, port: REDIS_PORT, db: REDIS_DB });

    // Check if user has a cached recommendation
    try {
        const cached_rec = await client.hgetall(`user:${user_id}:recommendations`);
        if (cached_rec) {
            res.json(cached_rec);
            return;
        }
    } catch (error) {
        console.error(error);
    }

    // Get product catalog API response
    const products_response = await fetch('https://api.product-catalog.com/products');
    const products = await products_response.json();

    // Integrate with recommendation engines (async)
    const recommendations = [];
    for (const engine in RECOMMENDATION_ENGINES) {
        try {
            const response = await fetch(RECOMMENDATION_ENGINES[engine], {
                method: 'POST',
                headers: { 'Content-Type': 'application/json' },
                body: JSON.stringify({ user_id })
            });
            const recs = await response.json();
            recommendations.push(...recs);
        } catch (error) {
            console.error(error);
        }
    }

    // Cache the recommendation results
    try {
        await client.hmset(`user:${user_id}:recommendations`, recommendations.map(rec => ({ [rec.product_id]: { product_name: products.find(p => p.id === rec.product_id).name, recommendation_score: rec.recommendation_score } })));
    } catch (error) {
        console.error(error);
    }

    res.json(recommendations);
});
