        const char* file_path;
        const char* bucket_name;
    } *data = (struct{}*)arg;

    if(cloud_upload(*data->file_path, *data->bucket_name) == -1) {
        perror("cloud upload");
        return NULL;
    }

    printf("Archived file: %s -> %s\n", *data->file_path, *data->bucket_name);

    free(data);
    return NULL;
}

// Main program
int main(int argc, char** argv) {
    pthread_t threads[argc];

    DIR* dir = opendir(argv[1]);
    if(dir == NULL) {
        perror("opendir");
        return -1;
    }

    struct dirent* dent;
    while((dent = readdir(dir)) != NULL) {
        const char* file_path = dent->d_name;

        // Configure policy based on file attributes
        int policy = 0; // rename, move, archive

        if(policy == RENAME) {
            pthread_create(&threads[0], NULL, rename_file, (void*)malloc(sizeof(struct{const char* old_path; const char* new_path;})));
        } else if(policy == MOVE) {
            pthread_create(&threads[1], NULL, move_file, (void*)malloc(sizeof(struct{const char* old_path; const char* new_path;})));
        } else if(policy == ARCHIVE) {
            pthread_create(&threads[2], NULL, archive_file, (void*)malloc(sizeof(struct{const char* file_path; const char* bucket_name;})));
        }

        closedir(dir);
    }

    for(int i = 0; i < argc; i++) {
        pthread_join(threads[i], NULL);
    }

    return 0;
}
