// Task queue implementation using std::queue and std::mutex
class TaskQueue {
public:
    void enqueue(const std::string& task) {
        std::unique_lock<std::mutex> lock(queue_mutex_);
        task_queue_.emplace(task);
        cv_.notify_one();
    }

    bool dequeue(std::string& task) {
        std::unique_lock<std::mutex> lock(queue_mutex_);
        cv_.wait(lock, [this] { return !task_queue_.empty(); });
        if (!task_queue_.empty()) {
            task = task_queue_.front();
            task_queue_.pop();
            return true;
        }
        return false;
    }

private:
    std::queue<std::string> task_queue_;
    std::mutex queue_mutex_;
    std::condition_variable cv_;
};

// Transaction processing worker thread pool
class TransactionProcessor {
public:
    void start(int num_workers) {
        for (int i = 0; i < num_workers; ++i) {
            workers_.emplace_back([this] { process_transactions(); });
        }
    }

    void enqueue_transaction(const std::string& transaction_data) {
        task_queue_.enqueue(transaction_data);
