#include <iostream>
#include <thread>
#include <mutex>
#include <condition_variable>
#include <chrono>

class RateLimiter {
public:
    explicit RateLimiter(size_t maxRequestsPerSecond) : maxRequestsPerSecond_(maxRequestsPerSecond),
        requestsMade_(0), lastRequestTime_(std::chrono::steady_clock::now()) {}

    bool tryAcquire() {
        std::unique_lock<std::mutex> lock(mutex_);
        while (requestsMade_ >= maxRequestsPerSecond_) {
            if (cv_.wait_for(lock, std::chrono::seconds(1)) <= std::chrono::nanoseconds(0)) {
                return false;
            }
        }
        requestsMade_++;
        lastRequestTime_ = std::chrono::steady_clock::now();
        lock.unlock();
        cv_.notify_all();
        return true;
    }

    void reset() {
        requestsMade_ = 0;
        lastRequestTime_ = std::chrono::steady_clock::now();
    }

private:
    size_t maxRequestsPerSecond_;
    size_t requestsMade_;
    std::chrono::time_point<std::chrono::steady_clock> lastRequestTime_;
    mutable std::mutex mutex_;
    std::condition_variable cv_;
};

class RateLimitingService {
public:
    explicit RateLimitingService(size_t maxRequestsPerSecond) : rateLimiter_(maxRequestsPerSecond) {}

    void run() {
        while (true) {
            if (rateLimiter_.tryAcquire()) {
                // Process request
                std::this_thread::sleep_for(std::chrono::microseconds(10));
                rateLimiter_.reset();
            } else {
                // Rate limit exceeded, wait and try again
                std::this_thread::sleep_for(std::chrono::milliseconds(1000));
            }
        }
    }

private:
    RateLimiter rateLimiter_;
};

class ExternalDependencyAPI {
public:
    bool query() {
        // Simulate API request with occasional outages
        if (std::rand() % 2 == 1) {
            return false;
        }
        return true;
    }
};

int main() {
    RateLimitingService rateLimiterService(100); // 100 requests per second

    std::thread rateLimiterThread(&RateLimitingService::run, &rateLimiterService);

    while (true) {
        if (ExternalDependencyAPI().query()) {
            // Process API response
            rateLimiterService.reset();
        } else {
            // API unavailable, wait and try again
            std::this_thread::sleep_for(std::chrono::milliseconds(1000));
        }
    }

    return 0;
}
