    int size;
    int front, rear;
} Queue;

// Function to initialize a new queue
void init_queue(Queue* q) {
    q->size = 10; // Initial capacity of the queue
    q->front = q->rear = 0;
    q->data = (NFAPI_L2_RX_PDU_T*)malloc(q->size * sizeof(NFAPI_L2_RX_PDU_T));
}

// Function to enqueue a new data item
void enqueue(Queue* q, NFAPI_L2_RX_PDU_T* data) {
    if ((q->rear + 1) % q->size == q->front) {
        printf("Queue is full. Increase the size.\n");
        return;
    }
    q->data[q->rear] = *data;
    q->rear = (q->rear + 1) % q->size;
}

// Function to dequeue an item from the queue
NFAPI_L2_RX_PDU_T* dequeue(Queue* q) {
    NFAPI_L2_RX_PDU_T* data;
    if (q->front == q->rear) {
        printf("Queue is empty.\n");
        return NULL;
    }
    data = &q->data[q->front];
    q->front = (q->front + 1) % q->size;
    return data;
}

// Function to initialize a new L2_RX_DATA structure
void init_l2_rx_data(L2_RX_DATA** l2_rx_data, uint32_t size) {
