    file = request.files['file']
    filename = secure_filename(file.filename)
    file.save(os.path.join(app.config['UPLOAD_FOLDER'], filename))
    return jsonify({'message': 'File uploaded successfully'})

@app.route('/retrieve/<int:document_id>', methods=['GET'])
@jwt_required
def retrieve_document(document_id):
    document = Document.query.get(document_id)
    if not document:
        return jsonify({'error': 'Document not found'}), 404
    return jsonify({'name': document.name, 'content': document.content})

@app.route('/batch_upload', methods=['POST'])
@jwt_required
def batch_upload():
    files = request.files.getlist('files')
    for file in files:
        filename = secure_filename(file.filename)
        file.save(os.path.join(app.config['UPLOAD_FOLDER'], filename))
    return jsonify({'message': 'Files uploaded successfully'})

@app.route('/validate/<int:document_id>', methods=['GET'])
@jwt_required
def validate_document(document_id):
