    pthread_mutex_lock(&cache->lock);
    size_t capacity = cache->capacity;
    CacheEntry** entries = cache->entries;
    for (size_t i = 0; i < capacity; i++) {
        if (entries[i] && strcmp(entries[i]->hostname, hostname) == 0) {
            strcpy(ip_address, entries[i]->ip_address);
            pthread_mutex_unlock(&cache->lock);
            return 1; // Cache hit
        }
    }
    pthread_mutex_unlock(&cache->lock);
    return -1; // Cache miss
}

// Implement the health-check mechanism to monitor the external DNS provider's availability
