import java.util.concurrent.Executors;
import java.util.concurrent.ScheduledExecutorService;

import javax.servlet.http.HttpServletRequest;
import javax.servlet.http.HttpServletResponse;
import org.springframework.beans.factory.annotation.Autowired;
import org.springframework.context.annotation.Bean;
import org.springframework.context.annotation.Configuration;
import org.springframework.security.authentication.AuthenticationManager;
import org.springframework.security.config.BeanDefinitions;
import org.springframework.security.config.SecurityConfigurer;
import org.springframework.security.config.annotation.authentication.builders.AuthenticationManagerBuilder;
import org.springframework.security.config.annotation.web.builders.HttpSecurity;
import org.springframework.security.config.annotation.web.configuration.EnableWebSecurity;
import org.springframework.security.config.annotation.web.configuration.WebSecurityConfigurerAdapter;
import org.springframework.security.oauth2.client.registration.Registration;
import org.springframework.security.oauth2.client.registration.RegisteredClientRepository;
import org.springframework.security.oauth2.config.OAuth2ClientConfiguration;
import org.springframework.security.oauth2.config.annotation.web.configuration.EnableResourceServer;
import org.springframework.security.oauth2.provider.authentication.TokenServices;
import org.springframework.security.oauth2.provider.token.store.JdbcTokenStore;

@Configuration
@EnableWebSecurity
public class SecurityConfig extends WebSecurityConfigurerAdapter {

  @Autowired
  private RegisteredClientRepository registeredClientRepository;

  @Bean
  public OAuth2ClientConfiguration oAuth2ClientConfiguration() {
    return OAuth2ClientConfiguration.withRegisteredClients(registeredClientRepository);
  }

  @Override
  protected void configure(HttpSecurity http) throws Exception {
    // Configure API endpoints to be secure and require authentication
    http.oauth2Login().and()
      .oauth2UserAuthorization().and()
      .authorizeRequests().antMatchers("/api/**").authenticated();
  }

  @Bean
  public AuthenticationManager authenticationManager() throws Exception {
    return super.authenticationManager();
  }

  @Override
  protected void configure(AuthenticationManagerBuilder auth) throws Exception {
    // Configure OAuth2 client details
    auth.oauth2Client(registration -> registration.clientRegistrationId("oauth2-client"));
  }

  @Bean
  public ScheduledExecutorService scheduledExecutorService() {
    return Executors.newScheduledThreadPool(5);
  }

  @Bean
  public JdbcTokenStore tokenStore() {
    return new JdbcTokenStore(dataSource());
  }

  @Bean
  public TokenServices tokenServices() {
    return new OAuth2TokenServices(tokenStore(), scheduledExecutorService());
  }
}
