	case true:
		// Credit card refund logic
	default:
		http.Error(w, "Unsupported gateway", http.StatusBadRequest)
		return
	}

	w.WriteHeader(http.StatusAccepted)
}

func (p *PaymentProcessor) HandleError(w http.ResponseWriter, r *http.Request) {
	log.Println("Error handling payment request:", r.Body)
	http.Error(w, "Internal Server Error", http.StatusInternalServerError)
}

func main() {
