	paymentProcessor := &PaymentProcessor{}

	r.Route("/payments", func(r chi.Router) {
		r.HandleFunc("/{paymentID}", paymentProcessor.HandlePayment).Methods("POST")
	})

	r.Route("/refunds", func(r chi.Router) {
