    size_t line_size;
    long line_number = 1;
    while ((line_size = fread(line, sizeof(char), MAX_LINE_SIZE - 1, file)) > 0) {
        line[line_size] = '\0';
        for (size_t i = 0; i < line_size; i++) {
            char* pattern_match = strstr(&line[i], ((pattern_t*)file_info)->pattern);
            if (pattern_match != NULL) {
                fseek(file, ftell(file) - line_size + i, SEEK_SET);
                size_t output_line_length = strlen(line) + sizeof(char) * 10; // estimated line length with newline and info
                char* output_line = malloc(output_line_length);
                sprintf(output_line, "%ld: %s", line_number++, &line[i]);
                fwrite(output_line, sizeof(char), output_line_length, ((pattern_t*)file_info)->output_file);
                free(output_line);
            }
        }
    }
    fclose(file);
}

void* log_performance(void* thread_id) {
    pthread_t this_thread = (pthread_t)thread_id;
    // Logging implementation
}

int main(int argc, char** argv) {
    if (argc < 3 || argc > 4) {
        fprintf(stderr, "Usage: %s [input file] [pattern(s)] [output file]\n", argv[0]);
        return 1;
    }
    FILE* input_file = fopen(argv[1], "r");
    if (input_file == NULL) {
        perror("Error opening input file");
        return 1;
    }
    FILE* output_file = fopen(argv[3], "w");
    if (output_file == NULL) {
        perror("Error opening output file");
        fclose(input_file);
        return 1;
    }
    pattern_t patterns[argc - 2];
    for (int i = 1; i < argc - 1; i++) {
        char* pattern = argv[i + 1];
        if (strlen(pattern) > PATTERN_MAX_LENGTH) {
            fprintf(stderr, "Pattern '%s' exceeds maximum length of %d characters.\n", pattern, PATTERN_MAX_LENGTH);
            return 1;
        }
        strcpy(patterns[i - 1].pattern, pattern);
        patterns[i - 1].output_file = output_file;
    }

    pthread_t threads[argc - 2];
    for (int i = 0; i < argc - 2; i++) {
        pthread_create(&threads[i], NULL, process_file, &patterns[i]);
    }
    for (int i = 0; i < argc - 2; i++) {
        pthread_join(threads[i], NULL);
    }

    log_performance(NULL);

    fclose(input_file);
    fclose(output_file);
}
