from flask import Flask, request, jsonify, send_file
from flask_cors import CORS
from flask_socketio import SocketIO, emit
from werkzeug.utils import secure_filename

app = Flask(__name__)
CORS(app)
socketio = SocketIO(app)

@app.route('/upload', methods=['POST'])
def handle_upload():
    file = request.files['file']
    filename = secure_filename(file.filename)
    filepath = os.path.join('uploads', filename)

    # Compute MD5 and SHA-256 hashes
    md5_hash = hashlib.md5(open(filepath, 'rb').read()).hexdigest()
    sha256_hash = hashlib.sha256(open(filepath, 'rb').read()).hexdigest()

    return jsonify({'md5': md5_hash, 'sha256': sha256_hash})

@socketio.on('connect')
def handle_connect():
    print('Client connected')

@socketio.on('disconnect')
def handle_disconnect():
    print('Client disconnected')

@socketio.on('progress_update')
def update_progress(progress):
    emit('progress_update', progress)

if __name__ == '__main__':
    socketio.run(app, debug=True)
