    def __init__(self):
        self.hashing_services = {}
        self.storage_providers = {}

    def add_hashing_service(self, service_name, api_url):
        if not self.hashing_services.get(service_name):
            self.hashing_services[service_name] = {
                'api': requests.Session(),
                'hash_func': hashlib.new('md5')
            }
        return self.hashing_services[service_name]

    def add_storage_provider(self, provider_name, config):
        if not self.storage_providers.get(provider_name):
            if provider_name == 'AWS S3':
                s3 = boto3.client('s3', aws_access_key_id=config['access_key'],
                                   aws_secret_access_key=config['secret_key'])
                self.storage_providers[provider_name] = s3
            elif provider_name == 'Google Cloud Storage':
                storage_client = storage.Client()
                bucket = storage_client.bucket(config['bucket_name'])
                self.storage_providers[provider_name] = bucket
            elif provider_name == 'Azure Blob Storage':
                blob_service_client = BlobServiceClient.from_connection_string(
                    config['connection_string']
                )
                self.storage_providers[provider_name] = blob_service_client

    def store_file(self, file_path, file_hash):
        for storage_provider in self.storage_providers.values():
            if isinstance(storage_provider, boto3.client):
                s3.put_object(Body=open(file_path, 'rb'), Bucket=storage_provider.Bucket(), Key=file_hash)
            elif isinstance(storage_provider, storage.Client):
                bucket = storage_provider.bucket(file_hash)
                blob = bucket.blob('file.txt')
                blob.upload_from_string(open(file_path, 'r').read())
            elif isinstance(storage_provider, BlobServiceClient):
                container_client = storage_provider.get_container_client(file_hash)
                blob_client = container_client.get_blob('file.txt')
                blob_client.upload_blob(open(file_path, 'rb'), overwrite=True)

    def validate_file(self, file_path, expected_hash):
        for hashing_service in self.hashing_services.values():
            hash_func = hashing_service['hash_func']
            actual_hash = hash_func.reads(open(file_path, 'rb').read()).hexdigest()
            if actual_hash == expected_hash:
                return True
        return False

    def handle_file_upload(self, file_path):
        file_hash = self.calculate_file_hash(file_path)
        try:
            self.store_file(file_path, file_hash)
            return {'status': 'ok', 'hash': file_hash}
        except Exception as e:
            logging.error(f"Error uploading file: {e}")
            return {'status': 'error'}

    def calculate_file_hash(self, file_path):
        for hashing_service in self.hashing_services.values():
            hash_func = hashing_service['hash_func']
            with open(file_path, 'rb') as f:
                file_content = f.read()
                hash_value = hash_func.update(file_content).digest().hex()
            return hash_value

