    host = gethostbyname(hostname);
    if (host == NULL)
        return NULL;

    for (i = 0; i < host->h_aliases[0]; i++) {
        if (host->h_aliases[i] != NULL) {
            ip_addr = malloc(strlen(host->h_aliases[i]) + 1);
            strcpy(ip_addr, host->h_aliases[i]);
            return ip_addr;
        }
    }

