#include <iostream>
#include <json/json.h>

bool validate_oauth2_token(const std::string& token_json) {
    Json::Value root;
    try {
        root = Json::parse(token_json);
    } catch (Json::Exception &e) {
        std::cerr << "Error parsing JSON: " << e.what() << std::endl;
        return false;
    }

    if (!root.isObject())
        return false;

    const char* access_token = root["access_token"].asString();
    time_t now = time(0);
    if (now > root["expires_in"].asInt64() + root["issued_at"].asInt64()) {
        std::cerr << "Token has expired." << std::endl;
        return false;
    }

    return true;
}
