} SearchPattern;

void search_file(char *file_name, SearchPattern pattern);
void filter_file(char *file_name, SearchPattern pattern);
void summarize_file(char *file_name);

int main(int argc, char **argv) {
    if (argc < 2) {
        printf("Usage: %s [search/filter/summarize] [file_name]\n", argv[0]);
        return 1;
    }

    if (!strcmp(argv[1], "search")) {
        SearchPattern pattern = {argv[2], 0}; // case-insensitive by default
        search_file(argv[3], pattern);
    } else if (!strcmp(argv[1], "filter")) {
        SearchPattern pattern = {argv[2], 0};
        filter_file(argv[3], pattern);
    } else if (!strcmp(argv[1], "summarize")) {
        summarize_file(argv[2]);
    } else {
        printf("Invalid operation: %s\n", argv[1]);
        return 1;
    }

    return 0;
}

void search_file(char *file_name, SearchPattern pattern) {
    regex_t reg;
    int rc;

    if (regcomp(&reg, pattern.pattern, REG_EXTENDED | (pattern.case_sensitive ? 0 : REG_ICASE))) {
        printf("Failed to compile regex: %s\n", file_name);
        return;
    }

    FILE *file = fopen(file_name, "r");
    if (!file) {
        printf("Failed to open file: %s\n", file_name);
        regfree(&reg);
        return;
    }

    char line[MAX_FILE_SIZE];
    while (fgets(line, MAX_FILE_SIZE, file)) {
        if (regexec(&reg, line, sizeof(line), NULL, 0) == 0) {
            printf("Found match: %s\n", line);
        }
    }

    fclose(file);
    regfree(&reg);
}

void filter_file(char *file_name, SearchPattern pattern) {
    FILE *file = fopen(file_name, "r");
    if (!file) {
        printf("Failed to open file: %s\n", file_name);
        return;
    }

    char line[MAX_FILE_SIZE];
    while (fgets(line, MAX_FILE_SIZE, file)) {
        if (regexec(&reg, line, sizeof(line), NULL, 0) == 0) {
            // process filtered line
            printf("Filtered match: %s\n", line);
        }
    }

    fclose(file);
}

void summarize_file(char *file_name) {
    FILE *file = fopen(file_name, "r");
    if (!file) {
        printf("Failed to open file: %s\n", file_name);
        return;
    }

    int lines_count = 0;
    while (fgets(line, MAX_FILE_SIZE, file)) {
        lines_count++;
    }

    fclose(file);

    printf("File summary: %d lines\n", lines_count);
}

