import hashlib
import os
from typing import Dict, List

class CloudStorage:
    def __init__(self, provider: str):
        self.provider = provider
        if self.provider == 'aws':
            from aws_s3 import AWSStorage
            self.storage = AWSStorage()
        elif self.provider == 'google':
            from google_cloud_storage import GoogleCloudStorage
            self.storage = GoogleCloudStorage()
        elif self.provider == 'azure':
            from azure_blob_storage import AzureBlobStorage
            self.storage = AzureBlobStorage()

    def put_object(self, file_path: str) -> Dict:
        # upload the file to the cloud storage provider
        obj = {'file_path': file_path}
        return self.storage.put_object(file_path)

    def get_object(self, file_path: str) -> Dict:
        # download the file from the cloud storage provider
        obj = {'file_path': file_path}
        return self.storage.get_object(file_path)

class HashingService:
    def __init__(self):
        self.hash_algorithms = ['md5', 'sha256']

    def hash_file(self, file_path: str) -> Dict:
        # compute the MD5 and SHA-256 hashes of the file
        hashes = {}
        for algorithm in self.hash_algorithms:
            with open(file_path, 'rb') as file:
                data = file.read()
                if algorithm == 'md5':
                    hash_value = hashlib.md5(data).hexdigest()
                elif algorithm == 'sha256':
                    hash_value = hashlib.sha256(data).hexdigest()
                hashes[algorithm] = hash_value
        return hashes

class FileService:
    def __init__(self):
        self.cloud_storages: List[CloudStorage] = []
        self.hashing_service = HashingService()

    def upload_file(self, file_path: str) -> Dict:
        # upload the file to a cloud storage provider and compute its hash
        for cloud_storage in self.cloud_storages:
            obj = cloud_storage.put_object(file_path)
            if obj['status'] == 'success':
                hashes = self.hashing_service.hash_file(file_path)
                return {'file_path': file_path, 'cloud_provider': cloud_storage.provider, **hashes}
        return {'status': 'error'}

    def download_file(self, file_path: str) -> Dict:
        # download the file from a cloud storage provider and compute its hash
        for cloud_storage in self.cloud_storages:
            obj = cloud_storage.get_object(file_path)
            if obj['status'] == 'success':
                hashes = self.hashing_service.hash_file(file_path)
                return {'file_path': file_path, 'cloud_provider': cloud_storage.provider, **hashes}
        return {'status': 'error'}

# Example usage:
file_service = FileService()
cloud_storages = [CloudStorage('aws'), CloudStorage('google')]
file_service.cloud_storages = cloud_storages

file_path = 'path/to/file.txt'
result = file_service.upload_file(file_path)
print(result)

result = file_service.download_file(file_path)
print(result)
