mod nfa_pi_module {
    use crate::nfa_pi_data::{NFAPI_L2_RX_PDU_T, RX_UE_INFORMATION_TAG};
    use std::fs;
    use std::io;

    pub fn process_file(path: &str) -> io::Result<()> {
        let contents = fs::read_to_string(path)?;
        // Parse the input file using a lexer and parser
        let mut lexer = crate::nfa_pi_lexer::Lexer::new(contents.as_bytes());
        let mut parser = crate::nfa_pi_parser::Parser::new(lexer);
        let ast = parser.parse()?;

        // Generate LLVM IR code for the given grammar
        let ir_gen = crate::nfa_pi_irgen::IrGen::new(ast.clone());
        let llvm_code = ir_gen.generate_ir_code();

        // Save the generated LLVM IR code to a file
        let output_path = "output.ll";
        fs::write(output_path, llvm_code)?;

        Ok(())
    }
}
