['Here is the C++ code block:

```cpp
#include <iostream>
#include <vector>
#include <mutex>
#include <thread>
#include <chrono>
#include <condition_variable>

class DataPacket {
public:
    uint32_t packetID;
    uint64_t timestamp;
    size_t payloadSize;
    void* payloadData;

    // Constructor
    DataPacket(uint32_t id, uint64_t ts, size_t size) : 
        packetID(id), timestamp(ts), payloadSize(size) {
        payloadData = new char[payloadSize];
    }

    // Destructor
    ~DataPacket() {
        delete[] (char*)payloadData;
    }
};

class DynamicList {
public:
    std::vector<DataPacket*> packets;
    std::mutex mutex;
    std::condition_variable condition;

    // Constructor
    DynamicList() : packets() {}

    // Add a new packet to the list
    void addPacket(DataPacket* packet) {
        std::unique_lock<std::mutex> lock(mutex);
        packets.push_back(packet);
        lock.unlock();
        condition.notify_all();
    }

    // Remove a packet from the list
    void removePacket(uint32_t id) {
        std::unique_lock<std::mutex> lock(mutex);
        for (auto it = packets.begin(); it != packets.end();) {
            if ((*it)->packetID == id) {
                delete *it;
                it = packets.erase(it);
            } else {
                ++it;
            }
        }
    }

    // Retrieve a packet by ID
    DataPacket* getPacket(uint32_t id) {
        std::unique_lock<std::mutex> lock(mutex);
        for (auto& packet : packets) {
            if (packet->packetID == id) {
                return packet;
            }
        }
        return nullptr;
    }

    // Consume all packets
    void consumePackets() {
        std::unique_lock<std::mutex> lock(mutex);
        while (!packets.empty()) {
            DataPacket* packet = packets.back();
            packets.pop_back();
            delete packet;
        }
    }
};

// Example usage:
int main() {
    DynamicList list;

    // Add some packets
    for (int i = 0; i < 10; ++i) {
        DataPacket* packet = new DataPacket(i, std::chrono::steady_clock::now().time_since_epoch().count(), 1024);
        list.addPacket(packet);
    }

    // Remove a packet
    list.removePacket(5);

    // Retrieve a packet
    DataPacket* packet = list.getPacket(3);
    if (packet) {
        std::cout << "Packet ID: " << packet->packetID << std::endl;
    } else {
        std::cout << "Packet not found" << std::endl;
    }

    // Consume all packets
    list.consumePackets();

    return 0;
}
