#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <sys/socket.h>
#include <netinet/in.h>
#include <arpa/inet.h>
#include <pthread.h>

#define PORT 8080
#define BUFFER_SIZE 1024
#define MAX_CONNECTIONS 15000

typedef struct {
    int sock;
    char ip[16];
} Connection;

Connection *connections = NULL;
int connections_count = 0;

void *handle_request(void *arg) {
    Connection *conn = (Connection *) arg;
    // Handle request
    return NULL;
}

void handle_connections() {
    pthread_t threads[MAX_CONNECTIONS];
    for (int i = 0; i < MAX_CONNECTIONS; i++) {
        int sock = accept(conn->sock, (struct sockaddr *)&conn->ip, sizeof(conn->ip));
        if (sock != -1) {
            Connection *new_conn = malloc(sizeof(Connection));
            new_conn->sock = sock;
            memcpy(new_conn->ip, conn->ip, 16);
            pthread_create(&threads[i], NULL, handle_request, new_conn);
            connections_count++;
        }
    }
}

void close_connections() {
    for (int i = 0; i < connections_count; i++) {
        Connection *conn = &connections[i];
        close(conn->sock);
    }
    free(connections);
}

int main(int argc, char **argv) {
    int master_sock = socket(AF_INET, SOCK_STREAM, 0);
    if (master_sock != -1) {
        struct sockaddr_in server_addr;
        server_addr.sin_family = AF_INET;
        server_addr.sin_port = htons(PORT);
        inet_pton(AF_INET, "127.0.0.1", &server_addr.sin_addr);

        if (bind(master_sock, (struct sockaddr *)&server_addr, sizeof(server_addr)) != -1) {
            listen(master_sock, MAX_CONNECTIONS);

            while (1) {
                handle_connections();
            }
        }

        close(master_sock);
    }
}

