#include <iostream>
#include <string>
#include <vector>
#include <map>
#include <queue>
#include <chrono>

using namespace std;

class RateLimiter {
public:
    explicit RateLimiter(size_t maxRequestsPerSecond) : maxRequestsPerSecond_(maxRequestsPerSecond), requestQueue_() {}

    bool isReadyForNewRequest() const {
        auto now = chrono::system_clock::now().time_since_epoch();
        return requestQueue_.empty() || requestQueue_.top() <= now;
    }

    void enqueueRequest(size_t requestTime) {
        requestQueue_.push(requestTime);
    }

    void dequeueExpiredRequests() {
        while (!requestQueue_.empty()) {
            auto top = requestQueue_.top();
            if (chrono::system_clock::now().time_since_epoch() > top) {
                requestQueue_.pop();
            } else {
                break;
            }
        }
    }

private:
    size_t maxRequestsPerSecond_;
    priority_queue<pair<int, size_t>> requestQueue_;
};

int main() {
    RateLimiter rateLimiter(50000); // Initialize the rate limiter with a maximum of 50,000 requests per second

    while (true) {
        if (!rateLimiter.isReadyForNewRequest()) {
            cout << "Rate limit exceeded. Waiting..." << endl;
            this_thread::sleep_for(chrono::milliseconds(1000)); // Simulate waiting
        } else {
            rateLimiter.enqueueRequest(time(nullptr));
            cout << "New request accepted." << endl;
        }
    }

    return 0;
}
