import hashlib
from google.cloud import storage as gcs
from azure.storage.blob import BlobServiceClient, BlobClient
import boto3
import requests
import time
import logging
from flask import Flask, request, jsonify
from waitress import serve
from concurrent.futures import ThreadPoolExecutor

app = Flask(__name__)

config_file = 'storage_config.json'
log_file = 'service.log'

def get_storage_config():
    try:
        with open(config_file, 'r') as f:
            return json.load(f)
    except FileNotFoundError:
        return {}

def init_storage_providers():
    storage_providers = {}
    for provider in get_storage_config().get('providers', []):
        if provider['type'] == 'aws_s3':
            s3 = boto3.client('s3')
            storage_providers[provider['name']] = {'s3': s3}
        elif provider['type'] == 'google_cloud_storage':
            gcs_client = gcs.Client()
            bucket = gcs_client.bucket(provider['bucket_name'])
            storage_providers[provider['name']] = {'gcs': bucket}
        elif provider['type'] == 'azure_blob_storage':
            blob_service_client = BlobServiceClient.from_connection_string(provider['connection_string'])
            storage_providers[provider['name']] = {'azure': blob_service_client}

def get_file_hash(file_path):
    with open(file_path, 'rb') as f:
        file_data = f.read()
    md5_hash = hashlib.md5(file_data).hexdigest()
    sha256_hash = hashlib.sha256(file_data).hexdigest()
    return {'md5': md5_hash, 'sha256': sha256_hash}

def upload_file_to_storage(storage_provider, file_path):
    if storage_provider['s3']:
        s3 = storage_provider['s3']
        bucket_name = storage_provider['bucket_name']
        key = file_path.split('/')[-1]
        s3.put_object(Body=open(file_path, 'rb'), Bucket=bucket_name, Key=key)
    elif storage_provider['gcs']:
        gcs_bucket = storage_provider['gcs']
        blob_name = file_path.split('/')[-1]
        gcs_bucket.blob(blob_name).upload_from_string(open(file_path, 'rb').read())
    elif storage_provider['azure']:
        azure_blob_client = storage_provider['azure'].get_blob_client(blob=file_path.split('/')[-1])
        with open(file_path, 'rb') as f:
            azure_blob_client.upload_blob(f.read())

def download_file_from_storage(storage_provider, file_path):
    if storage_provider['s3']:
        s3 = storage_provider['s3']
        bucket_name = storage_provider['bucket_name']
        key = file_path.split('/')[-1]
        response = s3.get_object(Bucket=bucket_name, Key=key)
        with open(file_path, 'wb') as f:
            f.write(response['Body'].read())
    elif storage_provider['gcs']:
        gcs_bucket = storage_provider['gcs']
        blob_name = file_path.split('/')[-1]
        blob = gcs_bucket.blob(blob_name)
        with open(file_path, 'wb') as f:
            f.write(blob.download_as_string().encode('utf-8'))
    elif storage_provider['azure']:
        azure_blob_client = storage_provider['azure'].get_blob_client(blob=file_path.split('/')[-1])
        with open(file_path, 'wb') as f:
            f.write(azure_blob_client.download_blob().read())

@app.route('/upload', methods=['POST'])
def upload_file():
    file_path = request.files['file']
    storage_providers = init_storage_providers()
    for provider in storage_providers.values():
        if provider.get('s3'):
            s3 = provider['s3']
            bucket_name = provider['bucket_name']
            key = file_path.filename
            s3.put_object(Body=file_path.stream, Bucket=bucket_name, Key=key)
        elif provider.get('gcs'):
            gcs_bucket = provider['gcs']
            blob_name = file_path.filename
            gcs_bucket.blob(blob_name).upload_from_string(file_path.stream.read())
        elif provider.get('azure'):
            azure_blob_client = provider['azure'].get_blob_client(blob=file_path.filename)
            with open(file_path, 'rb') as f:
                azure_blob_client.upload_blob(f.read())

@app.route('/download', methods=['GET'])
def download_file():
    file_path = request.args.get('file')
    storage_providers = init_storage_providers()
    for provider in storage_providers.values():
        if provider.get('s3'):
            s3 = provider['s3']
            bucket_name = provider['bucket_name']
            key = file_path
            response = s3.get_object(Bucket=bucket_name, Key=key)
            return response['Body'].read()
        elif provider.get('gcs'):
            gcs_bucket = provider['gcs']
            blob_name = file_path
            blob = gcs_bucket.blob(blob_name)
            return blob.download_as_string().encode('utf-8')
        elif provider.get('azure'):
            azure_blob_client = provider['azure'].get_blob_client(blob=file_path)
            return azure_blob_client.download_blob().read()

if __name__ == '__main__':
    serve(app, host='0.0.0.0', port=5000)

