const { Transform } = require('stream');
const { BufferJSON } = require('buffer-json');
const { createWriteStream } = require('fs');
const { createGzip } = require('zlib');
const { http } = require('https');

class LogProcessor extends Transform {
  constructor(options) {
    super({
      highWaterMark: options.bufferSize,
      writableObjectMode: true,
      readableObjectMode: false
    });
    this.logBuffer = [];
    this.queue = 0;
  }

  _transform(chunk, encoding, callback) {
    const logEntry = BufferJSON.decode(new Uint8Array(chunk));
    if (!logEntry || !logEntry.data) {
      return callback();
    }
    this.logBuffer.push(logEntry);
    this.queue++;
    if (this.queue >= options.batchSize) {
      this._flush(() => {
        this.queue -= batchSize;
      });
    } else {
      callback();
    }
  }

  _flush(callback) {
    const buffer = Buffer.concat(this.logBuffer.map(entry => entry.data));
    this.push(buffer);
    this.logBuffer.length = 0;
    callback();
  }

  _final() {
    this.end();
  }
}

class LogWriter extends Transform {
  constructor(options) {
    super({
      highWaterMark: options.bufferSize,
      writableObjectMode: true,
      readableObjectMode: false
    });
    this.queue = 0;
  }

  _transform(chunk, encoding, callback) {
