    }
    this.push(logEntry.data);
    this.queue++;
    if (this.queue >= options.batchSize) {
      this._flush(() => {
        this.queue -= batchSize;
      });
    } else {
      callback();
    }
  }

  _flush(callback) {
    callback();
  }

  _final() {
    this.end();
  }
}

class LogHandler extends Transform {
  constructor(options) {
    super({
      highWaterMark: options.bufferSize,
      writableObjectMode: true,
      readableObjectMode: false
    });
    this.queue = 0;
  }

  _transform(chunk, encoding, callback) {
    const logEntry = BufferJSON.decode(new Uint8Array(chunk));
    if (!logEntry || !logEntry.data) {
      return callback();
    }
    this.push(logEntry.data);
    this.queue++;
    if (this.queue >= options.batchSize) {
      this._flush(() => {
        this.queue -= batchSize;
      });
    } else {
      callback();
    }
  }

  _flush(callback) {
    callback();
  }

  _final() {
    this.end();
  }
}

class LogService {
  constructor(options) {
    this.logProcessor = new LogProcessor(options);
    this.logWriter = new LogWriter(options);
    this.logHandler = new LogHandler(options);

    this.logProcessor.pipe(this.logWriter).pipe(this.logHandler);
  }

  start() {
    // Start the log processing pipeline
  }
}

