class RateLimiter {
private:
    std::mutex mutex;
    std::condition_variable cv;
    int maxRequestsPerSecond;
    int currentRequests;
    double requestRate;
    bool enabled;

public:
    RateLimiter(int maxRequestsPerSecond, int requestRate) : 
        maxRequestsPerSecond(maxRequestsPerSecond), 
        currentRequests(0),
        requestRate(requestRate / 1000.0),
        enabled(true) {}

    void start() {
        std::thread rateChecker([this]() {
            while (enabled) {
                std::this_thread::sleep_for(std::chrono::milliseconds(int(1000.0 / requestRate))));
                std::unique_lock<std::mutex> lock(mutex);
                currentRequests = 0;
                cv.notify_one();
            }
        });
    }

    void stop() {
        enabled = false;
    }

    bool checkAndLimit(const std::string& userId) {
        if (!enabled) return true;

        std::unique_lock<std::mutex> lock(mutex);
        cv.wait_for(lock, std::chrono::milliseconds(int(1000.0 / requestRate)));

        currentRequests++;
        if (currentRequests > maxRequestsPerSecond) {
            // Anomaly detected or rate limit exceeded
            AnomalyDetector anomalyDetector;
            if (anomalyDetector.isAnomalous(userId)) {
                ConfigurationAPI configAPI;
                configAPI.updateConfig("RATE_LIMIT_DISABLED");
            }
            return false;
        }

        return true;
    }
};

int main() {
    RateLimiter rateLimiter(100, 50);
    rateLimiter.start();

    // Simulate concurrent requests
    std::vector<std::thread> threads;
    for (int i = 0; i < 10; i++) {
        threads.emplace_back([rateLimiter]() {
            while (true) {
                if (!rateLimiter.checkAndLimit("user" + std::to_string(i))) {
                    // Handle anomaly or rate limit exceeded
                }
                std::this_thread::sleep_for(std::chrono::milliseconds(100));
            }
        });
    }

    for (auto& thread : threads) {
        thread.join();
    }

    rateLimiter.stop();

    return 0;
}
