    // Define API endpoints
    endPoints := []Endpoint{
        {Name: "Payment", Description: "Process payment", URL: "/payment", Methods: []string{"POST"}},
        {Name: "Order", Description: "Place order", URL: "/order", Methods: []string{"POST"}},
        {Name: "Product", Description: "Retrieve product details", URL: "/product/{id}", Methods: []string{"GET", "PUT", "DELETE"}},
    }

    // Add API endpoints to the router
    for _, ep := range endPoints {
        r.HandleFunc(ep.URL, func(w http.ResponseWriter, r *http.Request) {
            fmt.Fprintf(w, "Hello from %s endpoint!", ep.Name)
        }).Methods(strings.Join(ep.Methods, ", "))
    }

    // Start the server
    port := ":8080"
    log.Fatal(http.ListenAndServe(port, r))
}

// Define a function to append a slash if the input string is under a certain size limit
func addSlash(s string, sizeLimit int) (string, error) {
    if len(s) <= sizeLimit {
        return s + "/", nil
    }
    return s, nil
