import os
import hashlib
import logging
from google.cloud import storage
from azure.storage.blob import BlobServiceClient, BlobClient
from boto3 import client as s3_client
from flask import Flask, request, send_file, jsonify
from flask_cors import CORS

app = Flask(__name__)
CORS(app)

# Configuration file to handle multiple storage provider configurations
config_file = 'storage_config.json'

def get_storage_provider(config):
    # AWS S3
    if config['provider'] == 'AWS':
        return {'bucket_name': config['bucket_name'], 
                'access_key_id': config['access_key_id'], 
                'secret_access_key': config['secret_access_key']}

    # Google Cloud Storage
    elif config['provider'] == 'GCS':
        return {'bucket_name': config['bucket_name'], 
                'project_id': config['project_id'], 
                'credentials_file_path': config['credentials_file_path']}

    # Azure Blob Storage
    elif config['provider'] == 'Azure':
        return {'account_name': config['account_name'], 
                'account_key': config['account_key'], 
                'container_name': config['container_name']}

    # Custom-built object storage service
    else:
        return {'storage_uri': config['storage_uri'], 
                'access_key_id': config['access_key_id'], 
                'secret_access_key': config['secret_access_key']}

def put_file(file_path, file_hash):
    # Get the storage provider configuration from the config file or API
    config = get_storage_provider(config_file)

    # AWS S3
    if config['provider'] == 'AWS':
        s3 = s3_client('s3', aws_access_key_id=config['access_key_id'], 
                        aws_secret_access_key=config['secret_access_key'])
        bucket_name = config['bucket_name']
        file_path = os.path.join(bucket_name, file_path)

    # Google Cloud Storage
    elif config['provider'] == 'GCS':
        gcs = storage.Client.from_service_account_json(config['credentials_file_path'])
        bucket_name = config['bucket_name']
        file_path = os.path.join(bucket_name, file_path)

    # Azure Blob Storage
    elif config['provider'] == 'Azure':
        blob_service_client = BlobServiceClient.from_connection_string(
            f"DefaultEndpointsProtocol=https;AccountName={config['account_name']};AccountKey={config['account_key']};BlobEndpoint={config['container_name']}"
        )
        bucket_name = config['container_name']
        file_path = os.path.join(bucket_name, file_path)

    # Custom-built object storage service
    else:
        pass

    try:
        if not config['provider']:
            # Hash the file using MD5, SHA-256, etc.
            with open(file_path, 'rb') as f:
                file_hash = hashlib.md5(f.read()).hexdigest()

            # Store the file in the storage provider
            if config['provider'] == 'AWS':
                s3.Bucket(bucket_name).put_object(Key=file_path, Body=f)
            elif config['provider'] == 'GCS':
                bucket = gcs.get_bucket(bucket_name)
                blob = bucket.blob(file_path)
                blob.upload_from_string(f.read())
            elif config['provider'] == 'Azure':
                container_client = blob_service_client.get_container_client(bucket_name)
                blob_client = container_client.get_blob_client(file_path)
                blob_client.upload_blob(f, overwrite=True)

    except Exception as e:
        logging.error('Error storing file: %s', str(e))

def get_file(file_path):
    # Get the storage provider configuration from the config file or API
    config = get_storage_provider(config_file)

    # AWS S3
    if config['provider'] == 'AWS':
        s3 = s3_client('s3', aws_access_key_id=config['access_key_id'], 
                        aws_secret_access_key=config['secret_access_key'])
        bucket_name = config['bucket_name']

    # Google Cloud Storage
    elif config['provider'] == 'GCS':
        gcs = storage.Client.from_service_account_json(config['credentials_file_path'])
        bucket_name = config['bucket_name']

    # Azure Blob Storage
    elif config['provider'] == 'Azure':
        blob_service_client = BlobServiceClient.from_connection_string(
            f"DefaultEndpointsProtocol=https;AccountName={config['account_name']};AccountKey={config['account_key']};BlobEndpoint={config['container_name']}"
        )
        bucket_name = config['container_name']

    # Custom-built object storage service
    else:
        pass

    try:
        if not config['provider']:
            # Retrieve the file from the storage provider using the MD5, SHA-256 hash
            if config['provider'] == 'AWS':
                response = s3.get_object(Bucket=bucket_name, Key=file_path)
                return send_file(BytesIO(response['Body'].read()), 
                                    as_attachment=True, attachment_filename=file_path)
            elif config['provider'] == 'GCS':
                bucket = gcs.get_bucket(bucket_name)
                blob = bucket.blob(file_path)
                return send_file(blob.download_as_string(), 
                                    as_attachment=True, attachment_filename=file_path)
            elif config['provider'] == 'Azure':
                container_client = blob_service_client.get_container_client(bucket_name)
                blob_client = container_client.get_blob_client(file_path)
                return send_file(blob_client.download_blob().read(), 
                                    as_attachment=True, attachment_filename=file_path)

    except Exception as e:
        logging.error('Error retrieving file: %s', str(e))

@app.route('/store', methods=['POST'])
def store_file():
    if 'file' not in request.files:
        return jsonify({'error': 'No file provided'}), 400

    file = request.files['file']
    file_hash = hashlib.md5(file.read()).hexdigest()
    put_file(file_path='path/to/file', file_hash=file_hash)
    return jsonify({'status': 'success'})

@app.route('/retrieve', methods=['GET'])
def retrieve_file():
    if 'file_path' not in request.args:
        return jsonify({'error': 'No file path provided'}), 400

    file_path = request.args['file_path']
    return get_file(file_path=file_path)

if __name__ == '__main__':
    app.run(debug=True)
