// Function to extract Old Testament book names from text using regular expressions
std::unordered_map<std::string, int> findOldTestamentBooks(const std::string& text) {
    // Define regular expression patterns for Old Testament book names
    static const std::string BOOK_NAME_PATTERN = "[A-Za-z\\s]+";
    static const std::string OLD_TESTAMENT_BOOKS[] = {"Genesis", "Exodus", "Leviticus", "Numbers", "Deuteronomy",
                                                         "Joshua", "Judges", "Ruth", "1Samuel", "2Samuel", "1Kings", "2Kings", "1Chronicles", "2Chronicles", "Ezra", "Nehemiah", "Esther", "Job", "Psalms", "Proverbs", "Ecclesiastes", "SongOfSolomon", "Isaiah", "Jeremiah", "Lamentations", "Ezekiel", "Daniel", "Hosea", "Joel", "Amos", "Obadiah", "Jonah", "Micah", "Nahum", "Habakkuk", "Zephaniah", "Haggai", "Zechariah", "Malachi"};

    std::unordered_map<std::string, int> bookCounts;

    // Remove punctuation and special characters from text
    std::string cleanText = text;
    std::regex punctuationRegex("\\W");
    cleanText = std::regex_replace(cleanText, punctuationRegex, "");

    // Match whole words in the text using regular expressions
    for (const auto& book : OLD_TESTAMENT_BOOKS) {
        std::smatch match;
        if (std::regex_search(cleanText, match, std::wcmatch(BOOK_NAME_PATTERN, std::wcmatch::nomatch))) {
            const std::string matchedBook = match.str();
            // Ignore books that are not in the Old Testament
            if (std::find(std::begin(OLD_TESTAMENT_BOOKS), std::end(OLD_TESTAMENT_BOOKS), matchedBook) != std::end(OLD_TESTAMENT_BOOKS)) {
                bookCounts[matchedBook]++;
            }
        }
    }

    return bookCounts;
}

int main() {
    const std::string inputText = "And so on... Genesis 1:1-2, Job 14:7-12, Psalms 100:5-6";
    std::unordered_map<std::string, int> result = findOldTestamentBooks(inputText);
    for (const auto& pair : result) {
        std::cout << "Book: " << pair.first << ", Count: " << pair.second << std::endl;
    }
    return 0;
}
