typedef struct {
    pthread_mutex_t mutex;
    int maxValue;
} MaxValueTracker;

int main() {
    // Initialize max value tracker
    MaxValueTracker *maxValueTracker = malloc(sizeof(MaxValueTracker));
    pthread_mutex_init(&maxValueTracker->mutex, NULL);
    maxValueTracker->maxValue = INT_MIN;

    // Start worker threads
    pthread_t threads[MAX_CONCURRENT_CONNECTIONS];
    for (int i = 0; i < MAX_CONCURRENT_CONNECTIONS; i++) {
        pthread_create(&threads[i], NULL, processInteger, maxValueTracker);
    }

    // Handle connections and integers
    int socket_fd;
    struct sockaddr_in server_addr;
    server_addr.sin_family = AF_INET;
    server_addr.sin_port = htons(8080);
    inet_pton(AF_INET, "127.0.0.1", &server_addr.sin_addr);

    while (1) {
        // Accept incoming connections
        int client_fd = accept(socket_fd, (struct sockaddr *)&server_addr, sizeof(server_addr));
        if (client_fd < 0) {
            perror("accept");
            continue;
        }

        // Read integers from the client
        Integer integer;
        read(client_fd, &integer, sizeof(Integer));

        // Process the integer and update max value tracker
        pthread_mutex_lock(&maxValueTracker->mutex);
        if (integer.value > maxValueTracker->maxValue) {
            maxValueTracker->maxValue = integer.value;
        }
        pthread_mutex_unlock(&maxValueTracker->mutex);

        // Send response back to the client
        int bytes_written = write(client_fd, "Integer processed successfully", strlen("Integer processed successfully"));
        if (bytes_written < 0) {
            perror("write");
        }

        close(client_fd);
    }

    return 0;
}

