import asyncio
import aiomysql
from aiohttp import web
import json
import time
import hashlib
import os

# System Integration
async def fetch_metadata():
    try:
        response = await requests.get('https://api.metadata.com/metadata')
        response.raise_for_status()
        return response.json()
    except Exception as e:
        print(f"Failed to fetch metadata: {str(e)}")
        return None

async def update_configuration(config_id):
    for _ in range(5):  # retry up to 5 times
        try:
            response = await requests.get(f'https://api.config.com/config/{config_id}')
            response.raise_for_status()
            data = response.json()
            if not data:
                return None
            return data
        except Exception as e:
            print(f"Failed to fetch configuration: {str(e)}")
            time.sleep(2 ** (_ + 1))  # exponential backoff

# Concurrency and Resource Management
async def handle_update(request):
    config_id = request.match_info['config_id']
    try:
        data = await update_configuration(config_id)
        if not data:
            return web.Response(status=404, text='Configuration not found')
        return web.Response(text=json.dumps(data))
    except Exception as e:
        print(f"Error handling update: {str(e)}")
        return web.Response(status=500, text='Internal Server Error')

# Scalability and Fault Tolerance
async def fetch_region_data(region):
    conn = await aiomysql.connect(host='mysql.service.com', port=3306,
                                  user='username', password='password',
                                  db='database')
    try:
        async with conn.cursor() as cursor:
            query = f"SELECT * FROM region_config WHERE region='{region}'"
            result = await cursor.execute(query)
            data = await cursor.fetchall()
            return data
    finally:
        conn.close()

async def sync_regions():
    regions = ['us', 'eu', 'ap']
    tasks = [fetch_region_data(region) for region in regions]
    results = await asyncio.gather(*tasks, return_exceptions=True)
    for i, result in enumerate(results):
        if isinstance(result, Exception):
            print(f"Error fetching {regions[i]}: {str(result)}")

# Performance Optimization
async def cache_region_data(region):
    conn = await aiomysql.connect(host='mysql.service.com', port=3306,
                                  user='username', password='password',
                                  db='database')
    try:
        async with conn.cursor() as cursor:
            query = f"SELECT * FROM region_config WHERE region='{region}'"
            result = await cursor.execute(query)
            data = await cursor.fetchall()
            cache.set(region, json.dumps(data))
    finally:
        conn.close()

async def get_region_data(region):
    cached_data = cache.get(region)
    if cached_data:
        return json.loads(cached_data)
    return await fetch_region_data(region)

# Error Handling and Monitoring
async def log_error(error):
    print(f"Error: {str(error)}")

async def monitor_service():
    while True:
        try:
            data = await get_region_data('us')
            if not data:
                raise Exception("Data not found")
            print(f"Service is healthy, received {data}")
        except Exception as e:
            await log_error(e)
        time.sleep(60)  # check every minute

# Modularity and Extensibility
class ConfigurationService:
    def __init__(self):
        self.configs = {}

    async def update_config(self, config_id, data):
        self.configs[config_id] = data

    async def get_config(self, config_id):
        return self.configs.get(config_id)

# Testing and Validation
async def test_service():
    service = ConfigurationService()
    await service.update_config('us', {'region': 'us'})
    result = await service.get_config('us')
    assert result == {'region': 'us'}

if __name__ == '__main__':
    asyncio.run(test_service())

# C Function for String Manipulation
c_code = """
#include <stdio.h>
#include <stdlib.h>
#include <string.h>

char* append_slash(char* str, int threshold) {
    if (strlen(str) >= threshold) {
        return str;
    }
    char* new_str = malloc(strlen(str) + 2);
    strcpy(new_str, str);
    strcat(new_str, "/");
    free(str);
    return new_str;
}
"""

c_function = None
if os.name == 'posix':
    import ctypes.util
    c_function = ctypes.CDLL(ctypes.util.find_library('mylib'))
elif os.name == 'nt':
    import ctypes
    c_function = ctypes.windll.mylib

# Integrate the C Function into the Service
async def append_slash(config_id, threshold):
    str_value = await get_config(config_id)
    new_str = c_function.append_slash(str_value.encode(), int(threshold))
    return new_str.decode()
