import com.fasterxml.jackson.databind.JsonNode;
import com.fasterxml.jackson.databind.ObjectMapper;
import java.io.IOException;
import java.util.concurrent.ConcurrentHashMap;
import java.util.concurrent.atomic.AtomicInteger;

public class OAuthTokenValidator {

    private static final int TOKEN_CACHE_SIZE = 1000;
    private static final long MAX_API_CALLS_PER_MINUTE = 10;
    private static final long API_CALL_TIMEOUT_MILLISECONDS = 500;

    private final ConcurrentHashMap<String, Integer> tokenCache = new ConcurrentHashMap<>();
    private final AtomicInteger apiCallsCount = new AtomicInteger(0);
    private final ObjectMapper mapper = new ObjectMapper();

    public void validateToken(String jsonToken) throws IOException {
        JsonNode node = mapper.readTree(jsonToken);

        if (!node.isArray() || node.size() < 4) {
            throw new InvalidTokenException("Invalid JSON structure");
        }

        String accessToken = node.get(0).asText();
        int expiresIn = node.get(1).intValue();
        String tokenType = node.get(2).asText();

        if (!"Bearer".equals(tokenType)) {
            throw new InvalidTokenException("Invalid token type: " + tokenType);
        }

        if (expiresIn <= 0) {
            throw new InvalidTokenException("Invalid expires_in value");
        }

        String refreshToken = null;
        try {
            refreshToken = node.get(3).asText();
        } catch (IOException e) {
            // ignore, just log the error
            System.out.println("Error parsing refresh token: " + e.getMessage());
        }

        validateTokenAgainstApi(accessToken);
    }

    private void validateTokenAgainstApi(String accessToken) throws IOException {
        if (apiCallsCount.incrementAndGet() > MAX_API_CALLS_PER_MINUTE * 60 / API_CALL_TIMEOUT_MILLISECONDS) {
            // wait for a short period before making the next call
            try {
                Thread.sleep(API_CALL_TIMEOUT_MILLISECONDS);
            } catch (InterruptedException e) {
                Thread.currentThread().interrupt();
            }
        }

        // TO DO: Implement token verification against external authentication API
    }

    public boolean isTokenValid(String accessToken) {
        return tokenCache.containsKey(accessToken);
    }

    public void cacheValidToken(String accessToken, int expiresIn) {
        if (tokenCache.size() >= TOKEN_CACHE_SIZE) {
            // remove the oldest cached token to make room for new ones
            tokenCache.remove(tokenCache.keySet().iterator().next());
        }
        tokenCache.put(accessToken, System.currentTimeMillis() + expiresIn * 1000);
    }

    public void clearTokenCache() {
        tokenCache.clear();
    }

    public static class InvalidTokenException extends Exception {

        public InvalidTokenException(String message) {
            super(message);
        }
    }
}
