const fs = require('fs');
const path = require('path');
const { API1, API2, API3 } = require('./apis');
const { Logger } = require('./logger');
const { Cache } = require('./cache');
const { Blockchain } = require('./blockchain');

class LogProcessor {
  constructor(config) {
    this.config = config;
    this.logDir = config.logDir;
    this.cache = new Cache(this.config.cacheOptions);
    this.blockchain = new Blockchain(this.config.blockchainOptions);
  }

  async processLogs() {
    const files = await fs.readdir(this.logDir);
    for (const file of files) {
      if (!file.endsWith('.log')) continue;

      const filePath = path.join(this.logDir, file);
      const logData = await this.readLog(filePath);

      if (!this.filterBySize(logData.size)) continue;
      if (!this.filterByTimestamp(logData.timestamp)) continue;
      if (!this.filterByText(logData.content)) continue;

      try {
        await this.applyFilters(logData);
      } catch (error) {
        console.error(`Error processing log ${file}: ${error}`);
        continue;
      }
    }

    await this.blockchain.commit();
  }

  async readLog(filePath) {
    const logData = await fs.readFile(filePath, 'utf8');
    return JSON.parse(logData);
  }

  filterBySize(size) {
    if (size > this.config.maxFileSize) return false;
    if (size < this.config.minFileSize) return false;
    return true;
  }

  filterByTimestamp(timestamp) {
    const now = new Date().getTime();
    if (now - timestamp > this.config.maxAge) return false;
    return true;
  }

  filterByText(content) {
    for (const keyword of this.config.keywords) {
      if (!content.includes(keyword)) return false;
    }
    return true;
  }

  async applyFilters(logData) {
    try {
      const metadata = await this.getMetadata(logData);
      logData.metadata = metadata;

      // Apply filters based on metadata
      for (const filter of this.config.filters) {
        if (!this.applyFilter(filter, logData)) continue;
      }
    } catch (error) {
      console.error(`Error applying filters to log ${logData.id}: ${error}`);
    }
  }

  async getMetadata(logData) {
    try {
      const apiResponse = await this.callAPI(API1, logData);
      if (!apiResponse || !apiResponse.metadata) return {};

      // Cache metadata for future lookups
      this.cache.set(logData.id, apiResponse.metadata);

      return apiResponse.metadata;
    } catch (error) {
      console.error(`Error calling API 1 for log ${logData.id}: ${error}`);
    }

    try {
      const apiResponse = await this.callAPI(API2, logData);
      if (!apiResponse || !apiResponse.metadata) return {};

      // Cache metadata for future lookups
      this.cache.set(logData.id, apiResponse.metadata);

      return apiResponse.metadata;
    } catch (error) {
      console.error(`Error calling API 2 for log ${logData.id}: ${error}`);
    }

    try {
      const apiResponse = await this.callAPI(API3, logData);
      if (!apiResponse || !apiResponse.metadata) return {};

      // Cache metadata for future lookups
      this.cache.set(logData.id, apiResponse.metadata);

      return apiResponse.metadata;
    } catch (error) {
      console.error(`Error calling API 3 for log ${logData.id}: ${error}`);
    }
  }

  callAPI(api, logData) {
    try {
      const response = await api.getMetadata(logData);
      if (response.status === 'success') return response.data;
      else throw new Error(response.message);
    } catch (error) {
      console.error(`Error calling API ${api.name} for log ${logData.id}: ${error}`);
      // Retry with exponential backoff
      await this.backoff();
      return this.callAPI(api, logData);
    }
  }

  async backoff() {
    const delay = Math.pow(2, Math.floor(Math.random() * 5));
    await new Promise((resolve) => setTimeout(resolve, delay));
  }
}

module.exports = LogProcessor;
