**JavaScript Function: Calculate Average Word Length**

```javascript
function calculateAverageWordLength(text) {
    const words = text.replace(/[^\w\s]/gi, '').split(/\b/);
    const totalWords = words.length;

    let totalChars = 0;
    for (let i = 0; i < totalWords; i++) {
        totalChars += words[i].length;
    }

    return { totalWords, averageWordLength: Math.ceil(totalChars / totalWords) };
}
