import java.io.File;
import java.util.ArrayList;
import java.util.List;
import java.util.concurrent.ExecutorService;
import java.util.concurrent.Executors;

public class DisjointPairFinder {
    private int maxPairs;
    private boolean printStats;
    private List<String> dataFormats;
    private ExecutorService executorService;
    private UnionFind unionFind;

    public DisjointPairFinder(Configuration configuration) {
        this.maxPairs = configuration.getMaxPairs();
        this.printStats = configuration.isPrintStats();
        this.dataFormats = configuration.getDataFormats();
        this.executorService = Executors.newCachedThreadPool();
        this.unionFind = new UnionFind(configuration.getParallelThreshold());
    }

    public void processIntArray(int[] array) throws Exception {
        int numChunks = (int) Math.ceil(array.length / (double) unionFind.getParallelThreshold());
        List<Chunk> chunks = splitArrayIntoChunks(array, numChunks);

        for (Chunk chunk : chunks) {
            executorService.submit(() -> processChunk(chunk));
        }

        if (printStats) {
            printProcessingStatistics();
        }
    }

    private void processChunk(Chunk chunk) throws Exception {
        // Process the chunk using Union-Find
        List<DisjointPair> disjointPairs = unionFind.findDisjointPairs(chunk.getArray());
        for (DisjointPair pair : disjointPairs) {
            if (maxPairs > 0 && maxPairs-- <= 0) {
                break;
            }
            System.out.println("Disjoint pair found: " + pair.toString());
        }
    }

    private void printProcessingStatistics() throws Exception {
        long startTime = System.nanoTime();
        // Print statistics
        long endTime = System.nanoTime();
        double processingTime = (endTime - startTime) / 1e9;
        System.out.println("Processing time: " + processingTime + " seconds");
    }

    private List<Chunk> splitArrayIntoChunks(int[] array, int numChunks) {
        List<Chunk> chunks = new ArrayList<>();
        int chunkSize = array.length / numChunks;

        for (int i = 0; i < numChunks; i++) {
            int start = i * chunkSize;
            int end = (i == numChunks - 1) ? array.length : (i + 1) * chunkSize;
            Chunk chunk = new Chunk(array, start, end);
            chunks.add(chunk);
        }

        return chunks;
    }

    public static class Configuration {
        private int maxPairs;
        private boolean printStats;
        private List<String> dataFormats;

        // Constructor and getters/setters
    }

    public static class DisjointPair {
        private int[] elements;

        // Constructor, getter, and setter
    }

    public static class Chunk {
        private int[] array;
        private int start;
        private int end;

        // Constructor and getter
    }
}
