CREATE PROCEDURE sp_GetEmployeeDetails
    @SupervisorID int,
    @CitiesList nvarchar(max)
AS
BEGIN
    SET NOCOUNT ON;

    DECLARE @ValidatedCities TABLE (CityName nvarchar(50));

    IF NOT EXISTS (
        SELECT 1
        FROM sys.tables
        WHERE OBJECT_ID('dbo_ValidatedCities', 'U') IS NOT NULL
    )
    BEGIN
        CREATE TABLE dbo.ValidatedCities (
            CityName nvarchar(50) PRIMARY KEY
        );
    END;

    IF NOT EXISTS (
        SELECT 1
        FROM sys.indexes
        WHERE OBJECT_ID('dbo_ValidatedCities_idx', 'IX') IS NOT NULL
    )
    BEGIN
        CREATE NONCLUSTERED INDEX [idx_CityName]
        ON dbo.ValidatedCities (CityName);
    END;

    IF NOT EXISTS (
        SELECT 1
        FROM sys.partitions
        WHERE OBJECT_ID('dbo_ValidatedCities_partition', 'UQ') IS NOT NULL
    )
    BEGIN
        CREATE PARTITION FUNCTION [pf_ValidatedCities] () AS RANGE RIGHT FOR VALUES ('A', 'Z');
    END;

    IF NOT EXISTS (
        SELECT 1
        FROM sys.partitions
        WHERE OBJECT_ID('dbo_ValidatedCities_partitioned', 'UQ') IS NOT NULL
    )
    BEGIN
        CREATE PARTITION SCHEME [ps_ValidatedCities] AS PARTITION [pf_ValidatedCities] TO ([pf_ValidatedCities]);
    END;

    IF @SupervisorID IS NULL OR @CitiesList IS NULL
    BEGIN
        RAISERROR('Invalid input parameters', 16, 1);
        RETURN;
    END;

    DECLARE @ValidCities TABLE (CityName nvarchar(50));

    INSERT INTO @ValidCities (CityName)
    SELECT c.CityName
    FROM dbo.ValidatedCities c
    WHERE EXISTS (
        SELECT 1
        FROM STRING_SPLIT(@CitiesList, ',')
        s
        WHERE s.value = c.CityName
    );

    IF NOT EXISTS (
        SELECT 1
        FROM @ValidCities
    )
    BEGIN
        RAISERROR('No valid cities provided', 16, 1);
        RETURN;
    END;

    DECLARE @EmployeeDetails TABLE (EmployeeID int, Name nvarchar(50), City nvarchar(50));

    INSERT INTO @EmployeeDetails (EmployeeID, Name, City)
    SELECT e.EmployeeID, e.Name, c.CityName
    FROM Employees e
    JOIN Cities c ON e.City = c.CityName
    WHERE c.CityName IN (
        SELECT v.CityName
        FROM @ValidCities v
    );

    DECLARE @PageNumber int;
    DECLARE @PageSize int;

    SET @PageNumber = 1;
    SET @PageSize = 10;

    WITH paginated_employees AS (
        SELECT *, ROW_NUMBER() OVER (ORDER BY e.Name) AS RowNum
        FROM @EmployeeDetails e
    )
    SELECT *
    FROM paginated_employees pe
    WHERE pe.RowNum BETWEEN (@PageNumber - 1) * @PageSize + 1 AND @PageNumber * @PageSize
    ORDER BY pe.RowNum;

END;
```"]

