fn generate_cert_llvm_ir(grammar: &str) -> (Vec<u8>, String) {
    let mut pkey = PKey::generate_rsa(2048).unwrap();
    let x509 = X509::new().unwrap();

    // Generate certificate
    let cert = x509.sign(&pkey, vec!["Country".to_string(), "State".to_string(), "Locality".to_string()], None);

    // Read LLVM IR from grammar string
    let lexer = include_bytes!("grammar_lexer");
    let parser = include_bytes!("grammar_parser");

    // Parse LLVM IR
    let llvm_ir = parse_llvm_ir(lexer, parser, grammar).unwrap();

    // Embed private key in PEM file
    let mut pem_file = File::create("certificate.pem").unwrap();
    pem_file.write_all(&cert.to_pem()).unwrap();

    // Write LLVM IR to a separate file
    let llvm_file = "llvm_ir.ll";
    let mut f = File::create(llvm_file).unwrap();
    f.write_all(&format!("{}{}", include_str!("llvm_header"), &llvm_ir)).unwrap();

    (fs::read("certificate.pem").unwrap(), fs::read(llvm_file).unwrap())
}

