    else:
        return jsonify({"error": "Invalid username or password"}), 401

@app.route("/refresh", methods=["POST"])
def refresh():
    # Get refresh token from request body
    refresh_token = request.json["refresh_token"]

    # Check if refresh token is valid and not blacklisted
    if refresh_token in token_blacklist:
        return jsonify({"error": "Invalid or blacklisted refresh token"}), 401

    # Generate new access token using refresh token
    access_token = generate_access_token_from_refresh(refresh_token)
    return jsonify({"access_token": access_token})

@app.route("/protected", methods=["GET"])
def protected():
    # Get access token from request headers
    access_token = request.headers["Authorization"]

    # Check if access token is valid and not blacklisted
    if access_token not in token_blacklist:
        # Verify user information using access token
        username = verify_access_token(access_token)
        return jsonify({"username": username})
    else:
        return jsonify({"error": "Invalid or blacklisted access token"}), 401

@app.route("/logout", methods=["POST"])
def logout():
    # Get access token from request body
    access_token = request.json["access_token"]

    # Blacklist access token
    if access_token not in token_blacklist:
        token_blacklist.append(access_token)

    return jsonify({"message": "Logged out successfully"})

# Helper functions

def generate_access_token(username: str) -> str:
    # Generate access token using username and secret key
    secret_key = "YOUR_SECRET_KEY"
    expires_in = 3600  # Token expiration time in seconds
    token = jwt.encode({"username": username, "expires_at": datetime.utcnow() + timedelta(seconds=expires_in)}, secret_key, algorithm="HS256")
    return token.decode("utf-8")

def generate_access_token_from_refresh(refresh_token: str) -> str:
    # Generate new access token using refresh token and secret key
    secret_key = "YOUR_SECRET_KEY"
    expires_in = 3600  # Token expiration time in seconds
    token = jwt.encode({"username": get_username_from_refresh(refresh_token), "expires_at": datetime.utcnow() + timedelta(seconds=expires_in)}, secret_key, algorithm="HS256")
    return token.decode("utf-8")

def verify_access_token(access_token: str) -> str:
    # Verify access token using username and secret key
    secret_key = "YOUR_SECRET_KEY"
    try:
        payload = jwt.decode(access_token, secret_key, algorithms=["HS256"])
        return payload["username"]
    except jwt.ExpiredSignatureError:
        return None

def get_username_from_refresh(refresh_token: str) -> str:
