    // Iterate through directory entries
    while ((dent = readdir(dp)) != NULL) {
        if (dent->d_name[0] == '.') continue;  // Ignore hidden files and directories

        char file_path[256];
        sprintf(file_path, "%s/%s", dir_path, dent->d_name);

