            return -1;
        }

        // Read and process the file contents...

        close(fd);
    }

    closedir(dp);
    return 0;
}

// Function to implement a demand-paging caching strategy
int cache_resource_bundle(const char* bundle_name, void* data, int size) {
    // Create or retrieve the cache entry
    int fd = open("cache", O_RDWR | O_CREAT, S_IRUSR | S_IWUSR);
    if (fd < 0) {
        perror("open");
        return -1;
    }

    lseek(fd, 0, SEEK_END);  // Move to the end of the file

    // Write the cache entry
    write(fd, bundle_name, strlen(bundle_name));
    write(fd, data, size);

    close(fd);
    return 0;
}

