class Converter {
public:
    Converter(const Config& config) : config_(config), queue_(), lock_, cond_(lock_) {}

    void startConversion() {
        thread t(&Converter::workerThread, this);
        t.detach();
    }

private:
    void workerThread() {
        while (true) {
            shared_ptr<fs::path> file = queue_.wait_and_get();

            if (!file) break;

            // Convert the file
            try {
                convertFile(*file);
            } catch (const exception& e) {
                // Handle conversion errors
                cerr << "Error converting file: " << e.what() << endl;
            }

            // Release lock before processing the next file
            unique_lock<mutex> lk(lock_);
        }
    }

    void queueFile(fs::path file) {
        queue_.enqueue(move(make_shared<fs::path>(file)));
