        // Convert file using local engine or external service
        if (config_.useExternalService) {
            try {
                convertFileUsingExternalService(file);
            } catch (const exception& e) {
                // Retry with local engine if external service fails
                config_.retries--;
                if (config_.retries > 0) {
                    convertFileUsingLocalEngine(file);
                } else {
                    // Fallback to local engine or notify user about failure
