class Task {
public:
    Task(const std::string& name, int duration) : name(name), duration(duration) {}

    void run() {
        // Simulate task execution
        for (int i = 0; i < duration; i++) {
            std::this_thread::sleep_for(std::chrono::milliseconds(1));
        }
        std::cout << "Task " << name << " completed." << std::endl;
    }

    bool isComplete() { return true; } // Assume tasks are always complete

private:
    std::string name;
    int duration;
};

class DynamicTaskManager {
public:
    void addTask(Task task) {
        // Add task to the queue
        taskQueue_.emplace_back(task);
    }

    void startTasks() {
        // Start all added tasks in separate threads
        for (auto& task : taskQueue_) {
            std::thread([task]() { task.run(); }).detach();
        }
    }

private:
    std::vector<Task> taskQueue_;
};

int main() {
    DynamicTaskManager manager;

    // Add some tasks to the queue
    manager.addTask(Task("Task 1", 10));
    manager.addTask(Task("Task 2", 5));
    manager.addTask(Task("Task 3", 15));

    // Start all added tasks
    manager.startTasks();

    return 0;
}

