import os
import json
import requests
import threading
from functools import lru_cache
from typing import Dict, Any

class ConfigurationManager:
    def __init__(self):
        self.config = {}
        self.lock = threading.Lock()
        self.reloader_thread = None

    @lru_cache(maxsize=None)
    def get_config(self) -> Dict[str, Any]:
        config = {}

        # Load environment variables
        for key in os.environ:
            if key.startswith('CONFIG_'):
                config[key[7:]] = os.environ[key]

        # Load local JSON file
        try:
            with open('config.json', 'r') as f:
                config.update(json.load(f))
        except FileNotFoundError:
            pass

        # Fetch remote configuration
        try:
            response = requests.get('https://example.com/config')
            if response.status_code == 200:
                config.update(response.json())
        except (requests.exceptions.RequestException, json.JSONDecodeError):
            pass

        return config

    def reload_config(self):
        with self.lock:
            self.config = self.get_config()

    def start_reloader(self):
        self.reloader_thread = threading.Thread(target=self.reload_config)
        self.reloader_thread.daemon = True
        self.reloader_thread.start()

    def get_merged_config(self) -> Dict[str, Any]:
        return self.config

def main():
    config_manager = ConfigurationManager()
    config_manager.start_reloader()

    while True:
        try:
            merged_config = config_manager.get_merged_config()
            print(merged_config)
        except Exception as e:
            print(f"Error: {e}")

if __name__ == "__main__":
    main()
