    public class PipelineProcessor
    {
        private readonly ILogger<PipelineProcessor> _logger;
        private readonly CosmosClient _cosmosClient;
        private readonly IValidator[] _validators;
        private readonly ICircuitBreaker _circuitBreaker;

        public PipelineProcessor(ILogger<PipelineProcessor> logger, CosmosClient cosmosClient, IValidator[] validators, ICircuitBreaker circuitBreaker)
        {
            _logger = logger;
            _cosmosClient = cosmosClient;
            _validators = validators;
            _circuitBreaker = circuitBreaker;
        }

        public async Task ProcessData(byte[] data)
        {
            // Initialize processing context
            var context = new ProcessingContext(data);

            try
            {
                // Validate data using multiple services
                foreach (var validator in _validators)
                {
                    await validator.ValidateAsync(context);
                }
            }
            catch (Exception ex) when (_circuitBreaker.IsOpen())
            {
                // Service unavailable, roll back and retry later
                await RollbackPartialProcessing(context);
                await Task.Delay(1000); // exponential backoff
            }

            try
            {
                // Store data in Cosmos DB
                var database = _cosmosClient.GetDatabase("mydatabase");
                var container = database.GetContainer("mycontainer");
                await container.CreateItemAsync(new Item { Id = Guid.NewGuid().ToString(), Data = data });
            }
            catch (Exception ex)
            {
                // Database failure, roll back and retry later
                await RollbackPartialProcessing(context);
                await Task.Delay(1000); // exponential backoff
            }

            _logger.LogInformation("Data processed successfully");
        }

        private async Task RollbackPartialProcessing(ProcessingContext context)
        {
            // Implement rollback strategy for partially processed batches
        }
    }
}
