namespace EncryptionDecryptionFramework
{
    public class EncryptionDecryptionModule
    {
        private const int MaximumIntegerValue = int.MaxValue;

        public static string ConvertIntegersToBase64EncodedString(int[] integers)
        {
            using (Aes aes = Aes.Create())
            {
                byte[] iv = aes.IV;
                byte[] encryptedBytes = Encrypt(aes, integers);
                return Convert.ToBase64String(Combine(iv, encryptedBytes));
            }
        }

        public static int[] DecryptBase64EncodedString(string base64EncodedString)
        {
            using (Aes aes = Aes.Create())
            {
                byte[] iv = aes.IV;
                byte[] decryptedBytes = Decrypt(aes, Convert.FromBase64String(base64EncodedString));
                return GetIntegerArrayFromDecryptedData(decryptedBytes);
            }
        }

        private static byte[] Encrypt(Aes aes, int[] integers)
        {
            using (MemoryStream ms = new MemoryStream())
            {
                using (CryptoStream cs = new CryptoStream(ms, aes.CreateEncryptor()))
                {
                    using (BinaryWriter bw = new BinaryWriter(cs))
                    {
                        foreach (int integer in integers)
                        {
                            bw.Write(integer);
                        }
                    }
                }
                return ms.ToArray();
            }
        }

        private static byte[] Decrypt(Aes aes, byte[] encryptedBytes)
        {
            using (MemoryStream ms = new MemoryStream(encryptedBytes))
            {
                using (CryptoStream cs = new CryptoStream(ms, aes.CreateDecryptor()))
                {
                    using (BinaryReader br = new BinaryReader(cs))
                    {
                        int integer;
                        List<int> integers = new List<int>();
                        while ((integer = br.ReadInt32()) > 0)
                        {
                            integers.Add(integer);
                        }
                        return ms.ToArray();
                    }
                }
            }
        }

        private static byte[] Combine(byte[] first, byte[] second)
        {
            var result = new byte[first.Length + second.Length];
            Buffer.BlockCopy(first, 0, result, 0, first.Length);
            Buffer.BlockCopy(second, 0, result, first.Length, second.Length);
            return result;
        }

        private static int[] GetIntegerArrayFromDecryptedData(byte[] decryptedBytes)
        {
            using (MemoryStream ms = new MemoryStream(decryptedBytes))
            {
                using (BinaryReader br = new BinaryReader(ms))
                {
                    List<int> integers = new List<int>();
                    int integer;
                    while ((integer = br.ReadInt32()) > 0)
                    {
                        integers.Add(integer);
                    }
                    return integers.ToArray();
                }
            }
        }
    }

    public class TripleDesEncryptionModule
    {
        public static string EncryptTripleDES(string plaintext, byte[] key, byte[] iv)
        {
            using (TripleDESCryptoServiceProvider tripleDes = new TripleDESCryptoServiceProvider())
            {
                tripleDes.Key = key;
                tripleDes.IV = iv;
                return Convert.ToBase64String(tripleDes.CreateEncryptor().TransformFinalBlock(Encoding.UTF8.GetBytes(plaintext), 0, plaintext.Length));
            }
        }

        public static string DecryptTripleDES(string ciphertext, byte[] key, byte[] iv)
        {
            using (TripleDESCryptoServiceProvider tripleDes = new TripleDESCryptoServiceProvider())
            {
                tripleDes.Key = key;
                tripleDes.IV = iv;
                return Encoding.UTF8.GetString(tripleDes.CreateDecryptor().TransformFinalBlock(Convert.FromBase64String(ciphertext), 0, ciphertext.Length));
            }
        }
    }
}

