        private readonly ILogger _logger;

        public EncryptionFramework(IKeyManagementService keyManager, ICachingStrategy cache, ILogger logger)
        {
            _keyManager = keyManager;
            _cache = cache;
            _logger = logger;
        }

        public async Task EncryptAsync(string data, string sessionKey, int iterationCount)
        {
            using (var tripleDes = TripleDES.Create())
            {
                await SetKey(tripleDes, sessionKey);
                var encryptedData = Encrypt(data, tripleDes);
                // cache the encrypted data for later use
                _cache.Set("encrypted_data", encryptedData);
            }
        }

        public async Task<string> DecryptAsync(string encryptedData, string sessionKey)
        {
            using (var tripleDes = TripleDES.Create())
            {
                await SetKey(tripleDes, sessionKey);
                var decryptedData = Decrypt(encryptedData, tripleDes);
                return decryptedData;
            }
        }

        private async Task SetKey(TripleDES tripleDes, string sessionKey)
        {
            byte[] keyBytes = Convert.FromBase64String(sessionKey);
            tripleDes.Key = keyBytes;
            await _keyManager.GetInitializationVectorAsync(tripleDes.IV);
        }

        private string Encrypt(string data, TripleDES tripleDes)
        {
            using (var ms = new MemoryStream())
            {
                var cryptoStream = new CryptoStream(ms, tripleDes.CreateEncryptor(), CryptoStreamMode.Write);
                using (var writer = new StreamWriter(cryptoStream))
                {
                    writer.Write(data);
                }
                return Convert.ToBase64String(ms.ToArray());
            }
        }

        private string Decrypt(string encryptedData, TripleDES tripleDes)
        {
            using (var ms = new MemoryStream(Convert.FromBase64String(encryptedData)))
            {
                var cryptoStream = new CryptoStream(ms, tripleDes.CreateDecryptor(), CryptoStreamMode.Read);
                using (var reader = new StreamReader(cryptoStream))
                {
                    return reader.ReadToEnd();
                }
            }
        }
    }

