    public class Md5Service
    {
        private readonly IDistributedCache _cache;
        private readonly IConfigurationRoot _config;

        public Md5Service(IDistributedCache cache, IConfigurationRoot config)
        {
            _cache = cache;
            _config = config;
        }

        public async Task<string> ComputeMd5HashAsync(string input)
        {
            // Implement caching mechanism using distributed cache solution
            string cachedMd5Hash = await _cache.GetStringAsync(input);

            if (cachedMd5Hash != null)
                return cachedMd5Hash;

            // Compute MD5 hash for the input string
            byte[] hashBytes = ComputeMd5Hash(input);

            // Cache the computed MD5 hash
            await _cache.SetStringAsync(input, Convert.ToBase64String(hashBytes), new DistributedCacheEntryOptions());

            return Convert.ToBase64String(hashBytes);
        }

        private byte[] ComputeMd5Hash(string input)
        {
            using (MD5 md5 = MD5.Create())
            {
                byte[] hashBytes = md5.ComputeHash(Encoding.UTF8.GetBytes(input));
                return hashBytes;
            }
        }

        public async Task VerifyMd5HashAsync(string input, string providedMd5Hash)
        {
            // Retrieve the cached MD5 hash
            string cachedMd5Hash = await _cache.GetStringAsync(input);

            if (string.IsNullOrEmpty(cachedMd5Hash))
                throw new Exception("No cached MD5 hash found for the input.");

            if (!VerifyMd5Hash(input, providedMd5Hash, cachedMd5Hash))
                throw new Exception("Provided MD5 hash does not match the expected one.");
        }

        private bool VerifyMd5Hash(string input, string providedMd5Hash, string expectedMd5Hash)
        {
            byte[] expectedHashBytes = Convert.FromBase64String(expectedMd5Hash);
            byte[] providedHashBytes = Convert.FromBase64String(providedMd5Hash);

            return BitConverter.ToString(expectedHashBytes) == BitConverter.ToString(providedHashBytes);
