    std::string mediaFormat;
    bool priority;
};

// Media processor class
class MediaProcessor {
public:
    MediaProcessor(std::size_t numThreads, std::size_t queueSize);
    ~MediaProcessor();

    void enqueueTask(Task task);
    void processQueue();
    void shutDown();

private:
    std::vector<std::thread> threads_;
    std::queue<Task> taskQueue_;
    std::mutex mutex_;
    std::condition_variable conditionVariable_;
    std::map<std::string, Task> tasksInFlight_;
};

// External API interfaces
class AuthenticationAPI {
public:
    bool authenticate(const std::string& userId);
};

class MetadataExtractorAPI {
public:
    std::string extractMetadata(const std::string& mediaId);
};

class DistributionAPI {
