class NFAPI_CRC_INDICATION_PDU_T {
public:
    std::string RX_UE_INFORMATION_TAG;
    int RNTI;
    std::string CRC_INDICATION_REL8_TAG;
    bool CRCFLAG;
    long timestamp;
};

class ConcurrentLinkedList {
private:
    struct Node {
        NFAPI_CRC_INDATION_PDU_T data;
        std::unique_ptr<Node> next;
    };

public:
    void addNode(NFAPI_CRC_INDATION_PDU_T data) {
        std::lock_guard<std::mutex> lock(mutex);
        if (head == nullptr) {
            head = std::make_unique<Node>(data, nullptr);
        } else {
            Node* current = head.get();
            while (current->next != nullptr) {
                current = current->next.get();
            }
            current->next = std::make_unique<Node>(data, nullptr);
        }
    }

    void removeNode(NFAPI_CRC_INDATION_PDU_T data) {
        std::lock_guard<std::mutex> lock(mutex);
        Node* current = head.get();
        if (current != nullptr && current->data == data) {
            head = std::move(current->next);
        } else {
            while (current != nullptr && current->next != nullptr) {
                if (current->next->data == data) {
                    current->next = std::move(current->next->next);
                    break;
                }
                current = current->next.get();
            }
        }
    }

private:
    std::unique_ptr<Node> head;
    std::mutex mutex;
};

class CRCIndicationModule {
public:
    ConcurrentLinkedList linkedList;

    void addCRCIndication(NFAPI_CRC_INDATION_PDU_T data) {
        linkedList.addNode(data);
    }

    void removeCRCIndication(NFAPI_CRC_INDATION_PDU_T data) {
        linkedList.removeNode(data);
    }
};

