import logging
import hashlib
from typing import Dict

class MD5Calculator:
    def __init__(self, 
                 chunk_size: int = 1048576, 
                 max_file_size: int = 10737418240):
        self.chunk_size = chunk_size
        self.max_file_size = max_file_size
        self.logger = logging.getLogger(__name__)
        self.logger.setLevel(logging.INFO)

    def calculate_md5(self, file_path: str) -> Dict[str, str]:
        if not isinstance(file_path, str) or not os.path.exists(file_path):
            raise ValueError("Invalid file path")

        try:
            md5_hash = hashlib.md5()
            with open(file_path, 'rb') as f:
                while True:
                    chunk = f.read(min(self.chunk_size, 1024**2))
                    if not chunk:
                        break
                    md5_hash.update(chunk)
                    self.logger.info(f"Processing {file_path} ({os.path.getsize(file_path)} bytes)... "
                                       f"[{int(os.path.getsize(file_path) / 1024 ** 2):.2f}%] MD5: {md5_hash.hexdigest()}")
            return {"file_path": file_path, "md5_hash": md5_hash.hexdigest()}
        except Exception as e:
            self.logger.error(f"Error processing {file_path}: {str(e)}")
            raise

if __name__ == "__main__":
    logging.basicConfig(level=logging.INFO)
