package com.dynamicimageprocessingframework;

import java.util.concurrent.ExecutorService;
import java.util.concurrent.Executors;
import java.util.concurrent.ForkJoinPool;
import java.io.IOException;
import java.nio.file.Files;
import java.nio.file.Paths;
import javax.imageio.ImageIO;
import org.apache.commons.lang3.StringUtils;
import org.slf4j.Logger;
import org.slf4j.LoggerFactory;

public class DynamicImageProcessingFramework {
    private static final Logger logger = LoggerFactory.getLogger(DynamicImageProcessingFramework.class);
    private ExecutorService executorService;
    private ForkJoinPool forkJoinPool;

    public DynamicImageProcessingFramework() {
        this.executorService = Executors.newFixedThreadPool(16); // Adjust concurrency level as needed
        this.forkJoinPool = new ForkJoinPool(); // Use for parallel processing
    }

    public void processImages(JPEGImageStream imageStream) {
        if (imageStream != null) {
            try {
                executorService.submit(() -> {
                    try {
                        imageStream.validate();
                        MD5Calculator calculator = new MD5Calculator(imageStream);
                        byte[] md5Hash = calculator.calculate();
                        logger.info("Processed {} images with MD5 hash: {}", imageStream.size(), StringUtils.hexEncode(md5Hash));
                    } catch (Exception e) {
                        logger.error("Error processing images", e);
                    }
                });
            } catch (Exception e) {
                logger.error("Error submitting tasks", e);
            }
        }
    }

    public void close() {
        if (executorService != null) {
            executorService.shutdown();
        }
        if (forkJoinPool != null) {
            forkJoinPool.shutdownNow();
        }
    }
}

