pthread_mutex_t queue_lock = PTHREAD_MUTEX_INITIALIZER;
DataPacket* queue[MAX_QUEUE_SIZE] = {0};
size_t queue_head = 0;
size_t queue_tail = 0;

void enqueue(DataPacket* packet) {
    pthread_mutex_lock(&queue_lock);
    if (queue_tail >= MAX_QUEUE_SIZE) {
        // Handle queue full condition
    }
    queue[queue_tail++] = packet;
    pthread_mutex_unlock(&queue_lock);
}

DataPacket* dequeue() {
    pthread_mutex_lock(&queue_lock);
    DataPacket* packet = queue[queue_head];
    if (packet != NULL) {
        queue_head++;
    }
    pthread_mutex_unlock(&queue_lock);
    return packet;
}

void gc_thread(void*) {
    while (1) {
        sleep(TTL_DEFAULT); // Simulate TTL-based expiration
        pthread_mutex_lock(&queue_lock);
        for (size_t i = 0; i < MAX_QUEUE_SIZE; i++) {
