#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>

// Define the DataPacket structure
typedef struct {
    char* data;
    int size;
} DataPacket;

// Define the Queue structure
typedef struct {
    DataPacket* packets;
    int capacity;
    int count;
    pthread_mutex_t mutex;
    pthread_cond_t cond;
} Queue;

// Function to create a new queue with given capacity
Queue* queue_create(int capacity) {
    Queue* queue = (Queue*) malloc(sizeof(Queue));
    queue->packets = (DataPacket*) calloc(capacity, sizeof(DataPacket));
    queue->capacity = capacity;
    queue->count = 0;
    pthread_mutex_init(&queue->mutex, NULL);
    pthread_cond_init(&queue->cond, NULL);
    return queue;
}

// Function to enqueue a packet in the queue
void queue_enqueue(Queue* queue, DataPacket packet) {
    pthread_mutex_lock(&queue->mutex);
    if (queue->count >= queue->capacity) {
        // Handle full queue
    }
    queue->packets[queue->count] = packet;
    queue->count++;
    pthread_cond_signal(&queue->cond);
    pthread_mutex_unlock(&queue->mutex);
}

// Function to dequeue a packet from the queue
DataPacket* queue_dequeue(Queue* queue) {
    pthread_mutex_lock(&queue->mutex);
    while (queue->count == 0) {
        // Wait for packet availability
        pthread_cond_wait(&queue->cond, &queue->mutex);
    }
    DataPacket* packet = queue->packets;
    queue->packets++;
    queue->count--;
    pthread_mutex_unlock(&queue->mutex);
    return packet;
}

// Function to close the queue and free resources
void queue_close(Queue* queue) {
    pthread_mutex_lock(&queue->mutex);
    pthread_cond_destroy(&queue->cond);
    pthread_mutex_unlock(&queue->mutex);
    free(queue->packets);
    free(queue);
}
