    const char *output_file_path = argc > optind + 1 ? argv[optind + 1] : NULL;

    if (access(input_file_path, R_OK) != 0) {
        printf("Error: Unable to access input file.\n");
        return 1;
    }

    in_file = fopen(input_file_path, "rb");
    if (!in_file) {
        LOG_ERROR("Failed to open input file.");
        return 1;
    }

    if (output_file_path) {
        out_file = fopen(output_file_path, "wb");
        if (!out_file) {
            LOG_ERROR("Failed to open output file.");
            fclose(in_file);
            return 1;
        }
    }

    char buffer[BUFFER_SIZE];

    while ((size_t)read(in_file, buffer, BUFFER_SIZE) > 0) {
        // Process the buffer contents here...
        if (out_file)
            fwrite(buffer, 1, size_t)write(in_file, buffer, BUFFER_SIZE), out_file);
    }

    fclose(in_file);

    if (out_file)
        fclose(out_file);

