import os
import hashlib
import requests
from concurrent.futures import ThreadPoolExecutor, as_completed
from datetime import datetime
import logging

logging.basicConfig(level=logging.WARNING)

def get_file_metadata(file_path):
    api_url = "https://api.example.com/metadata"
    response = requests.get(api_url, params={"file_path": file_path})
    if response.status_code == 200:
        return response.json()
    else:
        return None

def calculate_sha256_hash(file_path):
    hash_object = hashlib.sha256()
    with open(file_path, "rb") as f:
        while chunk := f.read(4096):
            hash_object.update(chunk)
    return hash_object.hexdigest()

def validate_file_metadata(metadata, file_path):
    if not metadata or metadata.get("file_extension", "") in ["log", "tmp"]:
        return False
    return True

def process_files(directory, num_threads):
    files = [os.path.join(directory, f) for f in os.listdir(directory) if not f.endswith((".log", ".tmp"))]
    with ThreadPoolExecutor(max_workers=num_threads) as executor:
        futures = {executor.submit(process_file, file): file for file in files}
        for future in as_completed(futures):
            file_path = futures[future].get()
            try:
                metadata = get_file_metadata(file_path)
                if not metadata:
                    logging.warning(f"Failed to retrieve metadata for {file_path}")
                else:
                    hash_value = calculate_sha256_hash(file_path)
                    if validate_file_metadata(metadata, file_path):
                        print(f"{file_path}: SHA-256: {hash_value}, Metadata validated")
                    else:
                        logging.warning(f"Invalid file extension: {file_path}")
            except Exception as e:
                logging.error(f"Error processing {file_path}: {str(e)}")

def process_file(file):
    return file

if __name__ == "__main__":
