    content = db.Column(db.Text, nullable=False)

@app.route("/renderFooterScripts", methods=["POST"])
@login_required
def render_footer_scripts():
    scripts_to_load = request.get_json()["scripts"]
    try:
        for script in scripts_to_load:
            if "url" in script:
                response = requests.get(script["url"])
                with open("script.js", "wb") as f:
                    f.write(response.content)
                script_content = io.open("script.js", "r+", encoding="utf-8").read()
                md5_hash = hashlib.md5(script_content.encode()).hexdigest()
                sha256_hash = hashlib.sha256(script_content.encode()).hexdigest()
                yield {"name": script["name"], "content": script_content, "md5Hash": md5_hash, "sha256Hash": sha256_hash}
            elif "content" in script:
                script_content = script["content"]
                md5_hash = hashlib.md5(script_content.encode()).hexdigest()
                sha256_hash = hashlib.sha256(script_content.encode()).hexdigest()
                yield {"name": script["name"], "content": script_content, "md5Hash": md5_hash, "sha256Hash": sha256_hash}
    except Exception as e:
        logging.error(f"Error processing scripts: {e}")
        raise

@app.route("/renderFooterScripts", methods=["GET"])
@login_required
def render_footer_scripts_all():
    try:
        scripts = Script.query.all()
        for script in scripts:
            yield {"name": script.name, "content": script.content}
    except Exception as e:
        logging.error(f"Error rendering footer scripts: {e}")
        raise

if __name__ == "__main__":
    app.run(debug=True)
