class PriorityQueue {
private:
    std::priority_queue<DataPacket*, std::vector<DataPacket*>, 
        [](const DataPacket* a, const DataPacket* b) { return a->id > b->id; }> queue;

public:
    void enqueue(DataPacket* packet) {
        queue.push(packet);
    }

    DataPacket* dequeue() {
        if (queue.empty()) return nullptr;
        return queue.top();
    }
};

class PacketProcessor {
private:
    std::mutex mutex;
    std::condition_variable cv;

