    void processPacket(DataPacket& packet) {
        // your processing logic here
    }

    void runWorker(std::function<void()> workerFunction) {
        while (true) {
            std::unique_lock<std::mutex> lock(mutex);
            cv.wait_for(lock, std::chrono::seconds(1));
            if (!workerFunction()) break;
        }
    }
};

class PacketProducer {
private:
    std::queue<DataPacket*> packetQueue;

public:
    void enqueuePacket(DataPacket* packet) {
        packetQueue.push(packet);
    }

    DataPacket* dequeuePacket() {
        return packetQueue.front();
    }
};

