#include <openssl/ssl.h>
#include <openssl/rand.h>
#include <stdlib.h>
#include <stdio.h>
#include <string.h>

// Function to perform cryptographic operation on an image string
char* imageCipher(const char* command, const char* input) {
    // Initialize the cipher context
    EVP_CIPHER_CTX *ctx;
    ctx = EVP_CIPHER_CTX_new();

    // Set the cipher algorithm based on the command line option
    if (strcmp(command, "encrypt") == 0) {
        EVP_EncryptInit_ex(ctx, EVP_aes_256_cbc(), NULL, NULL, NULL);
    } else if (strcmp(command, "decrypt") == 0) {
        EVP_DecryptInit_ex(ctx, EVP_aes_256_cbc(), NULL, NULL, NULL);
    }

    // Perform the cryptographic operation
    unsigned char *out = (unsigned char*)malloc(strlen(input) + EVP_MAX_BLOCK_LENGTH);
    size_t outlen;
    EVP_CipherUpdate(ctx, out, &outlen, (const unsigned char*)input, strlen(input));

    // Free the cipher context and return the processed image string
    EVP_CIPHER_CTX_free(ctx);
    return (char*)out;
}
