    RateLimiter(int maxRequestsPerSecond) : maxRequestsPerSecond(maxRequestsPerSecond), requestsMade(0), lastRequestTime(std::chrono::high_resolution_clock::now()) {}

    bool limit(std::string user, int requestCount) {
        auto now = std::chrono::high_resolution_clock::now();
        auto elapsed = std::chrono::duration_cast<std::chrono::milliseconds>(now - lastRequestTime).count();

        if (elapsed < 1000 / maxRequestsPerSecond) { // Check if the time since last request is less than 1 second
            return false; // Rate limit exceeded, reject request
        }

        requestsMade++;

        if (requestsMade > maxRequestsPerSecond) {
            // Reset requests made counter when rate limit is exceeded
            requestsMade = 0;
        }

        lastRequestTime = now;

        return true; // Request allowed within the rate limit
    }

