function renderFooterScripts(scripts) {
  const scriptElements = [];
  const scriptQueue = [];

  function loadScript(script) {
    return new Promise((resolve, reject) => {
      const scriptElement = document.createElement('script');
      scriptElement.src = script.url;
      scriptElement.onload = () => resolve();
      scriptElement.onerror = () => reject(new Error(`Failed to load ${script.url}`));
      document.body.appendChild(scriptElement);
    });
  }

  function queueScript(script) {
    return new Promise((resolve, reject) => {
      scriptQueue.push({ script, resolve, reject });
    });
  }

  async function renderScripts() {
    for (const script of scripts) {
      if (script.transformed) {
        // Handle transformed scripts
        const transformedScript = await loadScript(script);
        scriptElements.push(transformedScript);
      } else {
        // Load original scripts
        queueScript(script).then(() => {
          // Check if the script was loaded successfully
          if (scriptQueue.shift()) {
            scriptElements.push(scriptElement);
          }
        });
      }
    }

    await Promise.all(scriptQueue.map((script) => script.resolve()));
  }

  return renderScripts;
}
