};

class NFAPI_CRC_INDICATION_MANAGER {
public:
    NFAPI_CRC_INDICATION_MANAGER() : head_(nullptr), tail_(nullptr) {}

    void insert(const NFAPI_CRC_INDICATION_PDU_T& indication) {
        std::unique_lock<std::mutex> lock(mutex_);
        if (head_ == nullptr) {
            head_ = new NFAPI_CRC_INDICATION_PDU_T;
            tail_ = head_;
        } else {
            NFAPI_CRC_INDICATION_PDU_T* new_node = new NFAPI_CRC_INDICATION_PDU_T;
            new_node->timestamp = std::chrono::system_clock::now();
            *tail_ = *new_node;
            tail_ = new_node;
        }
    }

    void remove() {
        if (head_) {
            NFAPI_CRC_INDICATION_PDU_T* temp = head_;
            head_ = head_->next;
            delete temp;
        }
    }

    void process(const std::priority_queue<std::pair<int, NFAPI_CRC_INDICATION_PDU_T>>& priority_queue) {
        while (!priority_queue.empty()) {
            auto& indication = priority_queue.top();
            priority_queue.pop();
            // Process the indication
            std::this_thread::sleep_for(std::chrono::microseconds(1000)); // Simulate processing time
        }
    }

private:
    struct NFAPI_CRC_INDICATION_PDU_T_NODE {
        NFAPI_CRC_INDICATION_PDU_T data;
        NFAPI_CRC_INDICATION_PDU_T_NODE* next;
    };

    NFAPI_CRC_INDICATION_PDU_T_NODE* head_;
    NFAPI_CRC_INDICATION_PDU_T_NODE* tail_;
    std::mutex mutex_;
};

int main() {
