    // Simulate inserting and processing CRC indications
    for (int i = 0; i < 10; ++i) {
        NFAPI_CRC_INDICATION_PDU_T indication;
        indication.timestamp = std::chrono::system_clock::now();
        manager.insert(indication);

        std::priority_queue<std::pair<int, NFAPI_CRC_INDICATION_PDU_T>> priority_queue;

        // Add indications to the priority queue
        for (int j = 0; j < i + 1; ++j) {
            indication.timestamp = std::chrono::system_clock::now();
            priority_queue.push({i, indication});
        }

        manager.process(priority_queue);

        // Simulate removing CRC indications
        while (!manager.head_) {
            manager.remove();
        }
    }

    return 0;
}

