        self.directory_monitor = directory_monitor
        self.cloud_backup = cloud_backup

    def backup_files(self):
        while True:
            for file_name, file_info in self.directory_monitor.file_changes.items():
                if "added" in file_info:
                    file_path = os.path.join(*self.directory_monitor.directory_paths, file_name)
                    self.cloud_backup.upload_file(file_path, file_name)
                    del self.directory_monitor.file_changes[file_name]
            time.sleep(self.backup_interval)

def main():
    directory_paths = ["/path/to/directory1", "/path/to/directory2"]
    backup_interval = 60

    directory_monitor = DirectoryMonitor(directory_paths, backup_interval)
    cloud_backup_service = CloudBackup("AWS S3", "access_key", "secret_key")

    with ThreadPoolExecutor(max_workers=5) as executor:
        backup_worker = BackupWorker(directory_monitor, cloud_backup_service)
        future = executor.submit(backup_worker.backup_files)

    while True:
        pass

if __name__ == "__main__":
    main()
```
Please note that this is just a starting point and you will need to implement the `CloudBackup.upload_file` method as well as any necessary error handling, logging, and monitoring.']

