function renderFooterScripts(scripts) {
  const cache = {};
  const scriptEls = document.querySelectorAll('#footer-scripts');
  scriptEls.forEach((el) => {
    el.innerHTML = '';
  });

  scripts.forEach((script) => {
    if (cache[script.src]) {
      return;
    }

    const request = new Request(script.src, {
      method: 'GET',
      headers: {
        Accept: 'text/javascript',
      },
    });

    cache[script.src] = fetch(request)
      .then((response) => response.text())
      .then((code) => {
        const scriptTag = document.createElement('script');
        scriptTag.src = script.src;
        scriptTag.text = code;
        el.appendChild(scriptTag);
      })
      .catch((error) => {
        console.error(`Error loading script ${script.src}:`, error);
      });
  });

  return Promise.all(Object.values(cache)).then(() => {
    const sw = new ServiceWorker({
      name: 'footer-scripts',
      scope: '/',
    });

    sw.addEventListener('install', (event) => {
      event.waitUntil(
        caches.open(CACHE_NAME).then((cache) => {
          cache.addAll(scripts.map((script) => script.src));
        })
      );
    });

    sw.addEventListener('fetch', (event) => {
      if (event.request.url.endsWith('.js')) {
        event.respondWith(
          caches.match(event.request).then((response) => {
            return response || fetch(event.request);
          })
        );
      }
    });

    self.addEventListener('activate', () => {
      const reg = self.registration.scope;
      caches.keys().then((keys) => {
        keys.forEach((key) => {
          if (reg.includes(key)) {
            caches.delete(key);
          }
        });
      });
    });
  });
}
