public class DistributedLoggingSystem {

    private List<Logger> loggers = new ArrayList<>();
    private IndexManager indexManager;
    private AlertManager alertManager;

    public DistributedLoggingSystem() {
        this.indexManager = new IndexManager();
        this.alertManager = new AlertManager();
    }

    public void addLogger(Logger logger) {
        loggers.add(logger);
    }

    public void ingestLog(Log log) throws IOException {
        for (Logger logger : loggers) {
            logger.write(log);
        }
        indexManager.index(log);
    }

    public List<Log> searchLogs(String query) {
        return indexManager.search(query);
    }

    public void setAlertThreshold(int threshold) {
        alertManager.setThreshold(threshold);
    }

    public void startAlertService() throws IOException {
        alertManager.start();
    }

    public class Logger {

        private LogWriter logWriter;

        public Logger(LogWriter logWriter) {
            this.logWriter = logWriter;
