**C function to compress raw video frames into H.264 format using FFmpeg:**
```c
#include <ffmpeg/avformat.h>
#include <ffmpeg/avcodec.h>

extern "C" {
    void compress_video_frames(unsigned char* frame, int width, int height) {
        AVFormatContext* fmt_ctx = avformat_alloc_context();
        AVCodec* codec = avcodec_find_encoder(AV_CODEC_ID_H264);
        AVCodecContext* codec_ctx = avcodec_alloc_context3(codec);

        // Set up H.264 encoding
        codec_ctx->bit_rate = 1000000;
        codec_ctx->width = width;
        codec_ctx->height = height;
        codec_ctx->time_base.num = 1;
        codec_ctx->time_base.den = 30;

        // Allocate a buffer for compressed data
        uint8_t* compressed_data = av_malloc(AV_MAX_PACKET_SIZE);
        int compressed_size = 0;

        // Compress the frame using FFmpeg
        int ret = avcodec_encode_video2(codec_ctx, &compressed_data, &compressed_size, frame, width, height);

        if (ret < 0) {
            // Handle FFmpeg errors
            printf("Error compressing video: %s\n", av_err2str(ret));
        } else {
            // Log compressed data size and timestamp
            printf("Compressed video frame size: %d bytes, timestamp: %" PRIu64 "\n",
                   compressed_size, codec_ctx->pts);
        }

        // Clean up FFmpeg resources
        avcodec_free_context(codec_ctx);
        avformat_free_context(fmt_ctx);
    }
}
