#include <arpa/inet.h>

u_char* dns_resolution(char* hostname) {
    int sockfd;
    struct sockaddr_in serv_addr;
    struct hostent *he;
    u_char* ip = NULL;

    // Create a socket
    sockfd = socket(AF_INET, SOCK_STREAM, 0);
    if (sockfd < 0) {
        return NULL;
    }

    // Set up the server's IP address and port number
    serv_addr.sin_family = AF_INET;
    serv_addr.sin_port = htons(53);

    // Perform DNS resolution
    he = gethostbyname(hostname);
    if (he == NULL) {
        close(sockfd);
        return NULL;
    }

    // Get the IP address from the hostent struct
    ip = malloc(INET6_ADDRSZ);
    memcpy(ip, he->h_addr_list[0], INET6_ADDRSZ);

    // Close the socket
    close(sockfd);

    return ip;
}
