```c
#include <stdlib.h>
#include <string.h>
#include <pthread.h>

// Define a structure to hold the packet data
typedef struct {
    uint64_t id;
    time_t timestamp;
    size_t payload_size;
    int status_flag;
    char source_system[32];
    char destination_system[32];
} DataPacket;

// Create a linked list node for storing packets
typedef struct _Node {
    DataPacket* packet;
    struct _Node* next;
} Node;

// Define the queue data structure
typedef struct {
    Node* head;
    Node* tail;
    pthread_mutex_t lock;
    size_t size;
} Queue;

// Create a new packet and add it to the end of the queue
void enqueue(Queue* q, DataPacket* packet) {
    Node* node = (Node*)malloc(sizeof(Node));
    node->packet = packet;
    node->next = NULL;

    pthread_mutex_lock(&q->lock);
    if(q->tail == NULL) {
        q->head = node;
        q->tail = node;
    } else {
        q->tail->next = node;
        q->tail = node;
    }
    q->size++;
    pthread_mutex_unlock(&q->lock);
}

// Remove and return the front packet from the queue
DataPacket* dequeue(Queue* q) {
    Node* node = q->head;
    DataPacket* packet = node->packet;

    pthread_mutex_lock(&q->lock);
    if(q->size > 1) {
        q->head = node->next;
    } else {
        q->head = NULL;
        q->tail = NULL;
    }
    q->size--;
    free(node);
    pthread_mutex_unlock(&q->lock);

    return packet;
}

// Initialize the queue
void init_queue(Queue* q) {
    q->head = NULL;
    q->tail = NULL;
    q->size = 0;
    pthread_mutex_init(&q->lock, NULL);
}
