#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <arpa/inet.h>

u_char* dns_resolve(char* hostname) {
    // Perform DNS resolution using standard library functions
    struct hostent* host = gethostbyname(hostname);
    if (host == NULL) {
        return NULL;
    }

