function copyData(chunks, numBytes) {
    const buffer = Buffer.allocUnsafe(numBytes);
    let offset = 0;

    for (const chunk of chunks) {
        const chunkOffset = 0;
        const chunkLength = chunk.length;
        const endOffset = chunkOffset + chunkLength;

        if (offset + chunkLength > numBytes) {
            throw new Error("Insufficient buffer size");
        }

        buffer.copy(chunk, chunkOffset, offset);
        offset += chunkLength;
    }

    return buffer;
}
