import os
import requests
import logging
from datetime import datetime
from flask import Flask, request, jsonify
from flask_api import status
from flask_cors import CORS

app = Flask(__name__)
CORS(app)

def perform_dns_resolution(hostname):
    try:
        response = requests.get(f"https://api.{hostname}.com/resolve", timeout=5)
        if response.status_code == 200:
            return response.json()["ip"]
        else:
            raise Exception("DNS resolution failed")
    except (requests.exceptions.RequestException, KeyError) as e:
        logging.error(f"Error performing DNS resolution: {e}")
        return None

def validate_oauth_token(token):
    try:
        token_data = json.loads(token)
        if "access_token" not in token_data or "expires_in" not in token_data:
            return False
        expires_at = datetime.utcfromtimestamp(int(token_data["expires_in"]))
        if datetime.utcnow() > expires_at:
            return False
        signature = hashlib.sha256(token.encode()).hexdigest()
        if signature != token_data["signature"]:
            return False
        return True
    except (json.JSONDecodeError, KeyError) as e:
        logging.error(f"Error validating OAuth token: {e}")
        return False

@app.route('/dns', methods=['GET'])
def dns_resolution():
    hostname = request.args.get('hostname')
    if not hostname:
        return jsonify({'error': 'Hostname is required'}), status.HTTP_400_BAD_REQUEST
    ip_address = perform_dns_resolution(hostname)
    if ip_address:
        return jsonify({'ip': ip_address}), status.HTTP_200_OK
    else:
        return jsonify({'error': 'DNS resolution failed'}), status.HTTP_500_INTERNAL_SERVER_ERROR

@app.route('/oauth', methods=['GET'])
def oauth_token_validation():
    token = request.args.get('token')
    if not token:
        return jsonify({'error': 'OAuth token is required'}), status.HTTP_400_BAD_REQUEST
    valid = validate_oauth_token(token)
    if valid:
        return jsonify({'valid': True}), status.HTTP_200_OK
    else:
        return jsonify({'error': 'Invalid OAuth token'}), status.HTTP_401_UNAUTHORIZED

if __name__ == '__main__':
    app.run(debug=True, port=5000)

