    std::vector<std::string> processBatch(const std::vector<std::string>& jsonDocs) {
        std::vector<std::future<std::vector<std::string>>> futures;
        for (const auto& doc : jsonDocs) {
            futures.emplace_back(std::async([this, &doc]{
                return processDocument(doc);
            }));
        }

        std::vector<std::string> enrichedDocs;
        for (auto& future : futures) {
            enrichedDocs.insert(enrichedDocs.end(), future.get().begin(), future.get().end());
        }
        return enrichedDocs;
    }

private:
    size_t workerCount_;
    bool stop_;

    std::mutex mtx;
    std::condition_variable cv;

    std::vector<std::thread> workers;

    void startWorker() {
        for (size_t i = 0; i < workerCount_; ++i) {
            workers.emplace_back([this]{
                while (!stop_) {
                    processDocumentBatch();
                    std::this_thread::sleep_for(std::chrono::milliseconds(10));
                }
            });
        }
    }

    void stopWorkers() {
        stop_ = true;
        for (auto& worker : workers) {
