```python
import logging
from abc import ABC, abstractmethod
import asyncio
import aiomysql
import boto3

class LoggerBackend(ABC):
    @abstractmethod
    def log_message(self, message: str, severity: int, metadata: dict) -> None:
        pass

class FileLogger(LoggerBackend):
    def __init__(self, filename: str):
        self.filename = filename

    def log_message(self, message: str, severity: int, metadata: dict) -> None:
        with open(self.filename, 'a') as file:
            file.write(f"[{severity}]{message}\n")
        if metadata:
            file.write(str(metadata) + "\n")

class ConsoleLogger(LoggerBackend):
    def log_message(self, message: str, severity: int, metadata: dict) -> None:
        print(f"[{severity}] {message}")
        if metadata:
            print(str(metadata))

class ThirdPartyLogger(LoggerBackend):
    def __init__(self, api_key: str, auth_token: str):
        self.api_key = api_key
        self.auth_token = auth_token

    async def log_message(self, message: str, severity: int, metadata: dict) -> None:
        # Implement API rate limiting and authentication
        await asyncio.sleep(1)
        print(f"[{severity}] {message}")

class MySQLLogger(LoggerBackend):
    def __init__(self, host: str, user: str, password: str, db: str):
        self.host = host
        self.user = user
        self.password = password
        self.db = db

    async def log_message(self, message: str, severity: int, metadata: dict) -> None:
        conn = await aiomysql.connect(
            host=self.host,
            user=self.user,
            password=self.password,
            db=self.db
        )
        cur = await conn.cursor()
        await cur.execute("INSERT INTO logs (message, severity, metadata) VALUES (%s, %s, %s)", (message, severity, str(metadata)))
        await conn.commit()
        await conn.close()

class AWSLogger(LoggerBackend):
    def __init__(self, bucket_name: str, region: str):
        self.bucket_name = bucket_name
        self.region = region

    async def log_message(self, message: str, severity: int, metadata: dict) -> None:
        s3 = boto3.client('s3', region_name=self.region)
        await s3.put_object(Body=message.encode(), Bucket=self.bucket_name)

class LoggerConfig:
    def __init__(self):
        self.backends = []
        self.default_backend = None

    def add_backend(self, backend: LoggerBackend) -> None:
        self.backends.append(backend)
        if not self.default_backend:
            self.default_backend = backend

    async def log_message(self, message: str, severity: int, metadata: dict) -> None:
        for backend in self.backends:
            await backend.log_message(message, severity, metadata)

class Logger:
    def __init__(self, config: LoggerConfig):
        self.config = config

    async def log_message(self, message: str, severity: int, metadata: dict) -> None:
        await self.config.log_message(message, severity, metadata)
```

Note that this is just a starting point, and you'll need to flesh out the implementation details for each backend and handle potential errors and edge cases. Additionally, you may want to consider using a more robust logging library like Loguru or Tenacity instead of rolling your own.']

