class DataPacket {
public:
    uint64_t id;
    uint64_t timestamp;
    uint32_t payloadSize;
    bool statusFlag;
    // metadata related to source and destination systems
};

class Queue {
private:
    std::queue<DataPacket> packets;
    std::mutex mutex;
    std::condition_variable condition;

public:
    void enqueue(DataPacket packet) {
        std::unique_lock<std::mutex> lock(mutex);
        packets.push(packet);
        lock.unlock();
        condition.notify_one();
    }

    DataPacket dequeue() {
        std::unique_lock<std::mutex> lock(mutex);
        while (packets.empty()) {
            condition.wait(lock);
        }
        DataPacket packet = packets.front();
        packets.pop();
        return packet;
    }
};

