['Here is the code block:

```c
#include <stdlib.h>
#include <stdio.h>
#include <pthread.h>

// Define the record structure
typedef struct {
    long offset;
    int key;
    double value;
} Record;

// Define the memory pool data structure
typedef struct {
    Record* records;
    size_t capacity;
    pthread_mutex_t mutex;
} MemoryPool;

// Define the logging API interface
typedef void (*LoggingCallback)(const char*, const char*);

// Define the database API interface
typedef int (*DatabaseCallback)(const Record*, size_t);

// Function to initialize and return a new memory pool
MemoryPool* memory_pool_create(size_t initial_capacity, LoggingCallback logging_callback, DatabaseCallback database_callback) {
    MemoryPool* pool = (MemoryPool*)malloc(sizeof(MemoryPool));
    pool->records = (Record*)calloc(initial_capacity, sizeof(Record));
    pool->capacity = initial_capacity;
    pthread_mutex_init(&pool->mutex, NULL);
    pool->logging_callback = logging_callback;
    pool->database_callback = database_callback;
    return pool;
}

// Function to add a record to the memory pool
int memory_pool_add_record(MemoryPool* pool, Record* new_record) {
    pthread_mutex_lock(&pool->mutex);

    // Check if the pool needs to be expanded
    if (pool->capacity == 0 || pool->records[pool->capacity - 1].offset != new_record->offset) {
        pool->capacity *= 2;
        pool->records = (Record*)realloc(pool->records, pool->capacity * sizeof(Record));
    }

    // Add the record to the pool
    size_t idx = pool->capacity - 1;
    while (idx > 0 && pool->records[idx].offset < new_record->offset) {
        --idx;
    }
    memmove(&pool->records[idx + 1], &pool->records[idx], (pool->capacity - idx - 1) * sizeof(Record));
    pool->records[idx] = *new_record;

    // Log the memory usage and record metadata
    char buffer[1024];
    sprintf(buffer, "Added record with offset %ld and key %d. Memory used: %zu bytes.", new_record->offset, new_record->key, (size_t)(pool->capacity * sizeof(Record)));
    pool->logging_callback(buffer, "Memory Pool");

    // Persist the record metadata in the database
    pool->database_callback(pool->records, pool->capacity);

    pthread_mutex_unlock(&pool->mutex);
    return 0;
}

// Function to periodically report memory usage and free resources
void memory_pool_report_usage(MemoryPool* pool) {
    pthread_mutex_lock(&pool->mutex);
    char buffer[1024];
    sprintf(buffer, "Memory used: %zu bytes.", (size_t)(pool->capacity * sizeof(Record)));
    pool->logging_callback(buffer, "Memory Pool");
    pthread_mutex_unlock(&pool->mutex);

    // Free any unnecessary resources
    if (pool->capacity > 100000) {
        pool->capacity /= 2;
        pool->records = (Record*)realloc(pool->records, pool->capacity * sizeof(Record));
    }
}

// Function to destroy a memory pool and free its resources
void memory_pool_destroy(MemoryPool* pool) {
    pthread_mutex_lock(&pool->mutex);

    // Log the destruction of the memory pool
    char buffer[1024];
    sprintf(buffer, "Memory Pool destroyed with %zu records.", (size_t)(pool->capacity));
    pool->logging_callback(buffer, "Memory Pool");

    // Free any remaining resources
    free(pool->records);
    pthread_mutex_unlock(&pool->mutex);
}
