#include <iostream>
#include <list>
#include <mutex>
#include <condition_variable>
#include <chrono>

class NFAPI_CRC_INDICATION_PDU_T {
public:
    int RX_UE_INFORMATION_TAG;
    int RNTI;
    int CRC_INDICATION_REL8_TAG;
    std::time_t timestamp;
};

class DynamicLinkedList {
private:
    struct Node {
        NFAPI_CRC_INDICATION_PDU_T data;
        Node* next;
    };

    Node* head;
    Node* tail;
    std::mutex mtx;
    std::condition_variable cv;

public:
    void append(NFAPI_CRC_INDICATION_PDU_T& data) {
        Node* newNode = new Node();
        newNode->data = data;
        newNode->next = nullptr;

        if (head == nullptr) {
            head = tail = newNode;
        } else {
            tail->next = newNode;
            tail = newNode;
        }

        std::unique_lock<std::mutex> lock(mtx);
        cv.notify_one();
    }

    NFAPI_CRC_INDICATION_PDU_T popFront() {
        if (head == nullptr) {
            throw std::runtime_error("List is empty");
        }

        Node* temp = head;
        head = head->next;

        if (head == nullptr) {
            tail = nullptr;
        }

        std::unique_lock<std::mutex> lock(mtx);
        cv.notify_one();

        NFAPI_CRC_INDICATION_PDU_T data = temp->data;
        delete temp;
        return data;
    }

    bool isEmpty() const {
        return head == nullptr;
    }

    void waitUntilNotEmpty() {
        std::unique_lock<std::mutex> lock(mtx);
        cv.wait(lock, [this] { return !isEmpty(); });
    }
};

int main() {
    DynamicLinkedList list;

    // Test the dynamic linked list
    NFAPI_CRC_INDICATION_PDU_T data;
    data.RX_UE_INFORMATION_TAG = 1;
    data.RNTI = 2;
    data.CRC_INDICATION_REL8_TAG = 3;
    data.timestamp = std::time(nullptr);

    list.append(data);

    while (!list.isEmpty()) {
        NFAPI_CRC_INDICATION_PDU_T poppedData = list.popFront();
