class RateLimiter {
public:
    RateLimiter(int rateLimit) : rateLimit_(rateLimit), permits_(0) {}

    bool acquire() {
        std::unique_lock<std::mutex> lock(mutex_);
        while (permits_ == 0) {
            cv_.wait(lock);
        }
        if (--permits_ < 0) {
            ++permits_;
            return false;
        }
        --permits_;
        return true;
    }

private:
    int rateLimit_;
    std::atomic<int> permits_;
    mutable std::mutex mutex_;
    std::condition_variable cv_;
};

