        std::lock_guard<std::mutex> lock(mtx);
        fsas[id] = fsa;
    }

    void set_current_state(int id, int state_id) {
        std::lock_guard<std::mutex> lock(mtx);
        fsas[id].set_current_state(state_id);
    }
};

