import os
import hashlib
import logging
from logging.config import dictConfigFromDict
import threading
import queue
import heapq
import requests

class MD5Library:
    def __init__(self, chunk_size=1024*1024, max_concurrency=10):
        self.chunk_size = chunk_size
        self.max_concurrency = max_concurrency
        self.hash_cache = {}
        self.lock = threading.Lock()
        self.queue = queue.Queue()

    def compute_hash(self, file_path):
        if not os.path.exists(file_path) or not os.access(file_path, os.R_OK):
            raise FileNotFoundError(f"File '{file_path}' not found or inaccessible")

        with open(file_path, 'rb') as f:
            chunk_queue = []
            while True:
                chunk = f.read(self.chunk_size)
                if not chunk:
                    break
                chunk_queue.append(chunk)

        hashes = []
        with self.lock:
            for i in range(0, len(chunk_queue), self.max_concurrency):
                threads = []
                for j in range(i, min(i+self.max_concurrency, len(chunk_queue))):
                    thread = threading.Thread(target=self._compute_chunk_hash, args=(chunk_queue[j],))
                    thread.start()
                    threads.append(thread)
                for thread in threads:
                    thread.join()
                hashes.extend(self.queue.get_many())

        return hashlib.md5(b''.join(hashes)).hexdigest()

    def verify_hash(self, file_path, expected_hash):
        if not os.path.exists(file_path) or not os.access(file_path, os.R_OK):
            raise FileNotFoundError(f"File '{file_path}' not found or inaccessible")

        with open(file_path, 'rb') as f:
            chunk_queue = []
            while True:
                chunk = f.read(self.chunk_size)
                if not chunk:
                    break
                chunk_queue.append(chunk)

        hashes = []
        with self.lock:
            for i in range(0, len(chunk_queue), self.max_concurrency):
                threads = []
                for j in range(i, min(i+self.max_concurrency, len(chunk_queue))):
                    thread = threading.Thread(target=self._compute_chunk_hash, args=(chunk_queue[j],))
                    thread.start()
                    threads.append(thread)
                for thread in threads:
                    thread.join()
                hashes.extend(self.queue.get_many())

        return hashlib.md5(b''.join(hashes)).hexdigest() == expected_hash

    def _compute_chunk_hash(self, chunk):
        hash = hashlib.md5(chunk).hexdigest()
        self.queue.put(hash)

    def _get_logger(self, name):
        log_dict = {
            'version': 1,
            'formatters': {'default': {'format': '%(asctime)s - %(name)s - %(levelname)s: %(message)s'}},
            'handlers': {
                'console': {'class': 'logging.StreamHandler', 'level': logging.INFO, 'formatter': 'default'},
                'file': {'class': 'logging.FileHandler', 'filename': 'logs/{}.log'.format(name), 'mode': 'a', 'level': logging.DEBUG},
            },
            'root': {
                'level': int(os.environ.get('LOG_LEVEL', 20)),
                'handlers': ['console', 'file']
            }
        }
        dictConfigFromDict(log_dict, logging)
        return logging.getLogger(name)

    def run_cli(self):
        while True:
            cmd = input("Enter a command (compute/verify/file_list): ")
            if cmd == "compute":
                file_path = input("Enter the file path: ")
                print(f"Hash computed for {file_path}: {self.compute_hash(file_path)}")
            elif cmd == "verify":
                file_path = input("Enter the file path: ")
                expected_hash = input("Enter the expected hash: ")
                if self.verify_hash(file_path, expected_hash):
                    print(f"Verification successful for {file_path}")
                else:
                    print(f"Verification failed for {file_path}")
            elif cmd == "file_list":
                dir_path = input("Enter the directory path: ")
                files = os.listdir(dir_path)
                for file in files:
                    if os.path.isfile(os.path.join(dir_path, file)):
                        print(file)
            else:
                print("Invalid command. Please try again.")

if __name__ == "__main__":
    library = MD5Library()
    library._get_logger('logger')
    library.run_cli()

# Example usage:
