    state->semaphores = malloc(num_semaphores * sizeof(semaphore_t*));
    pthread_mutex_init(&state->mutex, NULL);
    pthread_cond_init(&state->cond, NULL);

    // ... (initialize semaphores and set up library)
}

// Create a new semaphore
void lib_create_semaphore(lib_state_t* state) {
    int i = 0;
    while (i < state->num_semaphores) {
        if (!state->semaphores[i]->sem) {
            sem_init(state->semaphores[i]->sem, 1, 1);
        }
        i++;
    }
}

// Wait on a semaphore
void lib_wait(lib_state_t* state, int index) {
    pthread_mutex_lock(&state->mutex);
    if (sem_trywait(state->semaphores[index]->sem)) {
        // Handle error
    }
    pthread_mutex_unlock(&state->mutex);
}

// Signal a semaphore
void lib_signal(lib_state_t* state, int index) {
    pthread_mutex_lock(&state->mutex);
    sem_post(state->semaphores[index]->sem);
    pthread_mutex_unlock(&state->mutex);
}

