import java.util.concurrent.ExecutorService;
import java.util.concurrent.Executors;

public class DataIngestionPipeline {
    private ExecutorService executor;
    private Map<String, DataProcessor> processors = new HashMap<>();
    private Map<String, DataSink> sinks = new HashMap<>();

    public DataIngestionPipeline() {
        executor = Executors.newCachedThreadPool();
    }

    public void addProcessor(String id, DataProcessor processor) {
        processors.put(id, processor);
    }

    public void addSink(String id, DataSink sink) {
        sinks.put(id, sink);
    }

    public void startPipeline() {
        for (DataProcessor processor : processors.values()) {
            executor.submit(processor::process);
        }
        for (DataSink sink : sinks.values()) {
            executor.submit(sink::write);
        }
    }

    public void stopPipeline() {
        executor.shutdownNow();
    }

    public interface DataProcessor {
        void process();
    }

    public interface DataSink {
        void write();
    }
}
```

