import java.util.concurrentatomic.AtomicLong;

public class DataProcessor implements Runnable, DataProcessor {
    private AtomicLong processedCount = new AtomicLong(0);
    private int maxProcessingTime;

    public DataProcessor(int maxProcessingTime) {
        this.maxProcessingTime = maxProcessingTime;
    }

    @Override
    public void run() {
        while (true) {
            long start = System.nanoTime();
            // Process data here...
            long end = System.nanoTime();
            if (end - start > maxProcessingTime) {
                processedCount.incrementAndGet();
            }
        }
    }

    public long getProcessedCount() {
        return processedCount.get();
    }
}
```

