import java.io.IOException;
import java.nio.file.Files;
import java.nio.file.Path;

public class DataSink implements Runnable, DataSink {
    private Path dataDir;
    private AtomicLong writtenCount = new AtomicLong(0);

    public DataSink(Path dataDir) {
        this.dataDir = dataDir;
    }

    @Override
    public void run() {
        while (true) {
            // Read data from the processing queue...
            try {
                Files.write(dataDir.resolve("data.txt"), "Data written to file.".getBytes());
                writtenCount.incrementAndGet();
            } catch (IOException e) {
                System.out.println("Error writing data: " + e.getMessage());
            }
        }
    }

    public long getWrittenCount() {
        return writtenCount.get();
    }
}
