from rest_framework.response import Response
from rest_framework.views import APIView
from rest_framework.parsers import FileUploadParser
from rest_framework.status import HTTP_200_OK, HTTP_400_BAD_REQUEST

# Media Ingestion Pipeline
class MediaIngestionPipeline:
    def __init__(self):
        self.api_clients = {
            'api1': {'url': 'https://api1.com', 'timeout': 30},
            'api2': {'url': 'https://api2.com', 'timeout': 60}
        }
        self.thumbnail_services = ['service1', 'service2']

    def ingest_media(self, file):
        # Validate file format and size
        if not file.content_type.startswith('video/') or file.size > 100 * 1024 * 1024:
            return {'error': 'Invalid file format or size'}

        # Extract metadata from API1
        try:
            response = requests.get(self.api_clients['api1']['url'] + '/metadata', files={'file': file}, timeout=self.api_clients['api1']['timeout'])
            if response.status_code == 200:
                metadata = response.json()
            else:
                return {'error': 'Failed to retrieve metadata from API1'}
        except requests.exceptions.RequestException as e:
            # Fallback to API2
            try:
                response = requests.get(self.api_clients['api2']['url'] + '/metadata', files={'file': file}, timeout=self.api_clients['api2']['timeout'])
                if response.status_code == 200:
                    metadata = response.json()
                else:
                    return {'error': 'Failed to retrieve metadata from API2'}
            except requests.exceptions.RequestException as e:
                return {'error': str(e)}

        # Generate thumbnails using thumbnail services
        for service in self.thumbnail_services:
            try:
                response = requests.post(f'https://{service}.com/thumbnails', files={'file': file}, timeout=30)
                if response.status_code == 200:
                    thumbnail_data = response.content
                else:
                    return {'error': f'Failed to generate thumbnail using {service}'}
            except requests.exceptions.RequestException as e:
                # Skip service and continue with next one
                continue

        # Index media in database
        media_object = MediaObject.objects.create(file=file, metadata=metadata)
        thumbnails = []
        for thumbnail_data in thumbnail_data:
            thumbnail = Thumbnail.objects.create(media_object=media_object, data=thumbnail_data)
            thumbnails.append(thumbnail)

        return {'message': 'Media ingested successfully', 'thumbnails': thumbnails}

# API View for Media Ingestion
class MediaIngestionView(APIView):
    parser_classes = [FileUploadParser]

    def post(self, request):
        file = request.data['file']
        response = MediaIngestionPipeline().ingest_media(file)
        return Response(response, status=HTTP_200_OK if 'message' in response else HTTP_400_BAD_REQUEST)

# Thumbnail Generation Service
class ThumbnailGenerationService:
    def __init__(self):
        self.api_url = 'https://thumbnail-service.com'

    def generate_thumbnail(self, file):
        try:
            response = requests.post(self.api_url, files={'file': file}, timeout=30)
            if response.status_code == 200:
                return BytesIO(response.content)
            else:
                return None
        except requests.exceptions.RequestException as e:
            return None

# Database Models
class MediaObject(models.Model):
    file = models.FileField()
    metadata = models.JSONField()

class Thumbnail(models.Model):
    media_object = models.ForeignKey(MediaObject, on_delete=models.CASCADE)
    data = models.BinaryField()
