function renderFooterScripts(scripts) {
  const scriptElements = [];

  // Loop through the array of scripts
  scripts.forEach((script) => {
    const { url, priority } = script;

    // Create a new script element and set its src attribute to the URL
    const scriptElement = document.createElement('script');
    scriptElement.src = url;

    // Set the priority based on the provided value
    if (priority === 'critical') {
      // Add the script to the DOM as soon as possible
      document.documentElement.firstElementChild.appendChild(scriptElement);
    } else if (priority === 'non-critical') {
      // Load the script asynchronously
      const script = document.createElement('script');
      script.src = url;
      script.onload = () => {
        // Add the script to the DOM once it has finished loading
        document.documentElement.firstElementChild.appendChild(script);
      };
    }

    // Store the script elements for later use
    scriptElements.push(scriptElement);
  });
}
