#include <thread>
#include <mutex>

class NFAPI_CRC_INDICATION_PDU_T {
public:
    int RX_UE_INFORMATION_TAG;
    int RNTI;
    int CRC_INDICATION_REL8_TAG;
    bool CRCFLAG;

    NFAPI_CRC_INDICATION_PDU_T(int tag, int rnti, int crcTag, bool flag) 
        : RX_UE_INFORMATION_TAG(tag), RNTI(rnti), CRC_INDICATION_REL8_TAG(crcTag), CRCFLAG(flag) {}
};

class NFAPI_CRC_INDICATION_MANAGER {
public:
    struct Node {
        NFAPI_CRC_INDICATION_PDU_T data;
        Node* next;

        Node(NFAPI_CRC_INDICATION_PDU_T& data, Node* next = nullptr)
            : data(data), next(next) {}
    };

    class ThreadSafeQueue {
    private:
        std::mutex mtx;
        Node* head;
        Node* tail;

    public:
        void enqueue(NFAPI_CRC_INDICATION_PDU_T& data) {
            Node* newNode = new Node(data, nullptr);
            {
                std::lock_guard<std::mutex> lock(mtx);
                if (head == nullptr)
                    head = tail = newNode;
                else
                    tail->next = newNode, tail = newNode;
            }
        }

        NFAPI_CRC_INDICATION_PDU_T dequeue() {
            Node* temp = head;
            NFAPI_CRC_INDICATION_PDU_T data = temp->data;
            {
                std::lock_guard<std::mutex> lock(mtx);
                if (head == tail)
                    head = tail = nullptr;
                else
                    head = head->next, temp = head;
            }
            delete temp;
            return data;
        }

        bool isEmpty() const {
            std::lock_guard<std::mutex> lock(mtx);
            return head == nullptr;
        }
    };

    NFAPI_CRC_INDICATION_MANAGER() : queue(), threadCount(0) {}

    void enqueue(NFAPI_CRC_INDICATION_PDU_T& data) {
        queue.enqueue(data);
    }

    NFAPI_CRC_INDICATION_PDU_T dequeue() {
        while (queue.isEmpty()) {
            // Wait for some indication
            std::this_thread::sleep_for(std::chrono::milliseconds(10));
        }
        return queue.dequeue();
    }

private:
    ThreadSafeQueue queue;
    int threadCount;

    void workerFunction() {
        while (!queue.isEmpty()) {
            NFAPI_CRC_INDICATION_PDU_T data = dequeue();
            // Process the indication
            std::cout << "Processed: " << data.RX_UE_INFORMATION_TAG << ", " << data.RNTI << ", "
                      << data.CRC_INDICATION_REL8_TAG << ", " << (data.CRCFLAG ? "True" : "False") << std::endl;
        }
    }

public:
    void start(int threadCount) {
        this->threadCount = threadCount;
        for (int i = 0; i < threadCount; ++i)
            std::thread(workerFunction).detach();
    }

    ~NFAPI_CRC_INDICATION_MANAGER() {
        // Wait for all threads to finish
        for (int i = 0; i < threadCount; ++i) {
            if (std::this_thread::get_id() != std::thread(i).id)
                std::thread(i).join();
        }
    }
};

int main() {
    NFAPI_CRC_INDICATION_MANAGER manager;
    manager.start(5);

    // Enqueue some indications
    for (int i = 0; i < 10; ++i) {
        NFAPI_CRC_INDICATION_PDU_T indication(i, i * 2, i * 3, i % 2 == 1);
        manager.enqueue(indication);
    }

    return 0;
}
