from kafka import KafkaProducer

app = Flask(__name__)
cache = Cache(app, config={'CACHE_TYPE': 'SimpleCache'})

class FileProcessor:
    def __init__(self):
        self.kafaka_producer = KafkaProducer(bootstrap_servers=['localhost:9092'])

    def process_file(self, file_path):
        with open(file_path, 'rb') as f:
            file_contents = f.read()
        md5_hash = hashlib.md5(file_contents).hexdigest()
        sha256_hash = hashlib.sha256(file_contents).hexdigest()
        return {'md5': md5_hash, 'sha256': sha256_hash}

    def cache_file_hashes(self, hashes):
        cache.set('file_hashes', hashes)

    def send_to_kafka(self, file_path):
        producer = self.kafaka_producer
        with open(file_path, 'rb') as f:
            file_contents = f.read()
        producer.send('file_hashes', value=file_contents)

@app.route('/hash_file', methods=['POST'])
def hash_file():
    file_path = request.files['file'].filename
    file_processor = FileProcessor()
    hashes = file_processor.process_file(file_path)
    file_processor.cache_file_hashes(hashes)
    file_processor.send_to_kafka(file_path)
    return jsonify({'md5': hashes['md5'], 'sha256': hashes['sha256']})

@app.route('/get_hash', methods=['GET'])
def get_hash():
    file_path = request.args.get('file_path')
    if not file_path:
        return jsonify({'error': 'File path is required'})
    file_processor = FileProcessor()
    hashes = cache.get('file_hashes')
    if hashes:
        return jsonify(hashes)
    else:
        return jsonify({'error': 'Hash not found'})

@app.route('/crc_indication', methods=['POST'])
def crc_indication():
    nfa_pi_crc_indication_pdu_t = []
    for i in range(10):
        rx_ue_information_tag = os.urandom(16)
        rnti = int(time.time())
        crc_flag = int(time.time()) % 2
        nfa_pi_crc_indication_pdu_t.append({
            'rx_ue_information_tag': rx_ue_information_tag.hex(),
            'rnti': rnti,
            'crc_flag': crc_flag
        })
    return jsonify(nfa_pi_crc_indication_pdu_t)

if __name__ == '__main__':
