import hashlib
from typing import List
import random
import zlib
import base64
import datetime
import logging
import threading

class FileProcessor:
    def __init__(self):
        self.md5_hasher = hashlib.md5()
        self.sha256_hasher = hashlib.sha256()
        self.file_cache = {}
        self.hash_cache = {}

    def process_file(self, file_path: str) -> None:
        with open(file_path, 'rb') as file:
            while chunk := file.read(4096):
                self.md5_hasher.update(chunk)
                self.sha256_hasher.update(chunk)

    def get_md5_hash(self, file_path: str) -> str:
        if file_path not in self.hash_cache:
            self.process_file(file_path)
            self.hash_cache[file_path] = self.md5_hasher.hexdigest()
        return self.hash_cache[file_path]

    def get_sha256_hash(self, file_path: str) -> str:
        if file_path not in self.hash_cache:
            self.process_file(file_path)
            self.hash_cache[file_path] = self.sha256_hasher.hexdigest()
        return self.hash_cache[file_path]

class CloudStorage:
    def __init__(self):
        self.storage = {}

    def put(self, file_name: str, file_content: bytes) -> None:
        self.storage[file_name] = file_content

    def get(self, file_name: str) -> bytes:
        return self.storage.get(file_name)

class NFAPI_CRC_INDICATION_PDU_T:
    def __init__(self):
        self.RX_UE_INFORMATION_TAG = random.randint(0, 255)
        self.RNTI = random.randint(0, 255)
        self.CRC_INDICATION_REL8_TAG = {
            'CRCFLAG': random.getrandbits(16),
        }

    def to_bytes(self) -> bytes:
        return zlib.compress(base64.b64encode(pickle.dumps(self)))

class AsyncFileProcessor:
    def __init__(self):
        self.queue = queue.Queue()
        self.processing_queue = queue.Queue()

    def put(self, file_path: str) -> None:
        self.queue.put(file_path)

    def get(self) -> bytes:
        return self.queue.get()

    def process_file(self, file_path: str) -> None:
        try:
            with open(file_path, 'rb') as file:
                while chunk := file.read(4096):
                    self.md5_hasher.update(chunk)
                    self.sha256_hasher.update(chunk)
            self.hash_cache[file_path] = {
                'md5': self.md5_hasher.hexdigest(),
                'sha256': self.sha256_hasher.hexdigest(),
            }
        except Exception as e:
            logging.error(f"Error processing file {file_path}: {e}")

    def run(self) -> None:
        while True:
            try:
                file_path = self.queue.get(True, timeout=1)
                if not file_path:
                    break
                self.process_file(file_path)
                self.queue.task_done()
            except queue.Empty:
                pass

if __name__ == '__main__':
    file_processor = FileProcessor()
    cloud_storage = CloudStorage()
    async_file_processor = AsyncFileProcessor()

    # Start processing files in the background
    threading.Thread(target=async_file_processor.run).start()

    # Upload and process a file
    file_path = 'path/to/file.zip'
    md5_hash = file_processor.get_md5_hash(file_path)
    sha256_hash = file_processor.get_sha256_hash(file_path)

    # Store the file in cloud storage
    cloud_storage.put('file_name', open(file_path, 'rb').read())

    # Get the file from cloud storage and process it asynchronously
    async_file_processor.put(file_path)

    # Wait for the processing to finish
    async_file_processor.queue.join()

    # Print the MD5 and SHA256 hashes
    print(f"MD5 Hash: {md5_hash}")
    print(f"SHA256 Hash: {sha256_hash}")

    # Create an NFAPI_CRC_INDICATION_PDU_T structure
    pdu = NFAPI_CRC_INDICATION_PDU_T()
    pdu_bytes = pdu.to_bytes()

    # Store the PDU in cloud storage
    cloud_storage.put('pdu_name', pdu_bytes)

    # Get the PDU from cloud storage and process it asynchronously
    async_file_processor.put('pdu_name')

    # Wait for the processing to finish
    async_file_processor.queue.join()
