// Define a struct to hold file information
struct File {
    std::string path;
    std::string name;
    std::string hash;
};

// Function to compute and return MD5 and SHA-256 hashes of user-uploaded files
File computeHashes(const std::string& filePath) {
    // Initialize file object
    File file;
    file.path = filePath;

    // Compute MD5 hash
    auto md5 = boost::md5(filePath);

    // Compute SHA-256 hash
    auto sha256 = boost::sha2_256(filePath);

    // Store hashes in the file object
    file.name = filePath.substr(filePath.find_last_of('/') + 1);
    file.hash = md5.hex() + ":" + sha256.hex();

    return file;
}

