// Function to handle concurrent uploads and optimize for large files using a streaming approach
void uploadFile(const std::string& filePath) {
    // Open the file stream in binary read mode
    std::ifstream fileStream(filePath, std::ios::binary);

    // Read the file in chunks (e.g., 1 MB at a time)
    while (fileStream) {
        char buffer[1048576];  // Adjust size as needed for optimal performance

        fileStream.read(buffer, sizeof(buffer));
        fileStream.seekg(sizeof(buffer));

        // Compute and store hash of each chunk
        File file;
        file.path = filePath;

        auto md5 = boost::md5(buffer);
        auto sha256 = boost::sha2_256(buffer);

        file.name = filePath.substr(filePath.find_last_of('/') + 1);
        file.hash = md5.hex() + ":" + sha256.hex();

        // Store the chunk in the cloud storage API
        storeFile(file);
    }

    fileStream.close();
}

// Function to handle partial uploads gracefully and validate file integrity
void uploadPartialFile(const std::string& filePath, const int64_t offset, const int64_t length) {
    // Open the file stream in binary read mode
    std::ifstream fileStream(filePath, std::ios::binary);

    // Seek to the desired offset
    fileStream.seekg(offset);

    // Read and process the partial file chunk
    char buffer[length];

    fileStream.read(buffer, length);
    fileStream.seekg(length);

    // Compute and store hash of each chunk
    File file;
    file.path = filePath;

    auto md5 = boost::md5(buffer);
    auto sha256 = boost::sha2_256(buffer);

    file.name = filePath.substr(filePath.find_last_of('/') + 1);
    file.hash = md5.hex() + ":" + sha256.hex();

    // Store the chunk in the cloud storage API
    storeFile(file);
}

int main() {
    // Demonstrate concurrent uploads and streaming approach for large files
    std::vector<std::thread> threads;

    for (int i = 0; i < 10; ++i) {
        threads.emplace_back([this, i]() {
            uploadFile("path/to/large/file" + std::to_string(i));
        });
    }

    for (auto& thread : threads) {
        thread.join();
    }

    return 0;
}
