#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <sys/socket.h>
#include <netinet/in.h>
#include <arpa/inet.h>
#include <unistd.h>
#include <curl/curl.h>

// Define constants
#define MAX_INTS_PER_BATCH 1000
#define BATCH_WRITE_INTERVAL 10 // in seconds
#define RETRY_ATTEMPTS 3

// Data structure to hold validated integers and analytics information
typedef struct {
    int *ints;
    size_t count;
    int highest_int;
} ValidatedData;

// Function prototypes
ValidatedData process_dataset(int sockfd, const char* range_str);
void write_batch_to_disk(ValidatedData* data, CURL* curl);
int send_analytics_request(CURL* curl, int highest_int);

// Main function
int main() {
    // Initialize CURL
    CURL* curl = curl_easy_init();
    if(curl) {
        curl_easy_setopt(curl, CURLOPT_WRITEFUNCTION, NULL);
        curl_easy_setopt(curl, CURLOPT_WRITEDATA, NULL);
    }

    int sockfd = accept(0, 0, 0); // Open a socket to receive data

    ValidatedData data = process_dataset(sockfd, "1-10000"); // Process the dataset
    free(data.ints); // Free dynamically allocated memory

    return 0;
}

// Function to process a large dataset of integers streamed from a high-throughput source
ValidatedData process_dataset(int sockfd, const char* range_str) {
    ValidatedData data = {NULL, 0, INT_MIN};
    size_t batch_count = 0;

    while(1) {
        int num;
        read(sockfd, &num, sizeof(num)); // Read an integer from the socket

        if(num < atoi(range_str)) continue; // Validate against the specified range
        data.count++;

        // Periodically write batches to disk and send analytics requests
        if(data.count % MAX_INTS_PER_BATCH == 0 || (data.count > 10000 && batch_count++ >= BATCH_WRITE_INTERVAL)) {
            write_batch_to_disk(&data, curl);
            int highest_int = data.highest_int;
            send_analytics_request(curl, highest_int);
        }

        // Update the highest integer value encountered
        if(num > data.highest_int) data.highest_int = num;

        // Dynamically allocate memory for validated integers and increment batch count
        if(data.count % MAX_INTS_PER_BATCH == 0 || (data.count > 10000 && batch_count++ >= BATCH_WRITE_INTERVAL)) {
            size_t new_size = (data.count / MAX_INTS_PER_BATCH + 1) * sizeof(int);
            int* new_ints = realloc(data.ints, new_size);
            if(new_ints == NULL) {
                // Handle memory allocation failure gracefully
                data.highest_int = INT_MIN;
                data.count = 0;
                break;
            }
            data.ints = new_ints;
        }

        data.ints[data.count - 1] = num; // Store the validated integer in the dynamically allocated array
    }

    return data;
}

// Function to write a batch of validated integers directly to a persistent storage system
void write_batch_to_disk(ValidatedData* data, CURL* curl) {
    FILE* file = fopen("validated_ints.bin", "wb"); // Open a binary file for writing

    if(file == NULL) {
        // Handle disk I/O failure gracefully
        fclose(file);
        return;
    }

    fwrite(data->ints + (data->count - MAX_INTS_PER_BATCH), sizeof(int), MAX_INTS_PER_BATCH, file); // Write the batch to disk
    fclose(file);

    // Reset the batch count and dynamically allocated memory
    data->batch_count = 0;
    free(data->ints);
    data->ints = NULL;
}

// Function to send the highest integer value encountered to an external analytics service via HTTP POST requests
int send_analytics_request(CURL* curl, int highest_int) {
    CURLcode res;

    // Set up the HTTP request and handle transient failures
    for(int attempt = 0; attempt < RETRY_ATTEMPTS; attempt++) {
        if(attempt > 0) sleep(1); // Implement a retry delay

        curl_easy_setopt(curl, CURLOPT_URL, "https://analytics-service.com/highest_int");
        struct curl_slist* list = NULL;
        list = curl_slist_append(list, "--header 'Content-Type: application/json'");

        char json[256];
        sprintf(json, "{\"highest_int\": %d}", highest_int);

        CURL *easy_handle = curl_easy_init();
        if(easy_handle) {
            curl_easy_setopt(easy_handle, CURLOPT_POSTFIELDS, json);
            res = curl_easy_perform(curl); // Send the request
            curl_easy_cleanup(easy_handle);
        }

        if(res == CURLE_OK) break; // Handle transient failures gracefully

        // Log detailed information for debugging and monitoring purposes
        printf("Failed to send analytics request (attempt %d). Last successfully processed integer: %d. Reason: %s\n", attempt, data.highest_int - 1, curl_easy_strerror(res));
    }

    return res;
}

