            // Validate and process IoT data based on urgency and relevance
            await ValidateAndProcessIoTDataAsync(data, config);

            // Store processed data in Redis cache for efficient retrieval
            await _redisCache.SetStringAsync("iot_data", data.ToJson());
        }

