        {
            var configuration = new Configuration();

            // Load JSON-based configuration file
            using (var stream = File.OpenRead(_configuration["ConfigFile"]))
            {
                using (var reader = new StreamReader(stream))
                {
                    configuration = new JsonConfiguration(reader.ReadToEnd());
