bool validateOAuth2Token(const std::string& tokenJson) {
  Json::Value token;
  try {
    token = Json::loadFromBuffer(tokenJson);
  } catch (const Json::Exception& e) {
    return false; // Invalid JSON
  }

  if (!token["access_token"].isString() || !token["expires_in"].isUInt()) {
    return false; // Missing or invalid fields
  }

  const std::string accessToken = token["access_token"].asString();
  uint expiresIn = token["expires_in"].asUInt();

  if (accessToken.empty() || expiresIn == 0) {
