CREATE TYPE CityType AS (city_name VARCHAR(255), is_valid BOOLEAN);

CREATE OR REPLACE FUNCTION get_city_list(p_city_string IN VARCHAR2)
    RETURN TABLE OF CityType
AS 
BEGIN
    DECLARE city_row CityType;
    DECLARE city_cursor SYS_REFCURSOR;
    OPEN city_cursor FOR SELECT column_value FROM TABLE(SYS.convert_VARCHAR2(DBMS_XMLTABLE.EXtract('/root/City', '/root/City/text()').getColumns(), 'City').COLUMNS) AS c(City);

    LOOP
        FETCH city_cursor INTO city_row;

        IF city_cursor%NOTFOUND THEN
            EXIT;
        END IF;

        INSERT INTO validated_cities (city_name, is_valid)
        VALUES (city_row.city_name, 1);
    END LOOP;

    CLOSE city_cursor;

    SELECT * FROM validated_cities WHERE is_valid = 1;
END get_city_list;

CREATE TABLE employee_details (
    id NUMBER,
    supervisor_id NUMBER,
    first_name VARCHAR2(255),
    last_name VARCHAR2(255),
    email VARCHAR2(255),
    department_id NUMBER,
    job_title VARCHAR2(255),
    hire_date DATE
);

CREATE INDEX idx_employee_details_supervisor_id ON employee_details (supervisor_id);
CREATE INDEX idx_employee_details_department_id ON employee_details (department_id);

CREATE MATERIALIZED VIEW employee_details_mv AS 
SELECT supervisor_id, department_id, COUNT(*) AS count
FROM employee_details
GROUP BY supervisor_id, department_id;

CREATE TABLE job_churn (
    id NUMBER,
    employee_id NUMBER,
    prediction_date DATE,
    probability NUMBER
);

CREATE TRIGGER update_job_churn_trigger
AFTER INSERT OR UPDATE ON employee_details
FOR EACH ROW
BEGIN
    IF NEW.department_id IS NOT NULL THEN
        INSERT INTO job_churn (id, employee_id, prediction_date, probability)
        VALUES ((SELECT COUNT(*) FROM job_churn) + 1, NEW.id, SYSTIMESTAMP, 0.8);
    END IF;
END update_job_churn_trigger;

CREATE TABLE supervisor_notification (
    id NUMBER,
    supervisor_id NUMBER,
    notification_date DATE
);

CREATE OR REPLACE FUNCTION send_supervisor_notification(p_supervisor_id IN NUMBER)
    RETURN INTEGER
AS 
BEGIN
    INSERT INTO supervisor_notification (id, supervisor_id, notification_date)
    VALUES ((SELECT COUNT(*) FROM supervisor_notification) + 1, p_supervisor_id, SYSTIMESTAMP);

    RETURN ROWID.COUNT;
END send_supervisor_notification;

CREATE OR REPLACE FUNCTION get_employee_details(p_supervisor_id IN NUMBER)
    RETURN TABLE OF employee_details
AS 
BEGIN
    SELECT * FROM employee_details WHERE supervisor_id = p_supervisor_id;
END get_employee_details;

CREATE OR REPLACE PROCEDURE get_employee_details_pagination(
    p_supervisor_id IN NUMBER,
    p_limit IN NUMBER,
    p_offset IN NUMBER
) AS 
DECLARE
    v_result TABLE OF employee_details;
BEGIN
    SELECT * INTO v_result FROM (
        SELECT * FROM employee_details WHERE supervisor_id = p_supervisor_id
        ORDER BY department_id, job_title
    ) WHERE ROWNUM <= p_limit OFFSET p_offset;

    DBMS_OUTPUT.PUT_LINE('Fetched ' || TO_CHAR(COUNT(*)) || ' records');
END get_employee_details_pagination;
