from flask import Flask, request, jsonify
import hashlib
import os
import stat
from concurrent.futures import ThreadPoolExecutor, as_completed
from functools import partial

app = Flask(__name__)
app.config["MAX_CONTENT_LENGTH"] = 16 * 1024 * 1024  # 16MB file limit

# Initialize a threaded executor pool for concurrent processing
pool = ThreadPoolExecutor(max_workers=5)

# Function to generate MD5 and SHA-256 hashes in parallel
def process_file(file):
    md5_hash = hashlib.md5()
    sha256_hash = hashlib.sha256()

    def calculate_hashes():
        chunk_size = 4096
        with open(file, "rb") as f:
            while True:
                data = f.read(chunk_size)
                if not data:
                    break
                md5_hash.update(data)
                sha256_hash.update(data)

    pool.submit(calculate_hashes)
    return {"md5": md5_hash.hexdigest(), "sha256": sha256_hash.hexdigest()}

# Endpoint to process a file and return its hashes
@app.route("/process", methods=["POST"])
def process_file_endpoint():
    if request.method == "POST":
        file = request.files["file"]
        file.save("tempfile")
        result = process_file("tempfile")
        os.remove("tempfile")
        return jsonify(result)
    else:
        return jsonify({"error": "Invalid request method"})

# Endpoint to perform concurrent hash calculations
@app.route("/concurrent", methods=["POST"])
def concurrent_hash_endpoint():
    if request.method == "POST":
        file_list = request.get_json()
        results = []
        with ThreadPoolExecutor() as executor:
            futures = [executor.submit(process_file, file) for file in file_list]
            for future in as_completed(futures):
                results.append(future.result())
        return jsonify(results)
    else:
        return jsonify({"error": "Invalid request method"})

# Endpoint to handle rate limiting
@app.route("/rate_limit", methods=["POST"])
def rate_limit_endpoint():
    if request.method == "POST":
        # Implement rate limiting logic here
        return jsonify({"message": "Rate limited"})
    else:
        return jsonify({"error": "Invalid request method"})

if __name__ == "__main__":
    app.run(debug=True)
