package media_streaming_platform;

import java.util.concurrent.ExecutorService;
import java.util.concurrent.Executors;

import com.amazonaws.services.sqs.AmazonSQSClient;
import com.amazonaws.services.sqs.model.SendMessageRequest;
import com.google.cloud.pubsub.v1.AcknowledgeResponse;
import com.google.cloud.pubsub.v1.Message;
import com.google.cloud.pubsub.v1.Subscriber;
import io.dropwizard.lifecycle.Managed;
import io.dropwizard.util.Duration;

public class DataIngestionPipeline implements Managed {

    private final AmazonSQSClient sqsClient;
    private final ExecutorService executorService;
    private final Subscriber subscriber;
    private final AcknowledgeResponse acknowledgeResponse;

    public DataIngestionPipeline(AmazonSQSClient sqsClient, ExecutorService executorService, Subscriber subscriber) {
        this.sqsClient = sqsClient;
        this.executorService = executorService;
        this.subscriber = subscriber;
        this.acknowledgeResponse = new AcknowledgeResponse();
    }

    @Override
    public void start() throws Exception {
        // Start the SQS client
        sqsClient.start();

        // Start the Executor Service
        executorService.submit(() -> {
            try {
                // Subscribe to Pub/Sub topic
                subscriber.subscribe("media-streaming-platform-topic", this::processMessage);
            } catch (Exception e) {
                throw new RuntimeException(e);
            }
        });
    }

    @Override
    public void stop() throws Exception {
        // Stop the Executor Service
        executorService.shutdown();

        // Stop the SQS client
        sqsClient.stop();
    }

    private void processMessage(Message message) {
        // Process the message
        String data = new String(message.getData(), "UTF-8");

        try {
            // Send the message to the message queue
            SendMessageRequest request = new SendMessageRequest("media-streaming-platform-queue", data);
            sqsClient.sendMessage(request);

            // Acknowledge the message
            acknowledgeResponse.ack();
        } catch (Exception e) {
            throw new RuntimeException(e);
        }
    }

}
