// Background Job Scheduler
class BackgroundJobManager {
public:
    void start() {
        std::unique_lock<std::mutex> lock(jobQueueMutex);
        while (!jobQueue.empty()) {
            auto job = jobQueue.front();
            jobQueue.pop();
            // Execute the job asynchronously
            std::thread([this, job]() { executeJob(job); }).detach();
        }
    }

private:
    std::queue<std::function<void()>> jobQueue;
    std::mutex jobQueueMutex;

    void executeJob(std::function<void()> job) {
        try {
            // Validate the job
            if (!job()) {
                return;
            }

            // Execute the job with retry mechanism
            int retryCount = 0;
            while (true) {
                try {
                    job();
                    break;
                } catch (const std::exception& e) {
                    ++retryCount;
                    if (retryCount >= 3) {
                        break;
                    }
                    // Exponential backoff
                    std::this_thread::sleep_for(std::chrono::seconds(retryCount * 2));
                }
            }

        } catch (const std::exception& e) {
            std::cerr << "Error executing job: " << e.what() << std::endl;
        }
    }

    void submitJob(std::function<void()> job) {
        std::unique_lock<std::mutex> lock(jobQueueMutex);
        jobQueue.push(job);
    }
};

