from fastapi.responses import JSONResponse
from fastapi.exception_handler import HTTPException

app = FastAPI()

class FileUpload(BaseModel):
    file: UploadFile

@app.post("/upload_file/")
async def upload_file(file_upload: FileUpload):
    if file_upload.file.content_type.startswith("text/"):
        return {"message": "Text files are not supported"}
    elif file_upload.file.size > 1000000:
        return {"message": "Files larger than 1MB are not allowed"}
    else:
        file_hash = hashlib.md5(file_upload.file.read())
        return {"file_name": file_upload.file.filename, "hash": file_hash.hexdigest()}

@app.post("/compute_hash/")
async def compute_hash(file_path: str):
    if os.path.exists(file_path):
        try:
            with open(file_path, 'rb') as f:
                content = f.read()
            return {"hash": hashlib.sha256(content).hexdigest()}
        except Exception as e:
            return {"message": "Failed to compute hash: {}".format(str(e))}
    else:
        return {"message": "File not found"}

@app.get("/get_file/")
async def get_file(file_name: str):
    if os.path.exists(file_name):
        with open(file_name, 'rb') as f:
            content = f.read()
        return JSONResponse(content=content, media_type="application/octet-stream")
    else:
        return {"message": "File not found"}

class HashingService(BaseModel):
    algorithm: str

@app.post("/hash_file/")
async def hash_file(file_path: str, hashing_service: HashingService):
    if os.path.exists(file_path):
        try:
            with open(file_path, 'rb') as f:
                content = f.read()
            return {"hash": getattr(hashlib, hashing_service.algorithm)(content).hexdigest()}
        except Exception as e:
            return {"message": "Failed to compute hash: {}".format(str(e))}
    else:
        return {"message": "File not found"}

class AuthenticationService(BaseModel):
    username: str
    password: str

@app.post("/authenticate/")
async def authenticate(authentication_service: AuthenticationService):
    if authentication_service.username == "admin" and authentication_service.password == "password":
        return {"authenticated": True}
    else:
        return {"authenticated": False}

if __name__ == "__main__":
    import uvicorn
    uvicorn.run(app, host="0.0.0.0", port=8000)
