#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>

#define MAX_NFAPDU 1000 // Define maximum number of NFAPI_CRC_INDICATION_PDU_T structures

typedef struct {
    char rx_ue_info_tag[16]; // RX_UE_INFORMATION_TAG
    int rnti; // RNTI
    unsigned int crc_flag; // CRCFLAG
} NFAPI_CRC_INDICATION_PDU_T;

// Thread-safe list of NFAPI_CRC_INDICATION_PDU_T structures
typedef struct {
    pthread_mutex_t lock;
    NFAPI_CRC_INDICATION_PDU_T* puds[MAX_NFAPDU];
    int len;
} NFAPDUList;

// Initialize NFAPDUList and lock
NFAPDUList nfapdu_list = {{PTHREAD_MUTEX_INITIALIZER}, {0}, 0};

void nfapdu_init() {
    pthread_mutex_init(&nfapdu_list.lock, NULL);
}

// Add an NFAPI_CRC_INDICATION_PDU_T structure to the list by RNTI
int nfapdu_add(NFAPI_CRC_INDICATION_PDU_T* pudi) {
    pthread_mutex_lock(&nfapdu_list.lock);

    for (int i = 0; i < MAX_NFAPDU; i++) {
        if (!nfapdu_list.puds[i]) {
            nfapdu_list.puds[i] = pudi;
            nfapdu_list.len++;
            break;
        }
    }

    pthread_mutex_unlock(&nfapdu_list.lock);
    return 0;
}

// Retrieve an NFAPI_CRC_INDICATION_PDU_T structure by RNTI
NFAPI_CRC_INDICATION_PDU_T* nfapdu_get(int rnti) {
    pthread_mutex_lock(&nfapdu_list.lock);

    for (int i = 0; i < MAX_NFAPDU; i++) {
        if (nfapdu_list.puds[i] && nfapdu_list.puds[i]->rnti == rnti) {
            NFAPI_CRC_INDICATION_PDU_T* pudi = nfapdu_list.puds[i];
            pthread_mutex_unlock(&nfapdu_list.lock);
            return pudi;
        }
    }

    pthread_mutex_unlock(&nfapdu_list.lock);
    return NULL; // Structure not found or list empty
}

// Delete an NFAPI_CRC_INDICATION_PDU_T structure by RNTI
int nfapdu_delete(int rnti) {
    pthread_mutex_lock(&nfapdu_list.lock);

    for (int i = 0; i < MAX_NFAPDU; i++) {
        if (nfapdu_list.puds[i] && nfapdu_list.puds[i]->rnti == rnti) {
            free(nfapdu_list.puds[i]);
            memmove(&nfapdu_list.puds[i], &nfapdu_list.puds[i + 1], sizeof(NFAPI_CRC_INDICATION_PDU_T*) * (MAX_NFAPDU - i - 1));
            nfapdu_list.len--;
            break;
        }
    }

    pthread_mutex_unlock(&nfapdu_list.lock);
    return 0;
}

void nfapdu_shutdown() {
    pthread_mutex_lock(&nfapdu_list.lock);

    for (int i = 0; i < MAX_NFAPDU; i++) {
        free(nfapdu_list.puds[i]);
    }

    pthread_mutex_unlock(&nfapdu_list.lock);
}
