// Function to extract book names from a string
char** extractBookNames(char* text) {
    char** result = (char**)malloc(1000 * sizeof(char*));
    int i = 0, j = 0;
    for(int k = 0; k < strlen(text); k++) {
        if(text[k] == ' ') {
            continue;
        } else if(text[k] >= 'A' && text[k] <= 'Z') {
            result[i] = (char*)malloc((j+1) * sizeof(char));
            for(int l = 0; l < j+1; l++) {
                result[i][l] = text[k-l-1];
            }
            result[i][j+1] = '\0';
            i++;
            j = 0;
        } else if(text[k] >= 'a' && text[k] <= 'z') {
            j++;
        }
    }
    return result;
}

int main() {
    char* text = "Genesis chapter 1, Exodus chapter 2, Leviticus chapter 3...";
    char** bookNames = extractBookNames(text);

    for(int i = 0; i < strlen(bookNames); i++) {
        printf("%s\n", bookNames[i]);
    }

    return 0;
}

