// Forward declaration of DataPacket structure
class DataPacket;

// Thread-safe dynamic list container for managing packets
class PacketList {
public:
    // Add a packet to the list by PID
    void addPacket(const DataPacket& packet);

    // Retrieve and return a packet by PID, or nullptr if not found
    DataPacket* getPacket(int pid) const;

    // Remove and delete a packet by PID
    void removePacket(int pid);

    // Find and return packets by source IP address
    std::list<DataPacket*> getPacketsBySourceIP(const std::string& ip) const;

    // Find and return packets by destination IP address
    std::list<DataPacket*> getPacketsByDestIP(const std::string& ip) const;
};

// Custom DataPacket structure with timestamp, source IP, dest IP, packet size, and PID fields
class DataPacket {
public:
    int timestamp;
    std::string srcIP;
    std::string destIP;
    int packetSize;
    int pid;

    // Constructor for initializing a new DataPacket instance
    DataPacket(int ts, const std::string& src, const std::string& dst, int ps, int pID)
        : timestamp(ts), srcIP(src), destIP(dst), packetSize(ps), pid(pID) {}
};

// Implementation of PacketList class
PacketList::PacketList() : packets_(), lock_(std::make_unique<std::mutex>()) {}

void PacketList::addPacket(const DataPacket& packet) {
    std::lock_guard<std::mutex> guard(*lock_);
    packets_.emplace_back(packet);
}

DataPacket* PacketList::getPacket(int pid) const {
    std::lock_guard<std::mutex> guard(*lock_);
    for (auto& packet : packets_) {
        if (packet.pid == pid) return &packet;
    }
    return nullptr;
}

void PacketList::removePacket(int pid) {
    std::lock_guard<std::mutex> guard(*lock_);
    for (auto it = packets_.begin(); it != packets_.end(); ++it) {
        if ((*it).pid == pid) {
            packets_.erase(it);
            return;
        }
    }
}

std::list<DataPacket*> PacketList::getPacketsBySourceIP(const std::string& ip) const {
    std::lock_guard<std::mutex> guard(*lock_);
    std::list<DataPacket*> result;
    for (auto& packet : packets_) {
        if (packet.srcIP == ip) result.push_back(&packet);
    }
    return result;
}

std::list<DataPacket*> PacketList::getPacketsByDestIP(const std::string& ip) const {
    std::lock_guard<std::mutex> guard(*lock_);
    std::list<DataPacket*> result;
    for (auto& packet : packets_) {
        if (packet.destIP == ip) result.push_back(&packet);
    }
    return result;
}
