#include <thread>
#include <chrono>

class DataPacket {
public:
    int timestamp;
    std::string sourceIP;
    std::string destinationIP;
    int packetSize;
    int PID;

    DataPacket(int timestamp, const std::string& sourceIP, const std::string& destinationIP, int packetSize, int PID)
        : timestamp(timestamp), sourceIP(sourceIP), destinationIP(destinationIP), packetSize(packetSize), PID(PID) {}
};

class PacketManager {
public:
    static const int MAX_PACKETS = 1000;
    static const int RETRY_WAIT_TIME_MILLIS = 500;

    std::list<DataPacket> packets;
    std::mutex mtx;
    std::map<int, DataPacket*> packetMap;
    std::thread* retryThread = nullptr;

    PacketManager() : packetCount(0) {}

    ~PacketManager() {
        if (retryThread != nullptr) {
            retryThread->join();
        }
    }

    void addPacket(DataPacket* packet) {
        std::unique_lock<std::mutex> lock(mtx);
        packets.push_back(*packet);
        packetMap[packet->PID] = packet;
        packetCount++;
        if (packetCount >= MAX_PACKETS) {
            retryThread = new thread([this]() {
                this->retryPackets();
            });
        }
    }

    void removePacket(int PID) {
        std::unique_lock<std::mutex> lock(mtx);
        auto it = packetMap.find(PID);
        if (it != packetMap.end()) {
            packets.remove_if([&](DataPacket& packet) { return &packet == &(it->second); });
            delete it->second;
            packetMap.erase(it);
            packetCount--;
        }
    }

    void retrievePackets(const std::string& IP) {
        std::unique_lock<std::mutex> lock(mtx);
        for (auto& packet : packets) {
            if (packet.sourceIP == IP || packet.destinationIP == IP) {
                // process the packet
            }
        }
    }

    void retryPackets() {
        while (true) {
            std::this_thread::sleep_for(std::chrono::milliseconds(RETRY_WAIT_TIME_MILLIS));
            for (auto& packet : packets) {
                if (packet.packetSize > 1024) {
                    // retry the packet
                }
            }
        }
    }

private:
    int packetCount;
};

int main() {
    PacketManager pm;

    DataPacket* packet1 = new DataPacket(1, "192.168.0.1", "192.168.0.2", 1024, 1);
    DataPacket* packet2 = new DataPacket(2, "192.168.0.3", "192.168.0.4", 2048, 2);

    pm.addPacket(packet1);
    pm.addPacket(packet2);

    pm.removePacket(1);

    return 0;
}
