#include <string.h>
#include <stdio.h>

#define AES_KEY_SIZE 32 // 256-bit key size
#define IV_SIZE 12      // 96-bit initialization vector size

// Define a structure to hold the encryption context
typedef struct {
    EVP_CIPHER_CTX *ctx;
    uint8_t iv[IV_SIZE];
} encryption_context;

// Initialize an encryption context with a new IV and cipher context
encryption_context* init_encryption_context() {
    encryption_context* ctx = (encryption_context*)malloc(sizeof(encryption_context));
    if (!ctx) return NULL;

    // Generate a random IV
    RAND_bytes(ctx->iv, IV_SIZE);

    // Create a new AES-GCM cipher context
    ctx->ctx = EVP_CIPHER_CTX_new();
    if (!ctx->ctx) {
        free(ctx);
        return NULL;
    }

    // Set the encryption algorithm to AES-256-GCM
    EVP_CIPHER_CTX_set_cipher(ctx->ctx, EVP_aes_256_gcm());
    EVP_CIPHER_CTX_set_padding(ctx->ctx, 0);

    return ctx;
}

// Encrypt data using the given encryption context and key
int encrypt_data(encryption_context* ctx, const uint8_t* key, size_t key_len,
                  const uint8_t* plaintext, size_t plaintext_len, uint8_t** ciphertext) {
    // Set the IV for this encryption session
    EVP_CIPHER_CTX_set_iv(ctx->ctx, ctx->iv, IV_SIZE);

    // Encrypt the data
    int len = 0;
    if (!EVP_EncryptInit_ex(ctx->ctx, NULL, NULL, key, key_len) ||
        !EVP_EncryptUpdate(ctx->ctx, *ciphertext, &len, plaintext, plaintext_len) ||
        !EVP_EncryptFinal_ex(ctx->ctx, *ciphertext + len, &len)) {
        ERR_error_fp(stderr, ctx->ctx);
        return 0;
    }

    // Update the ciphertext length
    *ciphertext = (uint8_t*)realloc(*ciphertext, len + plaintext_len);

    return 1;
}

// Decrypt data using the given encryption context and key
int decrypt_data(encryption_context* ctx, const uint8_t* key, size_t key_len,
                  const uint8_t* ciphertext, size_t ciphertext_len, uint8_t** plaintext) {
    // Set the IV for this decryption session
    EVP_CIPHER_CTX_set_iv(ctx->ctx, ctx->iv, IV_SIZE);

    // Decrypt the data
    int len = 0;
    if (!EVP_DecryptInit_ex(ctx->ctx, NULL, NULL, key, key_len) ||
        !EVP_DecryptUpdate(ctx->ctx, *plaintext, &len, ciphertext, ciphertext_len) ||
        !EVP_DecryptFinal_ex(ctx->ctx, *plaintext + len, &len)) {
        ERR_error_fp(stderr, ctx->ctx);
        return 0;
    }

    // Update the plaintext length
    *plaintext = (uint8_t*)realloc(*plaintext, len);

    return 1;
}

// Clean up an encryption context and release resources
void cleanup_encryption_context(encryption_context* ctx) {
    EVP_CIPHER_CTX_free(ctx->ctx);
    free(ctx);
}
