import java.util.concurrent.Executors;
import java.util.concurrent.LinkedBlockingQueue;
import java.util.concurrent.ThreadFactory;
import java.util.concurrent.ThreadPoolExecutor;

public class DynamicDataPipeline {
    private final ExecutorService executorService;
    private final LinkedBlockingQueue<Runnable> workQueue;
    private final List<DataProcessor> dataProcessors;
    private final SchemaInferenceEngine schemaInferenceEngine;

    public DynamicDataPipeline() {
        this.executorService = Executors.newCachedThreadPool();
        this.workQueue = new LinkedBlockingQueue<>();
        this.dataProcessors = new ArrayList<>();
        this.schemaInferenceEngine = new SchemaInferenceEngine();
    }

    public void addDataProcessor(DataProcessor processor) {
        dataProcessors.add(processor);
    }

    public void processRecord(Record record) {
        workQueue.submit(() -> {
            try {
                schemaInferenceEngine.inferSchema(record);
                for (DataProcessor processor : dataProcessors) {
                    processor.process(record);
                }
            } catch (Exception e) {
                // Log error and continue processing
                System.err.println("Error processing record: " + e.getMessage());
            }
        });
    }

    public void startPipeline() {
        executorService.submit(() -> {
            while (true) {
                try {
                    Runnable task = workQueue.take();
                    executorService.execute(task);
                } catch (InterruptedException e) {
                    Thread.currentThread().interrupt();
                }
            }
        });
    }

    public void shutdownPipeline() {
        executorService.shutdown();
    }
}

class SchemaInferenceEngine {
