    public class DataPipelineManager : IDisposable
    {
        private readonly CancellationTokenSource _cts = new CancellationTokenSource();
        private readonly IDataProvider _dataProvider;
        private readonly IDataTransformer _dataTransformer;
        private readonly IPublisher _publisher;

        public DataPipelineManager(IDataProvider dataProvider, IDataTransformer dataTransformer, IPublisher publisher)
        {
            _dataProvider = dataProvider;
            _dataTransformer = dataTransformer;
            _publisher = publisher;
        }

        public async Task ProcessAsync()
        {
            try
            {
                while (!_cts.IsCancellationRequested)
                {
                    var data = await _dataProvider.GetDataAsync();
                    if (data == null) continue;

                    var transformedData = _dataTransformer.Transform(data);
                    await _publisher.PublishAsync(transformedData);

                    // Monitor and log performance metrics here
                }
            }
            catch (OperationCanceledException)
            {
                // Handle cancellation request
            }
            catch (Exception ex)
            {
                // Log error and notify stakeholders if necessary
            }
        }

        public void Dispose()
        {
            _cts.Cancel();
            _dataProvider.Dispose();
            _dataTransformer.Dispose();
            _publisher.Dispose();
        }
    }

    public interface IDataProvider
    {
        Task<byte[]> GetDataAsync();
    }

    public interface IDataTransformer
    {
        byte[] Transform(byte[] data);
    }

    public interface IPublisher
    {
        Task PublishAsync(byte[] data);
    }
}
