import requests
from cryptography.hazmat.primitives.ciphers import Cipher, algorithms, modes
from cryptography.hazmat.backends import default_backend

class ConfigurationManager:
    def __init__(self):
        self.config = {}
        self.cache = {}

    def load_config(self):
        self.config.update({**os.environ})
        try:
            with open('config.json') as f:
                self.config.update(json.load(f))
        except FileNotFoundError:
            pass
        response = requests.get('https://remote-api.com/config')
        if response.status_code == 200:
            self.config.update(response.json())

    def merge_config(self, config):
        for key, value in config.items():
            if isinstance(value, dict):
                if key not in self.config or not isinstance(self.config[key], dict):
                    self.config[key] = {}
                self.merge_config({key: value})
            else:
                self.config[key] = value

    def save_config(self):
        with open('config.json', 'w') as f:
            json.dump(dict(self.config), f)

    def watch_config(self):
        while True:
            try:
                self.load_config()
                if self.config != self.cache:
                    self.save_config()
                    self.cache = self.config.copy()
                time.sleep(1)
            except Exception as e:
                print(f"Error: {e}")

def decrypt_message(message, key, iv):
    cipher = Cipher(algorithms.TripleDES(key), modes.CBC(iv), backend=default_backend())
    encryptor = cipher.encryptor()
    decrypted_data = encryptor.update(base64.b64decode(message)) + encryptor.finalize()
    return decrypted_data.decode('utf-8')
