import asyncio
from aiohttp import web

async def handle_upload(request):
    # accept POST request with file upload
    form = await request.post()
    if not form.get("file"):
        return web.HTTPBadRequest(text="Invalid file")

    # process file asynchronously using a message broker
    queue_url = "amqp://guest:guest@localhost:5672/"
    queue_name = "uploads"
    async with aiohttp.ClientSession() as session:
        async with session.post(queue_url + queue_name, json={"file": form.get("file")}) as response:
            if response.status == 201:
                return web.HTTPAccepted(text="File uploaded successfully")
            else:
                return web.HTTPInternalServerError(text="Error uploading file")

app = web.Application()
app.add_routes([web.post("/upload", handle_upload)])

if __name__ == "__main__":
    web.run_app(app)
