<?php

namespace MyAPI;

class UserAccountController {
    public function __construct($db) {
        $this->db = $db;
    }

    public function create(UserRequest $request) {
        // validate input and sanitize data
        if (!$request->isValid()) {
            return new Response(400, "Invalid request");
        }

        // perform create operation in database
        $result = $this->db->query("INSERT INTO users (name, email) VALUES (?, ?)", $request->getName(), $request->getEmail());
        if ($result === false) {
            return new Response(500, "Error creating user");
        } else {
            return new Response(201, "User created successfully");
        }
    }

    public function update(UserRequest $request) {
        // validate input and sanitize data
        if (!$request->isValid()) {
            return new Response(400, "Invalid request");
        }

        // perform update operation in database
        $result = $this->db->query("UPDATE users SET name = ?, email = ? WHERE id = ?", $request->getName(), $request->getEmail(), $request->getId());
        if ($result === false) {
            return new Response(500, "Error updating user");
        } else {
            return new Response(200, "User updated successfully");
        }
    }

    public function delete(UserRequest $request) {
        // validate input and sanitize data
        if (!$request->isValid()) {
            return new Response(400, "Invalid request");
        }

        // perform delete operation in database
        $result = $this->db->query("DELETE FROM users WHERE id = ?", $request->getId());
        if ($result === false) {
            return new Response(500, "Error deleting user");
        } else {
            return new Response(204, "User deleted successfully");
        }
    }
}

class UserRequest {
    public $name;
    public $email;
    public $id;

    public function isValid() {
        // validate input data
        if (!isset($this->name) || !isset($this->email) || !isset($this->id)) {
            return false;
        }
        return true;
    }
}
