    location: String,
}

async fn fetch_user_data(api_url: &str) -> Result<User, reqwest::Error> {
    let client = Client::new(api_url.to_string());
    let res = client.get("/users").send().await?;
    match res.status() {
        200 => Ok(res.json::<User>().await?),
        _ => Err(reqwest::Error::from(res)),
    }
}

async fn handle_request(req: &HttpRequest) -> Result<Responder, reqwest::Error> {
    let user_id = req.query("id").unwrap_or_default();
    let username = req.query("username").unwrap_or_default();
    let email = req.query("email").unwrap_or_default();
    let location = req.query("location").unwrap_or_default();

    let mut users: Vec<User> = vec![];

    if !user_id.is_empty() {
        for api_url in API_URLS.iter() {
            if let Ok(user) = fetch_user_data(api_url).await {
                user.id == user_id.parse::<i32>().unwrap()
                    .map(|id| if id == user.id { users.push(user); } else {})
                    .into_iter()
                    .collect()
        }
    }

    if !username.is_empty() {
        for api_url in API_URLS.iter() {
            if let Ok(user) = fetch_user_data(api_url).await {
                user.username.to_lowercase().contains(&username.to_lowercase())
                    .map(|is_match| if is_match { users.push(user); } else {})
                    .into_iter()
                    .collect()
        }
    }

    // Add more filtering criteria as needed

    Ok(web::json(&users))
}

async fn main() {
    let server = HttpServer::new(|| {
        App::new().service(
