                .route(web::get().to(handle_request)),
        )
    })
    .bind("127.0.0.1:8080")?
    .run()
    .await?;

    println!("Server started on 127.0.0.1:8080");
}

const API_URLS: [&str; 3] = [
    "https://api1.example.com",
