    public:
        void loadConfiguration(const YAML::Node& config) {
            for (const auto& service : config["services"].as<std::vector<YAML::Node>>()) {
                services_[service["name"].as<std::string>()] = Service{
                    .name = service["name"].as<std::string>(),
                    .port = service["port"].as<int>(),
                    .enabled = service["enabled"].as<bool>()
                };
            }
        }

        void saveConfiguration(YAML::Node& config) {
            for (const auto& service : services_) {
                YAML::Node serviceConfig;
                serviceConfig["name"] = service.second.name;
                serviceConfig["port"] = service.second.port;
                serviceConfig["enabled"] = service.second.enabled;
                config["services"].push_back(serviceConfig);
            }
        }

    private:
        std::unordered_map<std::string, Service> services_;
    };

