#include <iostream>
#include <memory>
#include <mutex>
#include <thread>
#include <vector>
#include <string>
#include <unordered_map>

class ResourceNode {
public:
    int deviceId;
    std::string hostname;
    std::string ipAddress;
    time_t lastMonitoredTime;
    double currentLoad;

    ResourceNode(int deviceId, const std::string& hostname,
                 const std::string& ipAddress, time_t lastMonitoredTime,
                 double currentLoad)
        : deviceId(deviceId), hostname(hostname),
          ipAddress(ipAddress), lastMonitoredTime(lastMonitoredTime),
          currentLoad(currentLoad) {}
};

class DeviceTree {
public:
    struct Node {
        ResourceNode node;
        std::unique_ptr<Node> left, right;

        Node(ResourceNode& node, std::unique_ptr<Node>& left,
             std::unique_ptr<Node>& right)
            : node(node), left(left), right(right) {}
    };

    class TreeTraversalVisitor {
    public:
        virtual void visit(Node* node) = 0;
    };

    DeviceTree() : root(nullptr) {}

    void insert(ResourceNode& node) {
        Node* newNode = new Node(node, nullptr, nullptr);
        if (root == nullptr) {
            root = std::make_unique<Node>(node, nullptr, nullptr);
        } else {
            traverse(root.get(), newNode);
        }
    }

    void deleteResource(int deviceId) {
        root = removeNode(root.get(), deviceId);
    }

    void traverseTree(TreeTraversalVisitor* visitor) {
        traverse(root.get(), visitor);
    }

private:
    std::unique_ptr<Node> root;

    void traverse(Node* node, TreeTraversalVisitor* visitor) {
        if (node != nullptr) {
            visit(node->node, visitor);
            traverse(node->left.get(), visitor);
            traverse(node->right.get(), visitor);
        }
    }

    void visit(ResourceNode& node, TreeTraversalVisitor* visitor) {
        visitor->visit(&root->node);
    }

    std::unique_ptr<Node> removeNode(Node* node, int deviceId) {
        if (node == nullptr) return nullptr;

        if (deviceId < node->node.deviceId) {
            node->left = removeNode(node->left.get(), deviceId);
        } else if (deviceId > node->node.deviceId) {
            node->right = removeNode(node->right.get(), deviceId);
        } else {
            if (node->left == nullptr && node->right == nullptr) {
                delete node;
                return nullptr;
            } else if (node->left == nullptr || node->right == nullptr) {
                Node* temp = (node->left != nullptr ? node->left.get() : node->right.get());
                delete node;
                return std::make_unique<Node>(temp);
            } else {
                Node* temp = findMinNode(node->right.get());
                node->node = temp->node;
                node->right = removeNode(node->right.get(), temp->node.deviceId);
            }
        }

        if (node->left != nullptr) {
            node->left = removeNode(node->left.get(), deviceId);
        }

        if (node->right != nullptr) {
            node->right = removeNode(node->right.get(), deviceId);
        }

        return std::make_unique<Node>(node->node, std::move(node->left),
                                       std::move(node->right));
    }

    Node* findMinNode(Node* node) {
        while (node->left != nullptr) {
            node = node->left.get();
        }
        return node;
    }
};

int main() {
    // Example usage:
    DeviceTree tree;

    ResourceNode node1(1, "HostA", "192.168.1.100", time(nullptr), 0.5);
    ResourceNode node2(2, "HostB", "192.168.1.101", time(nullptr) - 3600,
                       0.8);

    tree.insert(node1);
    tree.insert(node2);

    // Example error handling:
    try {
        tree.deleteResource(-1); // Invalid input: device ID not found
    } catch (const std::exception& e) {
        std::cerr << "Error: " << e.what() << '\n';
    }

    return 0;
}
```']

