using System;
using System.Net.Http;
using System.Threading.Tasks;

public class DatabaseSender {
    public async Task<DataTableReader> SendBytesToDatabase(byte[] data) {
        using (var client = new HttpClient()) {
            try {
                var response = await client.PostAsync("http://localhost:5000/api/data", new ByteArrayContent(data));
                if (!response.IsSuccessStatusCode) {
                    throw new Exception($"Failed to send data. Status code: {response.StatusCode}");
                }
                return await GetDataTableReader(response);
            } catch (Exception ex) {
                // Handle exception
                return null;
            }
        }
    }

    private async Task<DataTableReader> GetDataTableReader(HttpResponseMessage response) {
        using (var stream = await response.Content.ReadAsStreamAsync()) {
            // Read data table from stream
            return new DataTableReader(stream);
        }
    }
}
