// Thread-safe rate limiter
class RateLimiter {
public:
    explicit RateLimiter(size_t maxRate, size_t burstSize) : 
        maxRate_(maxRate), burstSize_(burstSize), remaining_(0), lastUpdate_(std::chrono::steady_clock::now()) {}

    void acquire() {
        std::unique_lock<std::mutex> lock(mutex_);
        while (remaining_ <= 0) {
            if (cv_.wait_for(lock, std::chrono::milliseconds(1)) == 
                std::cv_status::timeout) {
                // Update rate limits based on user activity patterns
                size_t newRate = updateUserActivity();
                remaining_ = burstSize_ * (newRate / maxRate_);
                lastUpdate_ = std::chrono::steady_clock::now();
            }
        }
        --remaining_;
    }

    bool tryAcquire() {
        std::unique_lock<std::mutex> lock(mutex_);
        if (remaining_ > 0) {
            --remaining_;
            return true;
        } else {
            // Update rate limits based on user activity patterns
            size_t newRate = updateUserActivity();
            remaining_ = burstSize_ * (newRate / maxRate_);
            lastUpdate_ = std::chrono::steady_clock::now();
            return false;
        }
    }

private:
    size_t maxRate_;
    size_t burstSize_;
    size_t remaining_;
    std::chrono::steady_clock::time_point lastUpdate_;
    std::mutex mutex_;
    std::condition_variable cv_;

    // Update rate limits based on user activity patterns
