    // Create a rate limiter with max rate 50,000 and burst size 1000
    RateLimiter rateLimiter(50000, 1000);

    // Start the microservice
    Microservice microservice(rateLimiter);
    std::thread worker([&microservice]() {
        while (true) {
            microservice.handleRequest();
        }
    });
