class RateLimit {
public:
    explicit RateLimit(int limit) : limit_(limit), requests_(0) {}

    bool allow() const;
    void add_request();
    int get_limit() const;

private:
    int limit_;
    int requests_;
};

bool RateLimit::allow() const {
    if (requests_ >= limit_) {
        return false;
    }
    ++requests_;
    return true;
}

void RateLimit::add_request() {
    ++requests_;
}

int RateLimit::get_limit() const {
    return limit_;
}
