import javax.xml.bind.DatatypeConverter;

public class FileProcessingService {
    private static final int BUFFER_SIZE = 1024 * 1024; // 1MB buffer size

    public Map<String, String> processFile(File file) throws IOException {
        Map<String, String> hashes = new HashMap<>();

        try (InputStream inputStream = Files.newInputStream(file.toPath())) {
            MessageDigest md5 = MessageDigest.getInstance("MD5");
            MessageDigest sha256 = MessageDigest.getInstance("SHA-256");

            int bytesRead;
            byte[] buffer = new byte[BUFFER_SIZE];

            while ((bytesRead = inputStream.read(buffer)) != -1) {
                md5.update(buffer, 0, bytesRead);
                sha256.update(buffer, 0, bytesRead);
            }

            byte[] md5HashBytes = md5.digest();
            byte[] sha256HashBytes = sha256.digest();

            hashes.put("MD5", DatatypeConverter.printHexBinary(md5HashBytes));
            hashes.put("SHA-256", DatatypeConverter.printHexBinary(sha256HashBytes));
        }

        return hashes;
    }

