    size_t capacity;
    nic_report_t** reports;
} nic_hash_t;

nic_hash_t* nic_hash_create(size_t capacity) {
    nic_hash_t* hash = (nic_hash_t*)malloc(sizeof(nic_hash_t));
    hash->capacity = capacity;
    hash->reports = (nic_report_t**)calloc(capacity, sizeof(nic_report_t*));
    return hash;
}

void nic_hash_insert(nic_hash_t* hash, int id, float throughput, float packet_loss) {
    // Linear probing for collision resolution
    size_t index = id % hash->capacity;
    while(hash->reports[index]) {
        if(hash->reports[index]->id == id) {
            break; // Report already exists, update it instead
        }
        index = (index + 1) % hash->capacity;
    }
    nic_report_t* report = (nic_report_t*)malloc(sizeof(nic_report_t));
    report->id = id;
    report->throughput = throughput;
    report->packet_loss = packet_loss;
    hash->reports[index] = report;
}

nic_report_t* nic_hash_lookup(nic_hash_t* hash, int id) {
    size_t index = id % hash->capacity;
    while(hash->reports[index]) {
        if(hash->reports[index]->id == id) {
            return hash->reports[index];
        }
        index = (index + 1) % hash->capacity;
    }
    return NULL; // Report not found
}

void nic_hash_delete(nic_hash_t* hash, int id) {
    size_t index = id % hash->capacity;
    while(hash->reports[index]) {
        if(hash->reports[index]->id == id) {
            free(hash->reports[index]);
            hash->reports[index] = NULL; // Mark as deleted
            break;
        }
        index = (index + 1) % hash->capacity;
    }
}

// External monitoring service integration
void monitor_service_report(nic_report_t* report) {
    // Send report to external monitoring service via API or socket
    printf("Sending report: ID=%d, Throughput=%.2f, Packet Loss=%.2f\n", report->id, report->throughput, report->packet_loss);
}

// Real-time alert mechanism
void monitor_service_alert(nic_report_t* report) {
    // Send alert to external monitoring service via API or socket
    if(report->packet_loss > 0.1 || report->throughput < 0.5) {
        printf("Critical issue: ID=%d, Packet Loss=%.2f, Throughput=%.2f\n", report->id, report->packet_loss, report->throughput);
    }
}

// Module initialization and shutdown
void nic_module_init() {
    // Initialize external monitoring service connection
    // ...
}

void nic_module_shutdown() {
    // Shut down external monitoring service connection
    // ...
}

int main() {
    nic_hash_t* hash = nic_hash_create(10000);

    while(1) {
        int id = 0; // Replace with actual ID from data center
        float throughput = 10.5; // Replace with actual throughput value
        float packet_loss = 0.05; // Replace with actual packet loss value

        nic_hash_insert(hash, id, throughput, packet_loss);

        nic_report_t* report = nic_hash_lookup(hash, id);
        if(report) {
            monitor_service_report(report);
            monitor_service_alert(report);
        }
    }

    return 0;
}
