#include <stdlib.h>
#include <string.h>
#include <pthread.h>

// Define struct for record data type
typedef struct {
    long offset;
    int key;
    double value;
} Record;

// Define structure to hold distributed collection of records
typedef struct {
    size_t capacity;
    size_t size;
    Record** records;
    pthread_mutex_t mutex;
    pthread_cond_t cond;
} DistributedCollection;

// Function to initialize a new DistributedCollection
DistributedCollection* init_collection(size_t initial_capacity) {
    DistributedCollection* collection = (DistributedCollection*)malloc(sizeof(DistributedCollection));
    collection->capacity = initial_capacity;
    collection->size = 0;
    collection->records = (Record**)malloc(initial_capacity * sizeof(Record*));
    pthread_mutex_init(&collection->mutex, NULL);
    pthread_cond_init(&collection->cond, NULL);
    return collection;
}

// Function to add a record to the collection
void add_record(DistributedCollection* collection, Record* record) {
    // Lock the mutex for exclusive access
    pthread_mutex_lock(&collection->mutex);

    // Check if the collection needs to be resized
    if (collection->size >= collection->capacity) {
        // Resize the array with a new capacity 2x the current size
        size_t new_capacity = collection->capacity * 2;
        Record** new_records = (Record**)realloc(collection->records, new_capacity * sizeof(Record*));
        collection->records = new_records;
        collection->capacity = new_capacity;
    }

    // Add the record to the end of the array
    collection->records[collection->size] = record;
    collection->size++;

    // Signal other threads that a new record has been added
    pthread_cond_signal(&collection->cond);

    // Unlock the mutex
    pthread_mutex_unlock(&collection->mutex);
}

// Function to get a record from the collection by its key
Record* get_record(DistributedCollection* collection, int key) {
    // Lock the mutex for exclusive access
    pthread_mutex_lock(&collection->mutex);

    // Search for the record with the given key
    size_t i;
    Record** current = collection->records;
    for (i = 0; i < collection->size; i++) {
        if (current[i]->key == key) {
            break;
        }
    }

    // If found, return the record
    if (i < collection->size) {
        Record* record = current[i];
        pthread_mutex_unlock(&collection->mutex);
        return record;
    }

    // If not found, unlock and return NULL
    pthread_mutex_unlock(&collection->mutex);
    return NULL;
}

// Function to free the distributed collection
void free_collection(DistributedCollection* collection) {
    size_t i;
    for (i = 0; i < collection->size; i++) {
        free(collection->records[i]);
    }
    free(collection->records);
    pthread_mutex_destroy(&collection->mutex);
    pthread_cond_destroy(&collection->cond);
    free(collection);
}
