```c++
#include <iostream>
#include <thread>
#include <mutex>
#include <condition_variable>
#include <queue>
#include <map>
#include <unordered_map>
#include <functional>

// Rate limiter class
class RateLimiter {
public:
    RateLimiter(int capacity) : _capacity(capacity), _tokens(_capacity), _lastUpdate(std::chrono::steady_clock::now()) {}

    bool acquireToken() {
        std::lock_guard<std::mutex> lock(_mutex);
        auto now = std::chrono::steady_clock::now();
        if (now - _lastUpdate >= _replenishPeriod) {
            _tokens = _capacity;
            _lastUpdate = now;
        }
        if (_tokens > 0) {
            _tokens--;
            return true;
        } else {
            return false;
        }
    }

private:
    int _capacity;
    std::mutex _mutex;
    std::condition_variable _condVar;
    int _tokens;
    std::chrono::steady_clock::time_point _lastUpdate;
    std::chrono::seconds _replenishPeriod = 1; // replenish tokens every second
};

// Anomaly detection class
class AnomalyDetector {
public:
    AnomalyDetector(int threshold) : _threshold(threshold), _dataQueue({}) {}

    bool detectAnomaly(double value) {
        if (_dataQueue.size() >= _threshold) {
            double avg = 0;
            for (auto val : _dataQueue) {
                avg += val;
            }
            avg /= _dataQueue.size();
            return std::abs(value - avg) > 2 * std::sqrt((std::pow(avg, 2)) / _dataQueue.size());
        } else {
            return false;
        }
    }

private:
    int _threshold;
    std::queue<double> _dataQueue;
};

// Main service class
class RateLimitingService {
public:
    RateLimitingService(int capacity) : _rateLimiter(capacity), _anomalyDetector(5) {}

    void handleRequest() {
        if (_rateLimiter.acquireToken()) {
            // process request
            std::cout << "Processed request" << std::endl;
        } else {
            // rate limit exceeded, reject request
            std::cout << "Rate limit exceeded, rejecting request" << std::endl;
        }
    }

private:
    RateLimiter _rateLimiter;
    AnomalyDetector _anomalyDetector;
};

int main() {
    RateLimitingService service(500000);
    while (true) {
        service.handleRequest();
        std::this_thread::sleep_for(std::chrono::milliseconds(10));
    }
    return 0;
}
```
This code provides a basic implementation of the rate-limiting microservice, including:

* A `RateLimiter` class that manages token distribution and replenishment based on a specified capacity.
* An `AnomalyDetector` class that detects anomalies in data streams using a simple moving average algorithm.
* The main `RateLimitingService` class that integrates the `RateLimiter` and `AnomalyDetector` classes to handle requests and detect anomalies.

Please note that this code is just a starting point, and you will need to modify it to suit your specific requirements.']

