#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <float.h>
#include <pthread.h>

#define MAX_RECORDS 10000
#define LOG_LEVEL 1 // 0: error, 1: warning, 2: info

// Node structure for linked list
typedef struct node {
    int key;
    float temperature;
    struct node* next;
} Node;

// Hash table structure
typedef struct hash_table {
    Node** buckets; // array of pointers to nodes
    size_t size; // number of buckets
    pthread_mutex_t mutex; // mutex for concurrent access
} HashTable;

// Linked list implementation
void linked_list_init(Node** head) {
    *head = NULL;
}

Node* linked_list_insert(Node* head, int key, float temperature) {
    Node* new_node = (Node*)malloc(sizeof(Node));
    new_node->key = key;
    new_node->temperature = temperature;
    new_node->next = head;
    return new_node;
}

// Hash table implementation
void hash_table_init(HashTable* table, size_t capacity) {
    table->buckets = (Node**)malloc(capacity * sizeof(Node*));
    table->size = capacity;
    pthread_mutex_init(&table->mutex, NULL);
}

int hash_function(int key) {
    return key % table->size;
}

void hash_table_insert(HashTable* table, int key, float temperature) {
    size_t index = hash_function(key);
    Node* node = (Node*)malloc(sizeof(Node));
    node->key = key;
    node->temperature = temperature;
    node->next = table->buckets[index];
    table->buckets[index] = node;
}

// Weather API client
void fetch_weather_data(HashTable* table) {
    // TO DO: implement weather API client
    printf("Fetching weather data...\n");
}

// Average temperature calculation
float average_temperature(HashTable* table) {
    float sum = 0.0f;
    size_t count = 0;
    Node* node = NULL;
    pthread_mutex_lock(&table->mutex);
    for (int i = 0; i < table->size; i++) {
        node = table->buckets[i];
        while (node != NULL) {
            sum += node->temperature;
            count++;
            node = node->next;
        }
    }
    pthread_mutex_unlock(&table->mutex);
    return sum / count;
}

// Latest temperature retrieval
float get_latest_temperature(HashTable* table, int key) {
    size_t index = hash_function(key);
    Node* node = table->buckets[index];
    while (node != NULL && node->key != key) {
        node = node->next;
    }
    if (node == NULL || node->key != key) {
        return FLT_MAX; // or some other default value
    }
    return node->temperature;
}

