#include <iostream>
#include <string>
#include <chrono>
#include <vector>
#include <map>
#include <mutex>
#include <condition_variable>
#include <thread>

class Cache {
public:
    // Constructor
    Cache(size_t cacheSize) : cacheSize_(cacheSize), expirationTime_(0), lock_(), cv_()
    {
        cache_.reserve(cacheSize_);
    }

    // Destructor
    ~Cache() {}

    // Put an asset in the cache
    void put(const std::string& uri, const std::chrono::milliseconds& expirationTime,
              const std::vector<uint8_t>& content) {
        if (content.empty()) return;
        if (expirationTime_ > 0) {
            evictionPolicy_(uri);
        }
        asset_.push_back({ uri, expirationTime, content });
    }

    // Get an asset from the cache
    bool get(const std::string& uri, std::vector<uint8_t>& content) {
        for (auto it = asset_.begin(); it != asset_.end();) {
            if (it->uri == uri && it->expirationTime > 0) {
                if (std::chrono::steady_clock::now() < it->expirationTime) {
                    content = it->content;
                    asset_.erase(it);
                    return true;
                }
                else
                    it = asset_.erase(it);
            }
            else
                ++it;
        }
        return false;
    }

private:
    size_t cacheSize_;
    std::chrono::milliseconds expirationTime_;
    mutable std::mutex lock_;
    std::condition_variable cv_;
    std::vector<std::tuple<std::string, std::chrono::milliseconds, std::vector<uint8_t>>> asset_;

    // Eviction policy
    void evictionPolicy_(const std::string& uri) {
        for (auto it = asset_.begin(); it != asset_.end();) {
            if (it->uri == uri && it->expirationTime > 0) {
                if (std::chrono::steady_clock::now() < it->expirationTime) {
                    ++(it->expirationTime);
                }
                else
                    it = asset_.erase(it);
            }
            else
                ++it;
        }
    }

};

int main() {
    Cache cache(10000);  // Initialize the cache with a size of 10,000

    return 0;
}
