**C Function: LoadResourceBundle**
```c
#include <stdio.h>
#include <stdlib.h>
#include <string.h>

typedef struct {
    char* key;
    char* value;
} ResourcePair;

void LoadResourceBundle(char* filePath, void** data) {
    FILE* file = fopen(filePath, "r");
    if (!file) {
        printf("Error opening file: %s\n", filePath);
        return;
    }

    // Parse file contents
    char line[256];
    while (fgets(line, sizeof(line), file)) {
        size_t keyLen = strlen(line) - 1;
        size_t valueLen = strlen(line) - strlen(line) + strlen(line) - 2;
        ResourcePair* pair = (ResourcePair*)malloc(sizeof(ResourcePair));
        pair->key = malloc(keyLen + 1);
        pair->value = malloc(valueLen + 1);

        sscanf(line, "%s:%s", pair->key, pair->value);
        *data = realloc(*data, sizeof(ResourcePair) + keyLen + valueLen + 2);
        ((ResourcePair*)*data)->next = (ResourcePair*)((char*)*data + keyLen + valueLen + 2);
        ((ResourcePair*)*data)->key = pair->key;
        ((ResourcePair*)*data)->value = pair->value;

        free(pair->key);
        free(pair->value);
    }

    fclose(file);
}
