// Java Microservice

import io.vertx.core.Vertx;
import io.vertx.ext.web.Router;
import io.vertx.ext.web.handler.BodyHandler;
import io.vertx.ext.web.handler.CorsHandler;
import io.vertx.ext.mongo.MongoClient;

public class ResourceCatalogService {

    public static void main(String[] args) {
        Vertx vertx = Vertx.vertx();
        Router router = Router.router(vertx);

        // Set up CORS for cross-origin requests
        router.route("/*").handler(CorsHandler.create("*", "*"));

        // Set up MongoDB client
        MongoClient mongoClient = MongoClient.createShared(vertx, "mongodb://localhost:27017");

        // Set up RESTful endpoints for CRUD operations
        router.get("/resources").handler(resourceListHandler(mongoClient));
        router.get("/resources/:id").handler(resourceDetailHandler(mongoClient));
        router.post("/resources").handler(createResourceHandler(mongoClient));
        router.put("/resources/:id").handler(updateResourceHandler(mongoClient));
        router.delete("/resources/:id").handler(deleteResourceHandler(mongoClient));

        // Start the web server
        vertx.createHttpServer().requestHandler(router::accept).listen(8080);
    }

    private static Router resourceListHandler(MongoClient mongoClient) {
        return router().get("/resources")
            .produces("application/json")
            .handler(response -> {
                // Fetch resources from MongoDB
                mongoClient.find("resources", {}, (result) -> {
                    response.putHeader("content-type", "application/json");
                    response.end(Json.encodePrettily(result));
                });
            });
    }

    private static Router resourceDetailHandler(MongoClient mongoClient) {
        return router().get("/resources/:id")
            .produces("application/json")
            .handler(response -> {
                // Fetch resource details from MongoDB
                String id = response.request().getParam(":id");
                mongoClient.find("resources", {"_id": id}, (result) -> {
                    response.putHeader("content-type", "application/json");
                    response.end(Json.encodePrettily(result));
                });
            });
    }

    private static Router createResourceHandler(MongoClient mongoClient) {
        return router().post("/resources")
            .consumes("application/json")
            .handler(request -> {
                // Create a new resource
                String jsonBody = request.getBodyAsJsonString();
                Resource resource = Json.decodeValue(jsonBody, Resource.class);
                mongoClient.insert("resources", resource, (result) -> {
                    response.end(Json.encodePrettily(resource));
                });
            });
    }

    private static Router updateResourceHandler(MongoClient mongoClient) {
        return router().put("/resources/:id")
            .consumes("application/json")
            .handler(request -> {
                // Update an existing resource
                String id = request.getParam(":id");
                String jsonBody = request.getBodyAsJsonString();
                Resource resource = Json.decodeValue(jsonBody, Resource.class);
                mongoClient.update("resources", {"_id": id}, resource, (result) -> {
                    response.end(Json.encodePrettily(resource));
                });
            });
    }

    private static Router deleteResourceHandler(MongoClient mongoClient) {
        return router().delete("/resources/:id")
            .handler(request -> {
                // Delete an existing resource
                String id = request.getParam(":id");
                mongoClient.remove("resources", {"_id": id}, (result) -> {
                    response.end();
                });
            });
    }
}

