<?php

declare(strict_types=1);

namespace SessionManagement;

use Exception;
use PDO;
use PDOException;
use SessionManager;

class SessionManager {
    private $redisConnection;
    private $dbConnection;
    private $tokenStore;

    public function __construct($redisHost, $redisPort, $dbHost, $dbUsername, $dbPassword) {
        try {
            $this->redisConnection = new PDO("redis://{$redisHost}:{$redisPort}");
            $this->dbConnection = new PDO("mysql:host={$dbHost};dbname=session_manager", $dbUsername, $dbPassword);
            $this->tokenStore = new TokenStore($this->redisConnection);
        } catch (PDOException $e) {
            throw new Exception('Database Connection Error: ' . $e->getMessage());
        }
    }

    public function createSession(string $userId): Session {
        $session = new Session();
        $sessionId = $this->generateToken($userId);

        try {
            // Store session in Redis
            $this->redisConnection->exec("SET session:$sessionId " . json_encode($session));

            // Store session in database
            $query = 'INSERT INTO sessions SET user_id=?, created_at=NOW()';
            $statement = $this->dbConnection->prepare($query);
            $statement->execute([$userId]);

            return $session;
        } catch (PDOException $e) {
            throw new Exception('Error creating session: ' . $e->getMessage());
        }
    }

    public function getSession(string $sessionId): Session {
        try {
            // Get session from Redis
            $result = $this->redisConnection->exec("GET session:$sessionId");

            // Validate and return session data
            if ($result) {
                $sessionData = json_decode($result, true);
                $session = new Session();
                foreach ($sessionData as $key => $value) {
                    $session->$key = $value;
                }
                return $session;
            } else {
                throw new Exception('Session not found');
            }
        } catch (PDOException $e) {
            throw new Exception('Error getting session: ' . $e->getMessage());
        }
    }

    public function deleteSession(string $sessionId): void {
        try {
            // Delete session from Redis
            $this->redisConnection->exec("DEL session:$sessionId");

            // Delete session from database
            $query = 'DELETE FROM sessions WHERE id=?';
            $statement = $this->dbConnection->prepare($query);
            $statement->execute([$sessionId]);
        } catch (PDOException $e) {
