        lock.lock();
        try {
            dataPackets.put(key, packet);
        } finally {
            lock.unlock();
        }
    }

    // Retrieve a data packet by PID or IP address
    public DataPacket getDataPacket(String key) {
        lock.lock();
        try {
            return dataPackets.get(key);
        } finally {
            lock.unlock();
        }
    }

    // Delete a data packet by PID or IP address
    public boolean deleteDataPacket(String key) {
        lock.lock();
        try {
            dataPackets.remove(key);
            return true;
        } finally {
            lock.unlock();
        }
    }

