import java.util.concurrent.ExecutorService;
import java.util.concurrent.Executors;

public class LoggingService {

    private static final int DEFAULT_CONCURRENT_PROCESSING = 10;

    private ExecutorService executorService;
    private Map<String, Consumer> consumers;
    private Map<String, Producer> producers;
    private volatile boolean isRunning = true;

    public LoggingService() {
        this.executorService = Executors.newFixedThreadPool(DEFAULT_CONCURRENT_PROCESSING);
        this.consumers = new ConcurrentHashMap<>();
        this.producers = new ConcurrentHashMap<>();
    }

    public void start() {
        Runtime.getRuntime().addShutdownHook(new ShutdownHook(this));
        executorService.submit(() -> processEvents());
    }

    private void processEvents() {
        while (isRunning) {
            Event event;
            if ((event = getNextEvent()) != null) {
                try {
                    consume(event);
                } catch (Exception e) {
                    handleException(e, event);
                }
            } else {
                // Handle empty event queue
            }
        }
    }

    private void consume(Event event) {
        for (Consumer consumer : consumers.values()) {
            executorService.submit(() -> consumer.consume(event));
        }
    }

    private Event getNextEvent() {
        // Implement logic to get the next event from the event queue
    }

    private void handleException(Exception e, Event event) {
        // Implement exception handling logic
    }

    public void addConsumer(String provider, Consumer consumer) {
        consumers.put(provider, consumer);
    }

    public void removeConsumer(String provider) {
        consumers.remove(provider);
    }

    public void addProducer(String provider, Producer producer) {
        producers.put(provider, producer);
    }

    public void removeProducer(String provider) {
        producers.remove(provider);
    }

    private class ShutdownHook extends Thread {
        private LoggingService loggingService;

        public ShutdownHook(LoggingService loggingService) {
            this.loggingService = loggingService;
        }

        @Override
        public void run() {
            isRunning = false;
            executorService.shutdown();
            // Perform any necessary shutdown operations
        }
    }
}

interface Consumer {
    void consume(Event event);
}

interface Producer {
    Event produceEvent();
}
