import hashlib
import os
import io
from PIL import Image
from flask import Flask, request, jsonify, send_file
from werkzeug.utils import secure_filename
from functools import wraps
from flask_caching import Cache
from flask_sqlalchemy import SQLAlchemy
from flask_socketio import SocketIO, emit
from rq import Queue
from redis import Redis

app = Flask(__name__)
app.config['SECRET_KEY'] = 'secret_key_here'
app.config['SQLALCHEMY_DATABASE_URI'] = 'sqlite:///hashservice.db'
app.config['CACHE_TYPE'] = 'RedisCache'
app.config['REDIS_URL'] = 'redis://localhost:6379'

db = SQLAlchemy(app)
cache = Cache(app)
socketio = SocketIO(app)

def async_task(func):
    def wrapper(*args, **kwargs):
        job = Queue().enqueue(func, *args, **kwargs)
        return {'status': 'queued'}
    return wraps(func)(wrapper)

@app.route('/upload', methods=['POST'])
@async_task
def handle_upload():
    file = request.files['file']
    filename = secure_filename(file.filename)
    file.save(os.path.join('uploads', filename))

    # Compute MD5 and SHA-256 hashes
    md5_hash = hashlib.md5(open(f'uploads/{filename}', 'rb').read()).hexdigest()
    sha256_hash = hashlib.sha256(open(f'uploads/{filename}', 'rb').read()).hexdigest()

    # Store hashes in database
    hash_entry = Hashes(filename=filename, md5=md5_hash, sha256=sha256_hash)
    db.session.add(hash_entry)
    db.session.commit()

    return {'status': 'success'}

@app.route('/hash', methods=['GET'])
def get_hash():
    filename = request.args.get('filename')
    hash_entry = Hashes.query.filter_by(filename=filename).first()
    if not hash_entry:
        return jsonify({'error': 'Hash not found'}), 404

    return jsonify({'md5': hash_entry.md5, 'sha256': hash_entry.sha256})

@app.route('/download', methods=['GET'])
def download_file():
    filename = request.args.get('filename')
    file_path = f'uploads/{filename}'

    if os.path.exists(file_path):
        return send_file(file_path, as_attachment=True)
    else:
        return jsonify({'error': 'File not found'}), 404

@app.route('/stats', methods=['GET'])
def get_stats():
    # Get total upload count and size
    total_uploads = Hashes.query.count()
    total_size = sum([os.path.getsize(f'uploads/{hash_entry.filename}') for hash_entry in Hashes.query.all()])

    return jsonify({'total_uploads': total_uploads, 'total_size': total_size})

if __name__ == '__main__':
    socketio.run(app)
```

