package com.oauth2api;

import java.util.ArrayList;
import java.util.List;
import org.springframework.boot.SpringApplication;
import org.springframework.boot.autoconfigure.SpringBootApplication;
import org.springframework.context.annotation.Bean;
import org.springframework.security.authentication.AuthenticationManager;
import org.springframework.security.config.annotation.web.builders.HttpSecurity;
import org.springframework.security.config.annotation.web.configuration.EnableWebSecurity;
import org.springframework.security.config.annotation.web.configuration.WebSecurityConfigurerAdapter;
import org.springframework.security.oauth2.client.registration.InMemoryOAuth2RegistrationRepository;
import org.springframework.security.oauth2.provider.authentication.TokenServices;

@SpringBootApplication
@EnableWebSecurity
public class OAuth2APIServiceApplication extends WebSecurityConfigurerAdapter {

    @Override
    protected void configure(HttpSecurity http) throws Exception {
        http.csrf().disable()
            .oauth2Login().userInfoEndpointUrl("/userinfo")
            .and()
            .authorizeRequests()
            .antMatchers("/login").permitAll()
            .anyRequest().authenticated();
    }

    @Bean
    public AuthenticationManager authenticationManager() {
        return super.authenticationManager();
    }

    @Bean
    public InMemoryOAuth2RegistrationRepository registrationRepository() {
        List<OAuth2ClientRegistration> registrations = new ArrayList<>();
        registrations.add(new Registration(
                "google",
                "https://accounts.google.com{oauthtoken}",
                clientId -> clientId.toString(),
                clientSecret -> clientSecret.toString()));
        registrations.add(new Registration(
                "facebook",
                "https://www.facebook.com{path}",
                clientId -> clientId.toString(),
                clientSecret -> clientSecret.toString()));
        registrations.add(new Registration(
                "github",
                "https://github.com{oauthtoken}",
                clientId -> clientId.toString(),
                clientSecret -> clientSecret.toString()));

        return new InMemoryOAuth2RegistrationRepository(registrations);
    }

    @Bean
    public TokenServices tokenServices() {
        return super.tokenServices();
    }

    public static void main(String[] args) {
        SpringApplication.run(OAuth2APIServiceApplication.class, args);
    }
}

class Registration implements OAuth2ClientRegistration {

    private String registrationId;
    private String authorizationUri;
    private Function<String, String> clientIdFunction;
    private Function<String, String> clientSecretFunction;

    public Registration(String registrationId, String authorizationUri,
                         Function<String, String> clientIdFunction,
                         Function<String, String> clientSecretFunction) {
        this.registrationId = registrationId;
        this.authorizationUri = authorizationUri;
        this.clientIdFunction = clientIdFunction;
        this.clientSecretFunction = clientSecretFunction;
    }
}
