import java.util.LinkedList;
import com.elastic.search.pdu.NFAPI_CRC_INDICATION_PDU_T;

public class CRCIndicationGenerator {
    public static NFAPI_CRC_INDICATION_PDU_T generateCRCIndications(int numEntries) {
        LinkedList<NFAPI_CRC_INDICATION_PDU_T> indicationList = new LinkedList<>();
        for (int i = 0; i < numEntries; i++) {
            NFAPI_CRC_INDICATION_PDU_T indication = new NFAPI_CRC_INDICATION_PDU_T();
            // populate the indication structure
            indication.setIndicationType("CRC");
            indication.setTimestamp(System.currentTimeMillis());
            indicationList.add(indication);
        }
        return indicationList;
    }
}
