}

// Serialize the dynamic array of NFAPI_CRC_INDICATION_PDU_T structures to JSON or binary format
void nfaapi_crc_indication_pdu_serialize(NFAPI_CRC_INDICATION_PDU_T *pdu_array, int N, char *format, FILE *output_file) {
