            json_object_object_add(json_obj, "Field2", field2_obj);
        } else if (format == "BINARY") {
            // Binary serialization logic
        }
    }

    // Write the serialized data to the specified output file
    fwrite(&json_obj, sizeof(json_object), 1, output_file);

    json_decref(json_obj);
}

