public:
    Buffer(size_t capacity) : data_(new double[capacity]) {}

    void push(double value) {
        if (size_ >= capacity_) {
            // resize buffer if full
            capacity_ *= 2;
            data_ = new double[capacity_];
        }
        data_[size_++] = value;
    }

    ~Buffer() {
