class PaymentGateway {
  constructor() {
    this.retryAttempts = 3;
    this.circuitBreakerThreshold = 5; // requests in a minute
  }

  async processPayment(paymentRequest) {
    try {
      await makePayment(paymentRequest);
    } catch (error) {
      if (this.retryAttempts > 0 && error.code === "SERVICE_UNAVAILABLE") {
        await waitAndRetry(this.retryAttempts, this.circuitBreakerThreshold);
        return await this.processPayment(paymentRequest); // retry
      }
      throw error;
    }
  }
}

