import os
import hashlib
import logging
from flask import Flask, request, jsonify
from flask_cors import CORS
from flask_socketio import SocketIO, emit
from threading import Thread
from queue import Queue
from collections import defaultdict
from statistics import mean

app = Flask(__name__)
CORS(app)
socketio = SocketIO(app)

# Define a dictionary to store the available storage providers and their respective hashing algorithms
storage_providers = {
    'AWS': ['md5', 'sha256'],
    'Google Cloud': ['md5', 'sha256'],
    'Azure': ['md5', 'sha256']
}

# Define a function to compute the hash of a file using the specified algorithm
def compute_hash(file_path, algorithm):
    if algorithm == 'md5':
        return hashlib.md5(open(file_path, 'rb').read()).hexdigest()
    elif algorithm == 'sha256':
        return hashlib.sha256(open(file_path, 'rb').read()).hexdigest()

# Define a function to upload a file and compute its hash
def upload_file(file_path):
    # Initialize the queue for concurrent file uploads and hash computations
    queue = Queue()

    def compute_hash_thread(queue):
        while True:
            file_path, algorithm = queue.get()
            if file_path is None:
                break
            try:
                hash_value = compute_hash(file_path, algorithm)
                queue.put((file_path, hash_value))
            except Exception as e:
                print(f"Error computing hash for {file_path}: {e}")

    # Start the thread for concurrent file uploads and hash computations
    Thread(target=compute_hash_thread, args=(queue,)).start()

    # Upload the file in chunks to prevent memory overflow
    with open(file_path, 'rb') as f:
        chunk_size = 1024 * 1024
        while True:
            data = f.read(chunk_size)
            if not data:
                break
            queue.put((file_path, request.args.get('algorithm')))

# Define a route for uploading files and computing their hashes
@app.route('/upload', methods=['POST'])
def upload_file_route():
    file_path = request.files['file'].filename
    algorithm = request.args.get('algorithm')
    if not storage_providers:
        return jsonify({'error': 'No storage provider specified'}), 400

    # Initialize the queue for concurrent file uploads and hash computations
    queue = Queue()

    def compute_hash_thread(queue):
        while True:
            file_path, algorithm = queue.get()
            if file_path is None:
                break
            try:
                hash_value = compute_hash(file_path, algorithm)
                queue.put((file_path, hash_value))
            except Exception as e:
                print(f"Error computing hash for {file_path}: {e}")

    # Start the thread for concurrent file uploads and hash computations
    Thread(target=compute_hash_thread, args=(queue,)).start()

    # Upload the file in chunks to prevent memory overflow
    with open(file_path, 'rb') as f:
        chunk_size = 1024 * 1024
        while True:
            data = f.read(chunk_size)
            if not data:
                break
            queue.put((file_path, algorithm))

    return jsonify({'status': 'File uploaded and hashed successfully'}), 200

# Define a route for retrieving file hashes
@app.route('/hashes', methods=['GET'])
def get_hashes_route():
    # Initialize the dictionary to store the file hashes
    file_hashes = {}

    def retrieve_hashes_thread(file_hashes):
        while True:
            file_path, hash_value = queue.get()
            if file_path is None:
                break
            file_hashes[file_path] = hash_value

    # Start the thread for retrieving file hashes
    Thread(target=retrieve_hashes_thread, args=(file_hashes,)).start()

    return jsonify(file_hashes), 200

if __name__ == '__main__':
    app.run(debug=True)
