NFAPI_CRC_INDICATION_PDU_T** generateNFAPICRCIndications(int N, ServiceContext* service_context, int* error_code) {
    NFAPI_CRC_INDICATION_PDU_T** p = (NFAPI_CRC_INDICATION_PDU_T**)malloc(N * sizeof(NFAPI_CRC_INDICATION_PDU_T*));
    if (!p) {
        *error_code = 1; // Memory allocation failed
        return NULL;
    }

    for (int i = 0; i < N; i++) {
        p[i] = (NFAPI_CRC_INDICATION_PDU_T*)malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T));
        if (!p[i]) {
            *error_code = 1; // Memory allocation failed
            free(p);
            return NULL;
        }

        p[i]->RX_UE_INFORMATION_TAG = rand() % 65536;
        p[i]->RNTI = rand() % 65536 + 1;
        p[i]->CRCFLAG = (uint8_t)rand() % 2;

        if (i > 0 && findDuplicateTag(p, i, error_code)) {
            *error_code = 2; // Duplicate tag found
            free(p);
            return NULL;
        }
    }

    free_service_context(service_context);

    return p;
}

int findDuplicateTag(NFAPI_CRC_INDICATION_PDU_T** p, int N, int* error_code) {
    for (int i = 0; i < N - 1; i++) {
        for (int j = i + 1; j < N; j++) {
            if (p[i]->RX_UE_INFORMATION_TAG == p[j]->RX_UE_INFORMATION_TAG) {
                *error_code = 2; // Duplicate tag found
                return 1;
            }
        }
    }

    return 0;
}

