class TelemetryProcessor {
public:
    TelemetryProcessor(int threads, int queue_size) 
        : stopped(false), threads_(threads), queue_size_(queue_size) {}

    void process(int cell_id, int timestamp, const std::vector<TxPowerData>& tx_power_data) {
        std::unique_lock<std::mutex> lock(mutex_);
        if (stopped_) {
            return;
        }
        queue_.emplace(cell_id, timestamp, tx_power_data);
        cv_.notify_one();
    }

    void start() {
        for (int i = 0; i < threads_; ++i) {
            std::thread([this]() { process_loop(); }).detach();
        }
    }

    void stop() {
        stopped_ = true;
        queue_.clear();
        cv_.notify_all();
    }

private:
    void process_loop() {
        while (!stopped_) {
            int cell_id, timestamp;
            std::vector<TxPowerData> tx_power_data;
            {
                std::unique_lock<std::mutex> lock(mutex_);
                if (queue_.empty()) {
                    cv_.wait(lock);
                }
                auto it = queue_.front();
                queue_.pop();
                cell_id = it.first;
                timestamp = it.second;
                tx_power_data = it.third;
            }
            // process telemetry data
            std::cout << "Processing: cell_id=" << cell_id << ", timestamp=" << timestamp << std::endl;
        }
    }

private:
    bool stopped_;
    int threads_;
    int queue_size_;
    std::mutex mutex_;
    std::condition_variable cv_;
    std::queue<std::tuple<int, int, std::vector<TxPowerData>>> queue_;

};

