// Define the structure for NFAPI_CRC_INDICATION_PDU_T
typedef struct {
    int RX_UE_INFORMATION_TAG;
    char RNTI[10];
    int CRC_INDICATION_REL8_TAG;
    unsigned short crcflag;
} NFAPI_CRC_INDICATION_PDU_T;

// Function to deserialize binary files and verify CRC values
int deserializeNfadata(const char *filename) {
    FILE *file = fopen(filename, "rb");
    if (file == NULL) {
        fprintf(stderr, "Error opening file: %s\n", filename);
        return -1;
    }

    NFAPI_CRC_INDICATION_PDU_T pdu;

    // Read and deserialize the NFAPI_CRC_INDICATION_PDU_T structure
    if (fread(&pdu, sizeof(NFAPI_CRC_INDICATION_PDU_T), 1, file) < 1) {
        fprintf(stderr, "Error reading file: %s\n", filename);
        fclose(file);
        return -2;
    }

    // Verify the CRC value using an external service
    int socket = socket(AF_INET, SOCK_STREAM, 0);
    if (socket < 0) {
        perror("Socket creation failed");
        fclose(file);
        return -3;
    }

    struct sockaddr_in server_addr;
    server_addr.sin_family = AF_INET;
    server_addr.sin_port = htons(8080);

    if (connect(socket, (struct sockaddr *)&server_addr, sizeof(server_addr)) < 0) {
        perror("Connection failed");
        close(socket);
        fclose(file);
        return -4;
    }

    // Send the CRC value to the external service for verification
    char crc_data[1024];
    sprintf(crc_data, "CRCFLAG: %d", pdu.crcflag);

    send(socket, crc_data, strlen(crc_data), 0);

    // Receive the response from the external service
    char response[1024];
    recv(socket, response, sizeof(response), 0);
    fclose(file);
    close(socket);

    // Check the response and handle any errors
    if (atoi(response) != pdu.crcflag) {
        fprintf(stderr, "CRC verification failed: %s\n", filename);
        return -5;
    } else {
        printf("CRC verified successfully for file: %s\n", filename);
        return 0;
    }
}

// Example usage:
int main() {
    deserializeNfadata("example.nfa");
    return 0;
}
