    if (!pool) return NULL;
    pool->buffer = (NFAPI_CRC_INDICATION_PDU_T*)malloc(num_elements * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!pool->buffer) {
        free(pool);
