    free(pool->buffer);
    free(pool);
}

NFAPI_CRC_INDICATION_PDU_T* nfaPI_crc_indication_pdu_pool_allocate(NFAPI_CrcIndicationPduPool* pool) {
    NFAPI_CRC_INDICATION_PDU_T* p = NULL;
    pthread_mutex_lock(&pool->lock);
    if (pool->size > 0) {
        p = &pool->buffer[--pool->size];
    }
    pthread_mutex_unlock(&pool->lock);
    return p;
}

void nfaPI_crc_indication_pdu_pool_deallocate(NFAPI_CrcIndicationPduPool* pool, NFAPI_CRC_INDICATION_PDU_T* p) {
    if (!pool || !p) return;
    pthread_mutex_lock(&pool->lock);
    if (pool->size < pool->size + 1) {
        memcpy(&pool->buffer[pool->size], p, sizeof(NFAPI_CRC_INDICATION_PDU_T));
        pool->size++;
