class PacketStats {
public:
    int packet_count;
    int byte_count;
    double error_rate;
    long timestamp;

    PacketStats() : packet_count(0), byte_count(0), error_rate(0.0), timestamp(0) {}
};

class PacketStatsPool {
private:
    std::map<int, PacketStats> pool;
    std::mutex mutex;
public:
    void addPacketStats(PacketStats stats) {
        std::lock_guard<std::mutex> lock(mutex);
        pool[stats.timestamp] = stats;
    }

    PacketStats getPacketStats(int timestamp) {
        std::lock_guard<std::mutex> lock(mutex);
        auto it = pool.find(timestamp);
        if (it != pool.end()) {
            return it->second;
        } else {
            throw std::out_of_range("Timestamp not found");
        }
    }

    void removePacketStats(int timestamp) {
        std::lock_guard<std::mutex> lock(mutex);
        pool.erase(timestamp);
    }
};

class NetworkMonitoringAPI {
public:
    virtual ~NetworkMonitoringAPI() {}

    virtual void updateStatistics(PacketStats stats) = 0;
};

class RealTimeDataAggregator : public NetworkMonitoringAPI {
private:
    PacketStatsPool packet_stats_pool;

public:
    void updateStatistics(PacketStats stats) override {
        packet_stats_pool.addPacketStats(stats);
    }
};

class VisualizationHandler : public NetworkMonitoringAPI {
private:
    PacketStatsPool packet_stats_pool;

public:
    void updateStatistics(PacketStats stats) override {
