import logging
from threading import Lock
from queue import Queue
import sqlite3
from collections import defaultdict
import time
import os
import re

class RobustLogger:
    def __init__(self):
        self.logger = logging.getLogger('robust_logger')
        self.logger.setLevel(logging.INFO)
        self.formatter = logging.Formatter('%(asctime)s - %(name)s - %(levelname)s - %(message)s')

        # Create a file handler that logs to a file in the specified format
        self.file_handler = logging.FileHandler('logs.log')
        self.file_handler.setFormatter(self.formatter)

        # Add the file handler to the logger
        self.logger.addHandler(self.file_handler)

        # Create a console handler and add it to the logger
        self.console_handler = logging.StreamHandler()
        self.console_handler.setLevel(logging.INFO)
        self.console_handler.setFormatter(self.formatter)
        self.logger.addHandler(self.console_handler)

        self.log_queue = Queue()
        self.log_lock = Lock()

        self.db = sqlite3.connect('logs.db')
        self.cursor = self.db.cursor()

    def capture_log(self, log_message):
        with self.log_lock:
            self.log_queue.put(log_message)

    def format_and_store_log(self):
        while True:
            if not self.log_queue.empty():
                log_message = self.log_queue.get()
                self.logger.info(log_message)
                self.store_log_in_db(log_message)
            time.sleep(0.1)

    def store_log_in_db(self, log_message):
        timestamp = int(time.time())
        level = 'INFO'
        if re.match(r'ERROR', log_message):
            level = 'ERROR'
        elif re.match(r'WARNING', log_message):
            level = 'WARNING'

        self.cursor.execute("INSERT INTO logs (timestamp, level, message) VALUES (?, ?, ?)", (timestamp, level, log_message))
        self.db.commit()

    def query_logs(self, start_time=None, end_time=None, level='INFO'):
        if start_time is None and end_time is None:
            return self.cursor.fetchall()
        elif start_time is not None and end_time is None:
            return self.cursor.execute("SELECT * FROM logs WHERE timestamp >= ?", (start_time,)).fetchall()
        elif start_time is None and end_time is not None:
            return self.cursor.execute("SELECT * FROM logs WHERE timestamp <= ?", (end_time,)).fetchall()
        else:
            return self.cursor.execute("SELECT * FROM logs WHERE timestamp >= ? AND timestamp <= ?", (start_time, end_time)).fetchall()

    def close(self):
        self.file_handler.close()
        self.console_handler.close()
        self.db.close()

if __name__ == '__main__':
    robust_logger = RobustLogger()
    while True:
        log_message = f"{time.time()}: {os.getpid()} - INFO - This is a test log message"
        robust_logger.capture_log(log_message)
        time.sleep(0.1)
```']

