#include <thread>

class PacketStats {
public:
    int packet_count;
    long byte_count;
    float error_rate;
    std::time_t timestamp;

    // Add more fields as needed
};

class PacketStatsPool {
private:
    std::mutex mtx;
    std::condition_variable cv;
    std::queue<PacketStats*> stats_queue;
    std::atomic<int> available_stats(0);
    std::map<std::thread::id, std::unique_ptr<std::thread>> threads;

public:
    void init(int num_stats) {
        for (int i = 0; i < num_stats; ++i) {
            PacketStats* stats = new PacketStats();
            stats->packet_count = 0;
            stats->byte_count = 0;
            stats->error_rate = 0.0f;
            stats->timestamp = std::time(nullptr);
            stats_queue.push(stats);
        }
    }

    PacketStats* get_stats() {
        std::unique_lock<std::mutex> lock(mtx);
        cv.wait(lock, [this] { return !stats_queue.empty(); });
        PacketStats* stats = stats_queue.front();
        stats_queue.pop();
        ++available_stats;
        return stats;
    }

    void put_stats(PacketStats* stats) {
        std::unique_lock<std::mutex> lock(mtx);
        --available_stats;
        stats_queue.push(stats);
        cv.notify_one();
    }
};

