package main

import (
	"context"
	"crypto/rand"
	"fmt"
	"log"
	"net/http"

	"github.com/coreos/go-iptables/iptables"
	"golang.org/x/crypto/bcrypt"
)

// User represents a user with an email, password, and roles.
type User struct {
	Email    string
	Password []byte
	Roles    []string
}

// Session represents an authentication session with a user ID and a set of permissions.
type Session struct {
	UserID int64
	Permissions []string
}

// Authenticator handles user authentication and session management.
type Authenticator struct {
	Users     map[string]User
	Sessions  map[int64]Session
	Cache     map[string][]byte // Cache for faster lookups.
	Eviction  func([]byte) bool // Eviction policy for cache.
	Ratelimit *iptablesextended.RateLimiter
}

func (a *Authenticator) Login(ctx context.Context, email string, password []byte) (*Session, error) {
	// Check if the user exists and their password is correct.
	if _, ok := a.Users[email]; !ok || !ComparePasswords(a.Users[email].Password, password) {
		return nil, fmt.Errorf("invalid username or password")
	}

	// Create a new session for the user.
	session := &Session{
		UserID: int64(len(a.Sessions)),
	}
	a.Sessions[session.UserID] = *session

	// Cache the session to improve performance.
	a.Cache[fmt.Sprintf("%d", session.UserID)] = []byte(session.UserID)

	return session, nil
}

func (a *Authenticator) Logout(ctx context.Context, sessionID int64) error {
	delete(a.Sessions, sessionID)
	delete(a.Cache, fmt.Sprintf("%d", sessionID))
	return nil
