NFAPI_CRC_INDICATION_PDU_T* create_crc_indication_pdu(int num_elements) {
    std::vector<NFAPI_CRC_INDICATION_PDU_T*> pdu_vector(num_elements);

    for (int i = 0; i < num_elements; ++i) {
        NFAPI_CRC_INDICATION_PDU_T* pdu = new NFAPI_CRC_INDATION_PDU_T();

