        std::mt19937 gen(rd());
        std::uniform_int_distribution<> dis(0, 255);
        pdu->rx_ue_info.tag = static_cast<RX_UE_INFORMATION_TAG>(dis(gen));

        // Set RNTI
        pdu->rnti = static_cast<RNTI>(i);

        // Generate random CRCFLAG for CRC_INDICATION_REL8_TAG
        pdu->crc_indication_rel8.crcflag = dis(gen) & 1;

        pdu_vector[i] = pdu;
