// Define a rate limiter class with thread-safe concurrent queue
class RateLimiter {
private:
    int maxRequests;
    int currentRequests;
    std::mutex mtx;
    std::condition_variable cv;

public:
    RateLimiter(int maxRequests) : maxRequests(maxRequests), currentRequests(0) {}

    // Get a rate limit token
    bool acquireToken() {
        std::unique_lock<std::mutex> lock(mtx);
        while (currentRequests >= maxRequests) {
            cv.wait(lock);
        }
        --currentRequests;
        return true;
    }

    // Release a rate limit token when request is processed
    void releaseToken() {
        std::unique_lock<std::mutex> lock(mtx);
        ++currentRequests;
        cv.notify_one();
    }
};

