public class LoggingAndFileProcessingService {

    private static final String ELK_STACK_URL = "your-elk-stack-url";
    private static final String AWS_CLOUDWATCH_REGION = "your-aws-cloudwatch-region";
    private static final String S3_BUCKET_NAME = "your-s3-bucket-name";

    private RestHighLevelClient esClient;
    private CloudWatchAsyncClient cloudWatchClient;
    private S3AsyncClient s3Client;

    public LoggingAndFileProcessingService() {
        // Initialize clients
        this.esClient = new RestHighLevelClient(
                RequestOptions.defaultOptions().setHost(ELK_STACK_URL)
        );
        this.cloudWatchClient = CloudWatchAsyncClient.create();
        this.s3Client = S3AsyncClient.create();

        // Start threads for processing and logging
        ExecutorService executorService = Executors.newFixedThreadPool(5);
        Future<?> future1 = executorService.submit(() -> processAndLogFiles());
        Future<?> future2 = executorService.submit(() -> aggregateAndSendLogs());

        // Wait for both tasks to complete
        try {
            if (!future1.get(10, TimeUnit.SECONDS) || !future2.get(10, TimeUnit.SECONDS)) {
                System.out.println("Tasks did not complete within the given time");
            }
        } catch (InterruptedException | ExecutionException e) {
            Thread.currentThread().interrupt();
            System.out.println("Error occurred while processing tasks: " + e.getMessage());
        } finally {
            executorService.shutdown();
        }
    }

    private void processAndLogFiles() {
        // Process and log files
        File file = new File("/path/to/files");
        try (FileInputStream fis = new FileInputStream(file)) {
            // Process file contents
            String fileContents = FileUtils.readFileToString(fis);
            // Log file metadata
            esClient.get(GetRequest("your-index-name"), RequestOptions.defaultOptions());
            s3Client.putObject(PutObjectRequest.builder()
                    .bucket(S3_BUCKET_NAME)
                    .key("file-key")
                    .build(), ResponseConverterToFuture.of(response -> response.toSync()));
        } catch (FileNotFoundException e) {
            System.out.println("File not found: " + file.getName());
        } catch (IOException e) {
            System.out.println("Error reading file contents: " + e.getMessage());
        }
    }

    private void aggregateAndSendLogs() {
        // Aggregate and send logs
        try {
            Future<?> future = cloudWatchClient.getMetricStatistics(
                    GetMetricStatisticsRequest.builder()
                            .metricDataQueries(List.of(MetricDataQuery.builder()
                                    .id("metric-id")
                                    .metric(new Metric.Builder().build())
                                    .aggregations(List.of(Aggregation.builder().build()))
                                    .build()))
                            .period(300)
                            .build(),
                    RequestOptions.defaultOptions()
            );
            // Send logs to external systems
        } catch (Exception e) {
            System.out.println("Error occurred while aggregating and sending logs: " + e.getMessage());
        }
    }

}
