#include <curl/curl.h>
#include <redis/client.h>

using namespace std;

class RateLimiter {
public:
    RateLimiter(int maxRequestsPerSecond, int durationInMilliseconds) 
        : maxRequestsPerSecond_(maxRequestsPerSecond), durationInMilliseconds_(durationInMilliseconds), 
          requestsPerSecond_(0), lastRequestTime_(chrono::system_clock::now()) {}

    bool isAllowed() {
        auto now = chrono::system_clock::now();
        auto elapsed = (now - lastRequestTime_).count() / 1000.0;
        if (elapsed >= durationInMilliseconds_) {
            requestsPerSecond_ = 0;
            lastRequestTime_ = now;
        }
        return requestsPerSecond_ < maxRequestsPerSecond_;
    }

    void incrementRequests() {
        requestsPerSecond_++;
    }

private:
    int maxRequestsPerSecond_, requestsPerSecond_;
    chrono::time_point<chrono::system_clock> lastRequestTime_;
};

class RateLimiterService {
public:
    RateLimiterService(int maxRequestsPerSecond, int durationInMilliseconds) 
        : rateLimiter_(maxRequestsPerSecond, durationInMilliseconds), redisClient_("localhost", 6379) {}

    void handleRequest(string requestID) {
        if (!rateLimiter_.isAllowed()) {
            // Send error response
            return;
        }
        rateLimiter_.incrementRequests();

        // Process the request
        auto start = chrono::system_clock::now();
        processRequest(requestID);
        auto end = chrono::system_clock::now();
        auto latency = (end - start).count() / 1000.0;

        // Log request metrics
        logRequestMetrics(requestID, latency);

        // Update Redis cache with the new request count
        redisClient_.set("requests_per_second", to_string(rateLimiter_.requestsPerSecond_));
    }

private:
    RateLimiter rateLimiter_;
    redis::client redisClient_;

    void processRequest(string requestID) {
        // Simulate processing a request
        this_thread::sleep_for(chrono::milliseconds(rand() % 1000 + 1));
    }

    void logRequestMetrics(string requestID, double latency) {
        // Log the request metrics to a file or database
        cout << "Request ID: " << requestID << ", Latency: " << latency << " ms" << endl;
    }
};

int main() {
    RateLimiterService rateLimiterService(50, 1000);
    for (int i = 0; i < 50000; ++i) {
        rateLimiterService.handleRequest(to_string(i));
    }
    return 0;
}
