const { readdir, stat, promises: { mkdir, unlink } } = require('fs');
const { promisify } = require('util');
const express = require('express');
const app = express();
const axios = require('axios');
const compression = require('compression');

// Define constants for API and service settings
const API_URL = 'https://api.example.com';
const MAX_CONCURRENT_REQUESTS = 5;
const LOG_LEVEL = 'debug';

// Set up file system operations as promises
const mkdirP = promisify(mkdir);
const unlinkP = promisify(unlink);

// Initialize the metadata service client
const getMetadata = async (file) => {
  try {
    const response = await axios.get(`${API_URL}/metadata/${file.name}`);
    return response.data;
  } catch (error) {
    console.error(`Error fetching metadata for ${file.name}:`, error);
    return null;
  }
};

// Define a function to process files asynchronously
async function processFiles(dirPath, userCriteria, options = {}) {
  const files = await readdir(dirPath);
  let filteredFiles = [];

  for (const file of files) {
    try {
      const statResult = await stat(`${dirPath}/${file}`);
      if (!statResult.isDirectory()) {
        const metadata = await getMetadata({ name: file });
        if (metadata && userCriteria(metadata)) {
          filteredFiles.push({ path: `${dirPath}/${file}`, metadata });
        }
      }
    } catch (error) {
      console.error(`Error processing ${file}:`, error);
    }
  }

  // Apply pagination and filtering
  const paginatedFiles = [];
  for (let i = 0; i < filteredFiles.length; i += options.limit) {
    paginatedFiles.push(filteredFiles.slice(i, i + options.limit));
  }

  return paginatedFiles;
}

// Define a route to handle file processing requests
app.get('/process', async (req, res) => {
  const dirPath = req.query.dir;
  const userCriteria = req.query.criterion;
  const options = { limit: parseInt(req.query.limit || '10') };

  try {
    const files = await processFiles(dirPath, userCriteria, options);
    res.json(files);
  } catch (error) {
    console.error(`Error processing files:`, error);
    res.status(500).send({ message: 'Internal Server Error' });
  }
});

// Enable Gzip compression for the API
app.use(compression());

// Start the server and listen for incoming requests
const port = process.env.PORT || 3000;
app.listen(port, () => {
  console.log(`Server started on port ${port} (${LOG_LEVEL})`);
});
