import boto3
from google.cloud import storage
from azure.storage.blob import BlobServiceClient

class CloudStorage:
    def __init__(self):
        self.aws_s3 = boto3.client('s3')
        self.google_cloud_storage = storage.Client()
        self.azure_blob_storage = BlobServiceClient()

    def put_object(self, bucket_name, object_name, data):
        if bucket_name == 'aws':
            self.aws_s3.put_object(Body=data, Bucket=bucket_name, Key=object_name)
        elif bucket_name == 'google':
            self.google_cloud_storage.bucket(bucket_name).blob(object_name).upload_from_string(data)
        elif bucket_name == 'azure':
            self.azure_blob_storage.get_service_client().get_container_client(bucket_name).get_blob_client(object_name).upload_blob(data)

    def get_object(self, bucket_name, object_name):
        if bucket_name == 'aws':
            return self.aws_s3.get_object(Bucket=bucket_name, Key=object_name)['Body'].read()
        elif bucket_name == 'google':
            return self.google_cloud_storage.bucket(bucket_name).blob(object_name).download_as_string()
        elif bucket_name == 'azure':
            return self.azure_blob_storage.get_service_client().get_container_client(bucket_name).get_blob_client(object_name).download_blob().content_as_text()

class HashingService:
    def __init__(self):
        self.md5 = hashlib.md5()
        self.sha256 = hashlib.sha256()

    def hash_file(self, file_path):
        with open(file_path, 'rb') as file:
            data = file.read()
            self.md5.update(data)
            self.sha256.update(data)

class DistributedLogger:
    def __init__(self):
        self.loggers = []

    def add_logger(self, logger):
        self.loggers.append(logger)

    def log(self, message):
        for logger in self.loggers:
            logger.log(message)

class ModularService:
    def __init__(self):
        self.cloud_storage = CloudStorage()
        self.hashing_service = HashingService()
        self.distributed_logger = DistributedLogger()

    def upload_file(self, file_path, bucket_name):
        data = open(file_path, 'rb').read()
        self.cloud_storage.put_object(bucket_name, os.path.basename(file_path), data)
        self.hashing_service.hash_file(file_path)
        self.distributed_logger.log(f"File uploaded to {bucket_name} and hashed")

    def download_file(self, bucket_name, file_name):
        data = self.cloud_storage.get_object(bucket_name, file_name)
        open(os.path.join('downloads', file_name), 'wb').write(data)

if __name__ == '__main__':
    service = ModularService()
    service.upload_file('path/to/file.txt', 'aws')
    service.download_file('aws', 'file.txt')
