import os
import boto3
from google.cloud import storage as gcs
from azure.storage.blob import BlobServiceClient
import hashlib
from urllib.parse import urlparse
from datetime import datetime

class FileStorageService:
    def __init__(self):
        self.aws_s3 = None
        self.google_cloud_storage = None
        self.azure_blob_storage = None

    def set_storages(self, aws_access_key_id, aws_secret_access_key, google_credential_file, azure_account_name, azure_account_key):
        if aws_access_key_id and aws_secret_access_key:
            self.aws_s3 = boto3.client('s3', aws_access_key_id=aws_access_key_id, aws_secret_access_key=aws_secret_access_key)

        if google_credential_file:
            self.google_cloud_storage = gcs.Client.from_service_account_json(google_credential_file)

        if azure_account_name and azure_account_key:
            self.azure_blob_storage = BlobServiceClient(account_url=f"https://{azure_account_name}.blob.core.windows.net/", credential=azure_account_key)

    def upload_file(self, file_path, storage_provider):
        # choose the right storage provider based on user preference
        if storage_provider == 'aws_s3':
            bucket_name = urlparse(file_path).netloc
            self.aws_s3.put_object(Body=open(file_path, 'rb'), Bucket=bucket_name)
        elif storage_provider == 'google_cloud_storage':
            bucket_name = urlparse(file_path).path.split('/')[1]
            blob = self.google_cloud_storage.bucket(bucket_name).blob(os.path.basename(file_path))
            blob.upload_from_string(open(file_path, 'rb').read())
        elif storage_provider == 'azure_blob_storage':
            container_name = urlparse(file_path).netloc
            blob_service_client = BlobServiceClient(account_url=f"https://{container_name}.blob.core.windows.net/")
            blob_client = blob_service_client.get_blob_client(container_name)
            with open(file_path, 'rb') as file:
                blob_client.upload_blob(os.path.basename(file), data=file.read(), overwrite=True)

    def hash_file(self, file_path):
        # choose the right hashing algorithm based on user preference
        if os.path.exists(file_path):
            with open(file_path, 'rb') as file:
                content = file.read()
                md5_hash = hashlib.md5(content).hexdigest()
                sha256_hash = hashlib.sha256(content).hexdigest()
                return md5_hash, sha256_hash
        else:
            return None

    def get_file_version(self, storage_provider, bucket_name, file_name):
        if storage_provider == 'aws_s3':
            response = self.aws_s3.list_objects(Bucket=bucket_name)
            for obj in response['Contents']:
                if obj['Key'] == file_name:
                    return obj['LastModified']
        elif storage_provider == 'google_cloud_storage':
            bucket = self.google_cloud_storage.bucket(bucket_name)
            blob = bucket.blob(file_name)
            return blob.time_created
        elif storage_provider == 'azure_blob_storage':
            container_client = self.azure_blob_storage.get_container_client(container_name=bucket_name)
            blob_client = container_client.get_blob_client(file_name)
            return blob_client.get_tags()['x-ms-last-modified']
