EventQueue* event_queue_create(size_t initial_capacity) {
    EventQueue* queue = (EventQueue*)malloc(sizeof(EventQueue));
    queue->events = (DeviceEvent*)calloc(initial_capacity, sizeof(DeviceEvent));
    queue->capacity = initial_capacity;
    queue->size = 0;
    pthread_mutex_init(&queue->mutex, NULL);
    pthread_cond_init(&queue->cond, NULL);
    return queue;
}

void event_queue_destroy(EventQueue* queue) {
    free(queue->events);
    pthread_mutex_destroy(&queue->mutex);
    pthread_cond_destroy(&queue->cond);
    free(queue);
}

int event_queue_add(EventQueue* queue, DeviceEvent* event) {
    pthread_mutex_lock(&queue->mutex);
    if (queue->size >= queue->capacity) {
        // Realloc and grow capacity
        size_t new_capacity = queue->capacity * 2;
        DeviceEvent* new_events = (DeviceEvent*)realloc(queue->events, new_capacity * sizeof(DeviceEvent));
        queue->events = new_events;
        queue->capacity = new_capacity;
    }
    memcpy(&queue->events[queue->size], event, sizeof(DeviceEvent));
    queue->size++;
    pthread_cond_signal(&queue->cond);
    pthread_mutex_unlock(&queue->mutex);
    return 0;
}

int bulk_add_events(EventQueue* queue, DeviceEvent** events, size_t num_events) {
