public:
    explicit RateLimiter(size_t maxRequestsPerSecond) : maxRequestsPerSecond_(maxRequestsPerSecond), requestsMade_(0), lastRequestTime_(std::chrono::steady_clock::now()) {}

    bool isReadyForNewRequest() {
        std::chrono::duration<double> requestInterval = std::chrono::steady_clock::now() - lastRequestTime_;
        if (requestInterval.count() < 1. / maxRequestsPerSecond_) {
            return false;
        }
        requestsMade_ = 0;
        return true;
    }

    void makeRequest() {
        ++requestsMade_;
        lastRequestTime_ = std::chrono::steady_clock::now();
    }

