#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>
#include <sys/socket.h>
#include <netinet/in.h>
#include <arpa/inet.h>

#define MAX_CONCURRENT_CONNECTIONS 1000
#define MAX_BUFFER_SIZE 1024

typedef struct {
    int max_value;
    pthread_mutex_t mutex;
} stream_processor_state;

stream_processor_state* stream_processor_init() {
    stream_processor_state* state = (stream_processor_state*)malloc(sizeof(stream_processor_state));
    state->max_value = INT_MIN;
    pthread_mutex_init(&state->mutex, NULL);
    return state;
}

void* process_stream(void* arg) {
    stream_processor_state* state = (stream_processor_state*)arg;
    int sock = *((int*)arg + 1);

    while (1) {
        char buffer[MAX_BUFFER_SIZE];
        int bytes_read = recv(sock, buffer, MAX_BUFFER_SIZE, 0);
        if (bytes_read < 0) {
            // handle error
            continue;
        }
        int value = *(int*)buffer;
        pthread_mutex_lock(&state->mutex);
        state->max_value = fmax(state->max_value, value);
        pthread_mutex_unlock(&state->mutex);
    }

    return NULL;
}

void stream_processor_start(stream_processor_state* state) {
    pthread_t threads[MAX_CONCURRENT_CONNECTIONS];
    for (int i = 0; i < MAX_CONCURRENT_CONNECTIONS; i++) {
        int sock = socket(AF_INET, SOCK_STREAM, 0);
        inet_pton(AF_INET, "127.0.0.1", &(struct sockaddr_in){ .sin_family = AF_INET });
        connect(sock, (struct sockaddr*)&(struct sockaddr_in){ .sin_family = AF_INET }, sizeof(struct sockaddr_in));
        pthread_create(&threads[i], NULL, process_stream, state);
    }
}

void stream_processor_shutdown(stream_processor_state* state) {
    // implement shutdown logic here
