using System;
using System.Collections.Generic;
using System.Data;
using System.Data.SqlClient;
using System.Linq;
using System.Threading.Tasks;
using Microsoft.Azure.SqlDatabase.ElasticQuery;

public class DatabaseService : IDatabaseService
{
    private readonly ConnectionStringBuilder _connectionStringBuilder;
    private readonly ILogger _logger;
    private readonly IPDFConverter _pdfConverter;

    public DatabaseService(ConnectionStringBuilder connectionStringBuilder, ILogger logger, IPDFConverter pdfConverter)
    {
        _connectionStringBuilder = connectionStringBuilder;
        _logger = logger;
        _pdfConverter = pdfConverter;
    }

    public async Task ExecuteParameterizedQueryAsync(string query, Dictionary<string, string> parameters)
    {
        try
        {
            using (var connection = new SqlConnection(_connectionStringBuilder.ConnectionString))
            {
                await connection.OpenAsync();

                using (var command = new SqlCommand(query, connection))
                {
                    foreach (var parameter in parameters)
                    {
                        command.Parameters.AddWithValue(parameter.Key, parameter.Value);
                    }

                    using (var reader = command.ExecuteReader())
                    {
                        // Process the query results
                    }
                }
            }

            await _pdfConverter.ConvertJpegToPdfAsync("path/to/jpeg/file.jpg", "output.pdf");
        }
        catch (SqlException ex) when (ex.Number == 109, Message.Contains("Timeout"))
        {
            // Handle timeout error
            await HandleErrorAsync(ex);
        }
        catch (SqlException ex) when (ex.Number == 1214, Message.Contains("Connection terminated by server"))
        {
            // Handle connection terminated by server error
            await HandleErrorAsync(ex);
        }
        catch (Exception ex)
        {
            // Handle any other exceptions
            await HandleErrorAsync(ex);
        }
    }

    private async Task HandleErrorAsync(Exception ex)
    {
        _logger.LogError(ex, "Error executing parameterized query");

        // Retry logic for transient database failures
        if (ex is SqlException sqlEx && sqlEx.Number == 109) // Timeout error
        {
            await Task.Delay(5000); // Wait for 5 seconds before retrying
            try
            {
                await ExecuteParameterizedQueryAsync(query, parameters);
            }
            catch
            {
                // Log the exception and stop retrying
                _logger.LogError(ex, "Error executing parameterized query after retry");
            }
        }

        // Send alert notification if necessary
        if (ex is SqlException sqlEx2 && sqlEx2.Number == 1214) // Connection terminated by server error
        {
            await SendAlertNotificationAsync();
        }
    }

    private async Task SendAlertNotificationAsync()
    {
        // Implement logic to send email or SMS alert notification
    }
}

public interface IDatabaseService
{
    Task ExecuteParameterizedQueryAsync(string query, Dictionary<string, string> parameters);
}

public class ConnectionStringBuilder
{
    public string ConnectionString { get; set; }

    public ConnectionStringBuilder(string connectionString)
    {
        ConnectionString = connectionString;
    }
}

public interface IPDFConverter
{
    Task ConvertJpegToPdfAsync(string inputFilePath, string outputFilePath);
}
