import importlib.util
import logging
import requests
from concurrent.futures import ThreadPoolExecutor, as_completed

class TestFramework:
    def __init__(self):
        self.logger = logging.getLogger('test_framework')
        self.logger.setLevel(logging.INFO)

    def run_tests(self, module_name: str, test_suite: list, api_client):
        try:
            # Dynamically load the module
            module_spec = importlib.util.spec_from_file_location(module_name)
            module = importlib.util.module_from_spec(module_spec)
            module_spec.loader.exec_module(module)

            results = {}
            with ThreadPoolExecutor() as executor:
                futures = {executor.submit(self.execute_test, test_func, api_client): test_func for test_func in test_suite}
                for future in as_completed(futures):
                    test_result = future.result()
                    if test_result['success']:
                        self.logger.info(f"Test '{test_result['name']}' passed in {test_result['execution_time']} seconds")
                    else:
                        self.logger.error(f"Test '{test_result['name']}' failed: {test_result['error']}")
                    results[test_result['name']] = test_result

            return results

        except Exception as e:
            self.logger.error(f"Failed to run tests for module {module_name}: {e}")
            return {}

    def execute_test(self, test_func, api_client):
        try:
            # Execute the test function
            test_result = {'name': test_func.__name__, 'success': True, 'execution_time': 0}
            start_time = time.time()
            test_func(api_client)
            end_time = time.time()
            test_result['execution_time'] = end_time - start_time

        except Exception as e:
            # Handle API failures and other exceptions
            test_result = {'name': test_func.__name__, 'success': False, 'error': str(e)}
            if isinstance(e, requests.exceptions.RequestException):
                self.logger.warning(f"API request failed: {e}")

        return test_result

# Example usage:
test_framework = TestFramework()
results = test_framework.run_tests('my_module', [my_test_func1, my_test_func2], api_client_instance)
print(results)']

