import org.springframework.cloud.gateway.route.RouteLocator;
import org.springframework.cloud.netflix.ribbon.RibbonClient;
import org.springframework.cloud.sleuth.instrument.Trace;
import org.springframework.context.annotation.Bean;
import org.springframework.web.reactive.function.server.ServerResponse;

@SpringBootApplication
public class GatewayApplication {

    public static void main(String[] args) {
        SpringApplication.run(GatewayApplication.class, args);
    }

    @Bean
    public RouteLocator routeLocator() {
        return RouteLocator.builder()
                .route(r -> r.path("/api/**")
                        .uri("http://localhost:8080") // Service A
                        . predicates(p -> p.pathEquals("/api/serviceA"))
                        .filters(f -> f.addRequestHeader("X-API-KEY", "SERVICE-A-KEY")))

                .route(r -> r.path("/api2/**")
                        .uri("http://localhost:8181") // Service B
                        .predicates(p -> p.pathEquals("/api2/serviceB"))
                        .filters(f -> f.addRequestHeader("X-API-KEY", "SERVICE-B-KEY")))
                .build();
    }

    @Bean
    public RibbonClient ribbonClient() {
        return new RibbonClient();
    }

    @Bean
    public Trace trace() {
        return new Trace();
    }

    public ServerResponse handleRequest(ServerRequest request) {
        // Handle request logic here
        return ServerResponse.ok().bodyValue("Hello, World!");
    }
}
