public:
    AvatarLoadingSystem() : cache_(new std::unordered_map<std::string, std::vector<char>>()), resolver_(new ImageResolver()) {}

    void loadAvatar(const std::string& userId) {
        // Get the avatar URL
        const auto& url = getAvatarUrl(userId);

        // Check if the avatar is already cached
        if (cache_->find(url) != cache_->end()) {
            // Return the cached avatar
            return;
        }

        // Load the avatar asynchronously using an external image hosting service
        resolver_->loadAvatarAsync(userId, [this, userId](const std::vector<char>& data) {
            // Store the loaded avatar in the cache
            cache_->insert({url, data});

            // Notify any waiting threads that the avatar is now available
            avatarAvailable_.notify_all();
        });
    }

    const std::vector<char>* getAvatar(const std::string& userId) {
        // Wait for the avatar to be loaded and cached
        std::unique_lock<std::mutex> lock(avatarMutex_);
        while (true) {
            if (cache_->find(getAvatarUrl(userId)) != cache_->end()) {
                return &(*cache_)[getAvatarUrl(userId)];
            }

            avatarAvailable_.wait(lock);
        }
    }

