#define DEVICE_EVENT_MAX_SIZE 1024

typedef struct {
    time_t timestamp;
    int event_type;
    char device_id[16];
} DeviceEvent;

typedef struct {
    DeviceEvent* events;
    size_t num_events;
    pthread_mutex_t lock;
} EventBatch;

void* handle_batch_submission(void* batch) {
    // Simulate API submission
    sleep(1);  // Wait for 1 second
    printf("Batch submitted\n");
    return NULL;
}

int create_event_batch(EventBatch** batch, size_t initial_size) {
    *batch = (EventBatch*)malloc(sizeof(EventBatch));
    (*batch)->events = (DeviceEvent*)calloc(initial_size, sizeof(DeviceEvent));
    (*batch)->num_events = 0;
    pthread_mutex_init(&((*batch)->lock), NULL);
    return 0;
}

int add_event_to_batch(EventBatch* batch, DeviceEvent event) {
    pthread_mutex_lock(&batch->lock);
    if (batch->num_events >= batch->events[batch->num_events].timestamp) {
        // Batch full
        pthread_mutex_unlock(&batch->lock);
        return -1;
    }
    memcpy(&batch->events[batch->num_events], &event, DEVICE_EVENT_MAX_SIZE);
    batch->num_events++;
    pthread_mutex_unlock(&batch->lock);
    return 0;
}

int submit_batch(EventBatch* batch) {
    pthread_mutex_lock(&batch->lock);
    if (batch->num_events > 0) {
        pthread_create(&thread, NULL, handle_batch_submission, batch);
        pthread_join(thread, NULL);
    }
    pthread_mutex_unlock(&batch->lock);
    return 0;
}

void free_event_batch(EventBatch* batch) {
    pthread_mutex_lock(&batch->lock);
    if (batch->num_events > 0) {
        // Simulate API rejection
        sleep(1);  // Wait for 1 second
        printf("Batch rejected\n");
    }
    pthread_mutex_unlock(&batch->lock);
    free(batch->events);
    free(batch);
}

int main() {
    EventBatch* batch;
    create_event_batch(&batch, 10);

    DeviceEvent event1 = {"2022-01-01 00:00:00", 0, "device1"};
    add_event_to_batch(batch, event1);
    DeviceEvent event2 = {"2022-01-02 00:00:00", 1, "device2"};
    add_event_to_batch(batch, event2);

    submit_batch(batch);
    free_event_batch(batch);

    return 0;
}
