def render_footer_scripts():
    script_objects = request.get_json()
    md5_hashes = {}
    sha256_hashes = {}

    for script in script_objects:
        file_path = script['file_path']
        with open(file_path, 'rb') as f:
            file_content = f.read()

        md5_hash = hashlib.md5(file_content).hexdigest()
        sha256_hash = hashlib.sha256(file_content).hexdigest()

        md5_hashes[script['name']] = md5_hash
        sha256_hashes[script['name']] = sha256_hash

    return {'md5_hashes': md5_hashes, 'sha256_hashes': sha256_hashes}

