**Node.js Service (DocumentMetadataService)**
```javascript
// document-metadata-service.js
const express = require('express');
const app = express();
const mongoose = require('mongoose');

app.use(express.json());

const DocumentMetadata = mongoose.model('DocumentMetadata', {
  id: Number,
  documentId: String,
  metadata: String,
});

app.get('/metadata/:documentId', async (req, res) => {
  const documentId = req.params.documentId;
  const metadata = await DocumentMetadata.findOne({ documentId });
  if (!metadata) {
    return res.status(404).send({ message: 'Document not found' });
  }
  return res.send(metadata);
});

app.post('/metadata', async (req, res) => {
  const { documentId, metadata } = req.body;
  try {
    await DocumentMetadata.create({ documentId, metadata });
    return res.status(201).send({ message: 'Metadata created successfully' });
  } catch (error) {
    return res.status(500).send({ message: 'Error creating metadata' });
  }
});

app.listen(3000, () => {
  console.log('Document Metadata Service listening on port 3000');
});
```

