class HybridCloudStorage:
    def __init__(self):
        self.aws_s3 = boto3.client('s3')
        self.google_cloud_storage = storage.Client()
        self.azure_blob_storage = BlobServiceClient()

    def upload_file(self, file_path, bucket_name):
        # Upload file to AWS S3
        s3_bucket = self.aws_s3.Bucket(bucket_name)
        s3_bucket.upload_file(file_path)

        # Upload file to Google Cloud Storage
        gcs_bucket = self.google_cloud_storage.bucket(bucket_name)
        gcs_bucket.upload_file(file_path, 'path/to/file')

        # Upload file to Azure Blob Storage
        blob_service_client = self.azure_blob_storage.get_blob_client(bucket_name)
        blob_service_client.upload_blob('file.txt', file_path)

    def get_file(self, bucket_name, file_name):
        # Retrieve file from AWS S3
        s3_bucket = self.aws_s3.Bucket(bucket_name)
        file_data = s3_bucket.Object(file_name).get()['Body'].read()

        # Retrieve file from Google Cloud Storage
        gcs_bucket = self.google_cloud_storage.bucket(bucket_name)
        file_data = gcs_bucket.blob(file_name).download_as_string()

        # Retrieve file from Azure Blob Storage
        blob_service_client = self.azure_blob_storage.get_blob_client(bucket_name)
        file_data = blob_service_client.download_blob(file_name).readinto(file_data)

    def hash_file(self, bucket_name, file_name):
        # Calculate MD5 and SHA-256 hashes for the file
        s3_bucket = self.aws_s3.Bucket(bucket_name)
        file_data = s3_bucket.Object(file_name).get()['Body'].read()
        md5_hash = hashlib.md5(file_data).hexdigest()
        sha256_hash = hashlib.sha256(file_data).hexdigest()

        # Upload hashes to the same bucket
        s3_bucket.put_object(Key='hashes', Body=md5_hash.encode() + b'\n' + sha256_hash.encode())
