// file-reader.js
import { createLogger } from './logger';
import * as fs from 'fs';
import * as path from 'path';
import { performance } from 'perf_hooks';

const logger = createLogger('file-reader');
const cache = {};

async function readFileSync(filePath) {
  try {
    const contents = await new Promise((resolve, reject) => {
      fs.readFile(filePath, (err, data) => {
        if (err) reject(err);
        else resolve(data);
      });
    });
    return Buffer.from(contents);
  } catch (err) {
    logger.error(`Error reading file: ${err.message}`);
    throw err;
  }
}

async function readAsyncFile(filePath) {
  try {
    const contents = await new Promise((resolve, reject) => {
      fs.readFile(filePath, { encoding: 'utf8' }, (err, data) => {
        if (err) reject(err);
        else resolve(data);
      });
    });
    return contents;
  } catch (err) {
    logger.error(`Error reading file: ${err.message}`);
    throw err;
  }
}

async function readStreamFile(filePath) {
  try {
    const stream = fs.createReadStream(filePath);
    let contents = '';
    await new Promise((resolve, reject) => {
      stream.on('data', (chunk) => {
        contents += chunk.toString();
      });
      stream.on('error', (err) => {
        reject(err);
      });
      stream.on('end', () => {
        resolve(contents);
      });
    });
    return Buffer.from(contents, 'utf8');
  } catch (err) {
    logger.error(`Error reading file: ${err.message}`);
    throw err;
  }
}

async function cacheFile(filePath, contents) {
  if (!cache[filePath]) {
    cache[filePath] = contents;
  }
  return cache[filePath];
}

async function getCachedFile(filePath) {
  return await cacheFile(filePath, null);
}

function getFileAccessCount(filePath) {
  const accessCount = {};
  try {
    const stat = await fs.stat(filePath);
    if (stat.isFile()) {
      accessCount[filePath] = 0;
    }
  } catch (err) {
    logger.error(`Error getting file access count: ${err.message}`);
  }
  return accessCount;
}

