            self.s3 = boto3.client("s3")
        elif provider == "GCS":
            self.storage_client = gcs.Client()
        elif provider == "Azure":
            self.blob_service_client = BlobServiceClient.from_connection_string(
                os.environ["AZURE_STORAGE_CONNECTION_STRING"]
            )
        else:
            raise ValueError(f"Unsupported storage provider: {provider}")

    def upload_file(self, file_path: str) -> Dict[str, Any]:
        if self.s3:
            return {"provider": "AWS", "file_key": self.s3.upload_file(file_path).get("Key")}
        elif self.storage_client:
            bucket = self.storage_client.bucket(os.environ["GCS_BUCKET_NAME"])
            blob = bucket.blob(os.path.basename(file_path))
            blob.upload_from_string(open(file_path, "rb").read())
            return {"provider": "GCS", "file_key": blob.public_url}
        elif self.blob_service_client:
            container_client = self.blob_service_client.get_container_client(
                os.environ["AZURE_STORAGE_CONTAINER_NAME"]
            )
            blob_client = container_client.get_blob_client(os.path.basename(file_path))
            with open(file_path, "rb") as file:
                blob_client.upload_blob(file.read(), overwrite=True)
            return {"provider": "Azure", "file_key": blob_client.url}

class HashAdapter:
    def __init__(self):
        self.md5 = hashlib.md5()
        self.sha256 = hashlib.sha256()

    def calculate_hash(self, file_path: str) -> Dict[str, Any]:
        with open(file_path, "rb") as file:
            while chunk := file.read(4096):
                self.md5.update(chunk)
                self.sha256.update(chunk)
        return {
            "md5": self.md5.hexdigest(),
            "sha256": self.sha256.hexdigest()
        }

class RateLimiter:
    def __init__(self, ip_address: str, user_account: str):
        self.ip_address = ip_address
        self.user_account = user_account

    def rate_limit(self) -> None:
        if self.ip_address in os.environ["RATE_LIMITED_IPS"]:
            time.sleep(int(os.environ["RATE_LIMIT_SECONDS"]))
        elif self.user_account in os.environ["RATE_LIMITED_ACCOUNTS"]:
            time.sleep(int(os.environ["RATE_LIMIT_SECONDS"]))

class DistributedLogger:
    def __init__(self):
        self.loggers = []

    def log(self, message: str) -> None:
        for logger in self.loggers:
            logger.info(message)

