class StorageAdapter:
    def __init__(self, provider):
        self.provider = provider

    def upload_file(self, file_path):
        if self.provider == "aws":
            s3 = boto3.client("s3")
            s3.put_object(Body=open(file_path, "rb"), Bucket="my-bucket", Key="file.txt")
        elif self.provider == "gcp":
            storage_client = storage.Client()
            bucket = storage_client.bucket("my-bucket")
            blob = bucket.blob("file.txt")
            blob.upload_from_string(open(file_path, "r").read())
        elif self.provider == "azure":
            blob_service_client = BlobServiceClient("https://my-account.blob.core.windows.net/")
            blob_client = blob_service_client.get_blob_client("my-container", "file.txt")
            with open(file_path, "rb") as file:
                blob_client.upload_blob(file.read())

class HashAdapter:
    def __init__(self, algorithm):
        self.algorithm = algorithm

    def hash_file(self, file_path):
        if self.algorithm == "md5":
            return hashlib.md5(open(file_path, "rb").read()).hexdigest()
        elif self.algorithm == "sha-256":
            return hashlib.sha256(open(file_path, "rb").read()).hexdigest()

class DnsResolver:
    def __init__(self):
        self.resolver = dns.resolver.Resolver()

