// Define the structure to store NFAPI_CRC_INDICATION_PDU_T information
typedef struct {
    int RX_UE_INFORMATION_TAG;
    char RNTI[16];
    int CRC_INDICATION_REL8_TAG;
    int CRCFLAG;
} nfapi_crc_indication_pdu_t;

// Define the hash table structure to manage dynamic storage and processing
typedef struct {
    int size;
    int capacity;
    void **table;
} hash_table_t;

// Initialize a new hash table with given capacity
hash_table_t* hash_table_init(int capacity) {
    hash_table_t* ht = malloc(sizeof(hash_table_t));
    ht->size = 0;
    ht->capacity = capacity;
    ht->table = calloc(capacity, sizeof(void *));
    return ht;
}

// Free the resources allocated for a hash table
void hash_table_free(hash_table_t* ht) {
    free(ht->table);
    free(ht);
}

// Insert a new entry into the hash table with given key and value
void hash_table_insert(hash_table_t* ht, int key, void* value) {
    // Calculate the index for the given key using hash function
    int index = key % ht->capacity;

    // Check if the slot is empty or has a different key
    if (ht->table[index] == NULL || ht->table[index]->RX_UE_INFORMATION_TAG != key) {
        // Update the size and table entry
        ht->size++;
        ht->table[index] = value;
    }
}

// Retrieve an existing entry from the hash table by its key
void* hash_table_lookup(hash_table_t* ht, int key) {
    int index = key % ht->capacity;

    // Check if the slot has a matching key
    if (ht->table[index] != NULL && ht->table[index]->RX_UE_INFORMATION_TAG == key) {
        return ht->table[index];
    }

    // Handle hash collision or missing entry
    return NULL;
}

// Prune entries older than 5 minutes from the hash table
void hash_table_prune(hash_table_t* ht, time_t prune_time) {
    for (int i = 0; i < ht->capacity; i++) {
        void* value = ht->table[i];

        // Check if the entry is older than the prune time
        if (value != NULL && value->RX_UE_INFORMATION_TAG > prune_time) {
            // Remove the stale entry from the hash table
            free(value);
            ht->table[i] = NULL;
            ht->size--;
        }
    }
}

