    void add_entry(const NFAPI_CRC_INDICATION_PDU_T& entry) {
        std::unique_lock<std::mutex> lock(mtx);
        entries.push_back(entry);

        // prune old entries
        if (entries.size() > 1000000) {
            entries.pop_front();
        }

        cv.notify_one();
    }

    void remove_old_entries(int age_in_minutes) {
        std::unique_lock<std::mutex> lock(mtx);
        while (!entries.empty()) {
            NFAPI_CRC_INDICATION_PDU_T entry = entries.front();
            if (entry.CRCFLAG && (std::chrono::system_clock::now() - entry.RX_UE_INFORMATION_TAG.creation_time()).count() / 60 > age_in_minutes) {
                entries.pop_front();
            } else {
                break;
            }
        }
    }

