    new_instance->CRC_INDICATION_REL8_TAG = 0; // initialize with default value
    new_instance->CRCFLAG = 0; // initialize with default value

    pool->pool = realloc(pool->pool, (pool->num_instances + 1) * sizeof(NFAPI_CRC_INDICATION_PDU_T*));
    pool->pool[pool->num_instances] = new_instance;
