class DataPacket {
public:
    // Your implementation
};

class CellularSession {
public:
    std::string sessionId;
    DataPacket* dataPacket;
    CellularSession* previousSession;
    CellularSession* nextSession;

    CellularSession(const std::string& id, DataPacket* packet)
        : sessionId(id), dataPacket(packet) {}
};

class SessionManager {
public:
    class SessionIterator {
    public:
        explicit SessionIterator(SessionManager* manager, bool reverse = false)
            : manager_(manager), current_(nullptr), reverse_(reverse) {}

        CellularSession* operator->() const { return current_; }
        CellularSession& operator*() const { return *current_; }

        void next() {
            if (reverse_) {
                current_ = current_->nextSession;
            } else {
                current_ = current_->previousSession;
            }
        }

        bool valid() const { return current_ != nullptr; }

    private:
        SessionManager* manager_;
        CellularSession* current_;
        bool reverse_;
    };

    void addSession(CellularSession* session) {
        std::unique_lock<std::mutex> lock(mutex_);
        sessions_.push_back(session);
        session->previousSession = &sessions_[sessions_.size() - 1];
        if (!reverse_) {
            session->nextSession = nullptr;
        } else {
            session->nextSession = &sessions_[0];
        }
    }

    void removeSession(CellularSession* session) {
        std::unique_lock<std::mutex> lock(mutex_);
        auto it = sessions_.begin();
        for (; it != sessions_.end(); ++it) {
            if (it->get() == session) {
                break;
            }
        }
        if (it != sessions_.end()) {
            // Update previous and next pointers
            if (it->previousSession_ != nullptr) {
                it->previousSession_->nextSession_ = it->nextSession_;
            } else {
                sessions_[0]->nextSession_ = session->nextSession_;
            }
            if (it->nextSession_ != nullptr) {
                it->nextSession_->previousSession_ = it->previousSession_;
            } else {
                sessions_.back()->previousSession_ = &sessions_[0];
            }
            // Remove from the list
            sessions_.erase(it);
        }
    }

    SessionIterator getForwardIterator() const {
        return SessionIterator(this);
    }

    SessionIterator getReverseIterator() const {
        return SessionIterator(this, true);
    }

private:
    std::mutex mutex_;
    std::vector<CellularSession*> sessions_;
};

int main() {
