                head, tail = self._cell_sessions
                new_session.prev_session = None
                new_session.next_session = head
                head.prev_session = new_session
                self._cell_sessions.append(tail)
            else:
                new_session.prev_session = self._cell_sessions[-1]
                self._cell_sessions[-1].next_session = new_session
                self._cell_sessions.append(new_session)

    def delete_cell_session(self, session_id):
        with self._lock:
            for session in self._cell_sessions:
