```cpp
#include <thread>
#include <mutex>
#include <condition_variable>
#include <queue>
#include <functional>
#include <map>

class DynamicCharacterActionExecutor {
public:
    void execute(const std::function<void()> &action) {
        std::unique_lock<std::mutex> lock(action_mutex_);
        action_queue_.push(action);
        lock.unlock();
        action_condition_.notify_one();
    }

private:
    std::mutex action_mutex_;
    std::condition_variable action_condition_;
    std::queue<std::function<void()>> action_queue_;

    void runActions() {
        while (true) {
            std::unique_lock<std::mutex> lock(action_mutex_);
            action_condition_.wait(lock, [this] { return !action_queue_.empty(); });
            auto action = action_queue_.front();
            action_queue_.pop();
            lock.unlock();
            action();
        }
    }

    static void startThread(DynamicCharacterActionExecutor *executor) {
        std::thread([executor]() { executor->runActions(); }).detach();
    }

    friend class DynamicCharacterActionExecutorFactory;
};

class DynamicCharacterActionExecutorFactory {
public:
    static DynamicCharacterActionExecutor &create() {
        static DynamicCharacterActionExecutor executor;
        return executor;
    }
};

int main() {
    auto &executor = DynamicCharacterActionExecutorFactory::create();

    // Example usage
    std::function<void()> action1 = [] { std::cout << "Action 1 executed.\n"; };
    std::function<void()> action2 = [] { std::cout << "Action 2 executed.\n"; };

    executor.execute(action1);
    executor.execute(action2);

    return 0;
}
```

