        private readonly List<IRealTimeAnalyzer> _analyzer = new List<IRealTimeAnalyzer>();

        public void AddTransformer(IDataTransformer transformer)
        {
            _transformers.Add(transformer);
        }

        public void AddAnalyzer(IRealTimeAnalyzer analyzer)
        {
            _analyzer.Add(analyzer);
        }

        public async Task ProcessAsync(string inputData)
        {
            var data = JsonConvert.DeserializeObject(inputData);

            foreach (var transformer in _transformers)
            {
                data = await transformer.TransformAsync(data);
            }

            foreach (var analyzer in _analyzer)
            {
                await analyzer.AnalyzeAsync(data);
            }
        }
