using System;
using System.IO;
using System.Security.Cryptography;
using System.Threading.Tasks;
using Microsoft.Extensions.Caching.Memory;
using Microsoft.Extensions.Logging;

public class HashService
{
    private readonly IMemoryCache _memoryCache;
    private readonly ILogger<HashService> _logger;
    private readonly IFileStorageApi _fileStorageApi;
    private readonly IRateLimiter _rateLimiter;

    public HashService(IMemoryCache memoryCache, ILogger<HashService> logger, IFileStorageApi fileStorageApi, IRateLimiter rateLimiter)
    {
        _memoryCache = memoryCache;
        _logger = logger;
        _fileStorageApi = fileStorageApi;
        _rateLimiter = rateLimiter;
    }

    public async Task<string> ComputeHashAsync(string input, HashAlgorithm hashAlgorithm)
    {
        if (string.IsNullOrEmpty(input))
        {
            throw new ArgumentException("Input cannot be null or empty", nameof(input));
        }

        var cacheKey = $"hash-{input}-{hashAlgorithm.ToString()}";
        string cachedHash;
        if (_memoryCache.TryGetValue(cacheKey, out cachedHash))
        {
            _logger.LogInformation($"Retrieved hash from cache: {cachedHash}");
            return cachedHash;
        }

        try
        {
            switch (hashAlgorithm)
            {
                case HashAlgorithm.MD5:
                    var md5 = MD5(input);
                    break;
                case HashAlgorithm.SHA256:
                    var sha256 = SHA256(input);
                    break;
                default:
                    throw new ArgumentException("Invalid hash algorithm", nameof(hashAlgorithm));
            }

            if (_rateLimiter.AllowRequest())
            {
                _memoryCache.Set(cacheKey, md5, TimeSpan.FromDays(1));
                return md5;
            }
            else
            {
                await Task.Delay(_rateLimiter.GetRetryInterval());
                return ComputeHashAsync(input, hashAlgorithm);
            }
        }
        catch (Exception ex)
        {
            _logger.LogError(ex, "Error computing hash");
            throw;
        }
    }

    public async Task<string> ComputeFileHashAsync(string filePath, HashAlgorithm hashAlgorithm)
    {
        if (string.IsNullOrEmpty(filePath))
        {
            throw new ArgumentException("Input cannot be null or empty", nameof(filePath));
        }

        var fileStream = _fileStorageApi.GetFileStream(filePath);
        using var md5 = MD5.Create();
        using var sha256 = SHA256.Create();

        try
        {
            using var reader = new FileStreamReader(fileStream);
            byte[] fileBytes;
            if (reader.TryReadBuffer(1024, out fileBytes))
            {
                return ComputeHashAsync(new MemoryStream(fileBytes), hashAlgorithm);
            }
            else
            {
                _logger.LogError("Failed to read file");
                throw new IOException("Failed to read file");
            }
        }
        catch (Exception ex)
        {
            _logger.LogError(ex, "Error computing file hash");
            throw;
        }
    }

    private string MD5(string input)
    {
        using var md5 = MD5.Create();
        var bytes = Encoding.UTF8.GetBytes(input);
        return BitConverter.ToString(md5.ComputeHash(bytes)).Replace("-", "").ToLower();
    }

    private string SHA256(string input)
    {
        using var sha256 = SHA256.Create();
        var bytes = Encoding.UTF8.GetBytes(input);
        return BitConverter.ToString(sha256.ComputeHash(bytes)).Replace("-", "").ToLower();
    }
}

public enum HashAlgorithm
{
    MD5,
    SHA256
}
```

