// Upload handler function
async function handleUpload(file) {
  try {
    // Send file to external API for uploading
    const response = await axios.post(
      'https://api.example.com/upload',
      { file },
      {
        // Set the API rate limit (e.g., 5 requests per second)
        maxContentLength: 50000000,
        timeout: 1000, // 1 sec
      }
    );

    if (!response.ok) {
      // Handle failed upload (retry up to 5 times with exponential backoff)
      const maxAttempts = 5;
      let attempts = 0;
      let delay = 500; // Initial retry delay (500 ms)

      while (attempts < maxAttempts) {
        try {
          await axios.post(
            'https://api.example.com/upload',
            { file },
            {
              timeout: delay,
            }
          );
          break;
        } catch (error) {
          attempts++;
          if (attempts < maxAttempts) {
            // Exponential backoff
            delay *= 2;
            await new Promise((resolve) => setTimeout(() => resolve(), delay));
          }
        }
      }

      // Log detailed metrics for each attempt
      console.log({
        file: file.name,
        attempts: attempts,
        success: response.ok,
        size: file.size,
        duration: (new Date().getTime() - file.timestamp),
      });
    } else {
      // Successful upload, log the metrics
      console.log({
        file: file.name,
        success: true,
        size: file.size,
        duration: (new Date().getTime() - file.timestamp),
      });
    }
  } catch (error) {
    // Handle errors and exceptions
    console.error(error);
  }
}

// Express app routes
app.get('/upload', async (req, res) => {
  // Handle upload request from the client
  const file = req.file;
  await handleUpload(file);
  res.json({ message: 'File uploaded successfully' });
});

app.listen(port, () => {
  console.log(`Upload service listening on port ${port}`);
});
