const { createHSMConnectionPool } = require('./hsm-pool');
const { createExternalAPIClient } = require('./api-client');
const { createEncryptionService } = require('./encryption');
const { createCachingService } = require('./caching');

class ModularSecureConfigService {
  constructor({ hsm, api, encryptionKeys }) {
    this.hsmPool = createHSMConnectionPool(hsm);
    this.apiClient = createExternalAPIClient(api, this.hsmPool);
    this.encryptionService = createEncryptionService(encryptionKeys, this.hsmPool);
    this.cachingService = createCachingService(this.apiClient, this.encryptionService);

    // Initialize connection pool and cache
    this.hsmPool.init();
    this.cachingService.init();

    // Define retry strategy with exponential backoff for transient failures
    this.retryStrategy = {
      retries: 5,
      delay: 1000, // initial delay in milliseconds
      maxDelay: 30000, // maximum delay in milliseconds
    };

    // Set up logging and monitoring
    const logger = require('pino').child({ pid: process.pid });
    this.logger = logger;
  }

  async handleRequest(req) {
    try {
      // Validate request and retrieve necessary data
      const { key, value } = req;

      // Check if cache is valid for the requested key
      const cachedValue = await this.cachingService.getValue(key);
      if (cachedValue) {
        return cachedValue;
      }

      // Fetch encryption keys from external API if not already cached
      if (!this.apiClient.isKeyCached(key)) {
        await this.apiClient.fetchKeys();
      }

      // Encrypt and decrypt data using HSM
      const encryptedData = await this.encryptionService.encrypt(value, key);
      return encryptedData;
    } catch (error) {
      // Handle errors and retries
      if (this.retryStrategy.retries > 0) {
        setTimeout(() => {
          this.handleRequest(req).catch(error => {
            // Log error and continue retrying
            this.logger.error({ message: 'Error handling request', error });
          });
        }, this.retryStrategy.delay);
      } else {
        // Log final error and notify stakeholders
        this.logger.error({ message: 'Failed to handle request', error });
      }
    }
  }

  async start() {
    try {
      await this.hsmPool.start();
      await this.apiClient.start();
      await this.encryptionService.start();
      await this.cachingService.start();

      // Monitor and log performance metrics
      setInterval(() => {
        const metrics = {
          cacheHitRate: this.cachingService.getCacheHitRate(),
          connectionPoolSize: this.hsmPool.getConnectionPoolSize(),
          encryptionKeysFetched: this.apiClient.getEncryptionKeysFetchedCount(),
        };
        this.logger.info({ message: 'Service metrics', metrics });
      }, 30000); // every 30 seconds
    } catch (error) {
      // Log startup errors and notify stakeholders
      this.logger.error({ message: 'Error starting service', error });
    }
  }

  async stop() {
    try {
      await this.hsmPool.stop();
      await this.apiClient.stop();
      await this.encryptionService.stop();
      await this.cachingService.stop();

      // Log shutdown and notify stakeholders
      this.logger.info({ message: 'Service stopped' });
    } catch (error) {
      // Log shutdown errors and notify stakeholders
      this.logger.error({ message: 'Error stopping service', error });
    }
  }
}

// Export the modular secure config service
module.exports = ModularSecureConfigService;
