package com.example.fileprocessing;

import java.io.InputStream;
import java.nio.ByteBuffer;
import java.security.MessageDigest;
import java.util.concurrent.ExecutorService;
import java.util.concurrent.Executors;
import java.util.concurrent.LinkedBlockingQueue;

import org.apache.commons.io.IOUtils;
import org.apache.hadoop.hbase.client.HBaseClient;
import org.apache.hadoop.hbase.util.Bytes;

public class FileProcessingService {
    public static void processFile(InputStream fileInputStream) throws Exception {
        ExecutorService executor = Executors.newFixedThreadPool(5);

        LinkedBlockingQueue<ByteBuffer> buffers = new LinkedBlockingQueue<>();

        // Handle large files efficiently using a streaming approach
        while (fileInputStream.available() > 0) {
            byte[] buffer = new byte[1024];
            int bytesRead = fileInputStream.read(buffer, 0, buffer.length);
            ByteBuffer wrappedBuffer = ByteBuffer.wrap(buffer, 0, bytesRead);
            buffers.put(wrappedBuffer);
        }

        // Calculate and return MD5 and SHA-256 hashes
        MessageDigest md5 = MessageDigest.getInstance("MD5");
        MessageDigest sha256 = MessageDigest.getInstance("SHA-256");

        while (!buffers.isEmpty()) {
            ByteBuffer buffer = buffers.take();
            md5.update(buffer.array(), 0, buffer.capacity());
            sha256.update(buffer.array(), 0, buffer.capacity());
        }

        // Return MD5 and SHA-256 hashes
        byte[] md5HashBytes = md5.digest();
        byte[] sha256HashBytes = sha256.digest();

        return new String(Base64.getEncoder().encode(md5HashBytes)) + "," + new String(Base64.getEncoder().encode(sha256HashBytes));
    }
}

