    private final ConcurrentHashMap<String, StreamingSubscription> subscriptions;
    private final ExecutorService executor;
    private final DistributedCache cache;
    private final ShardManager shardManager;

    public SubscriptionManager() {
        this.subscriptions = new ConcurrentHashMap<>();
        this.executor = Executors.newCachedThreadPool();
        this.cache = new DistributedCache();
        this.shardManager = new ShardManager();
    }

    public void subscribe(String subscriptionId, DataStream dataStream) {
        StreamingSubscription subscription = new StreamingSubscription(subscriptionId, dataStream);
        subscriptions.putIfAbsent(subscriptionId, subscription);

        // Handle network errors and transient issues with the external message broker service
        while (!sendMessageToBroker(subscription)) {
            // Exponential backoff strategy for retrying failed operations
            try { Thread.sleep(100); } catch (InterruptedException e) { }
        }

        // Store the subscription in the distributed cache
        cache.put(subscriptionId, subscription);

        // Shard the subscription based on geographical location or subscription attributes
        shardManager.addSubscription(subscription);
    }

    public void unsubscribe(String subscriptionId) {
        StreamingSubscription subscription = subscriptions.remove(subscriptionId);

        if (subscription == null) return;

        // Handle network errors and transient issues with the external message broker service
        while (!sendMessageToBroker(subscription)) {
            try { Thread.sleep(100); } catch (InterruptedException e) { }
        }

        // Evict the subscription from the distributed cache
        cache.invalidate(subscriptionId);

        // Remove the subscription from its shard
        shardManager.removeSubscription(subscription);
    }

