        List<StreamingSubscription> subscriptions = new ArrayList<>();

        // Iterate over the subscriptions in the specified direction (forward or reverse)
        for (Map.Entry<String, StreamingSubscription> entry : subscriptions.entrySet()) {
            if (direction == Direction.FORWARD && entry.getKey().compareTo(subscriptionId) > 0) {
                subscriptions.add(entry.getValue());
            } else if (direction == Direction.REVERSE && entry.getKey().compareTo(subscriptionId) < 0) {
                subscriptions.add(entry.getValue());
            }
