public class CellularSessionManager {

    private final ReentrantLock lock = new ReentrantLock();
    private Map<Long, CellularSession> sessions = new HashMap<>();
    private List<CellularSession> sessionList = new ArrayList<>();

    public void addSession(CellularSession session) {
        lock.lock();
        try {
            sessions.put(session.getSessionID(), session);
            sessionList.add(session);
        } finally {
            lock.unlock();
        }
    }

    public void removeSession(long sessionID) {
        lock.lock();
        try {
            sessions.remove(sessionID);
            sessionList.removeIf(s -> s.getSessionID() == sessionID);
        } finally {
            lock.unlock();
        }
    }

    public CellularSession getSession(long sessionID) {
        lock.lock();
        try {
            return sessions.get(sessionID);
        } finally {
            lock.unlock();
        }
    }

    // Other operations: insert, traverse, etc.

}

