    int capacity;
    NFAPI_CRC_INDICATION_PDU_T* pdus;
    pthread_mutex_t mutex;
    pthread_cond_t cond;
} PDU_List;

// Function to create a new PDU list
PDU_List* pdu_list_create(int initial_capacity) {
    PDU_List* list = (PDU_List*) malloc(sizeof(PDU_List));
    list->size = 0;
    list->capacity = initial_capacity;
    list->pdus = (NFAPI_CRC_INDICATION_PDU_T*) 
                malloc(initial_capacity * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    pthread_mutex_init(&list->mutex, NULL);
    pthread_cond_init(&list->cond, NULL);
    return list;
}

// Function to add a PDU to the list
void pdu_list_add(PDU_List* list, NFAPI_CRC_INDICATION_PDU_T pdu) {
    pthread_mutex_lock(&list->mutex);
    if (list->size == list->capacity) {
        // Reallocate memory and double capacity
        list->capacity *= 2;
        list->pdus = (NFAPI_CRC_INDICATION_PDU_T*) 
                    realloc(list->pdus, list->capacity * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    }
    list->pdus[list->size] = pdu;
    list->size++;
    pthread_mutex_unlock(&list->mutex);
}

// Function to remove a PDU from the list
void pdu_list_remove(PDU_List* list, int rnti) {
    pthread_mutex_lock(&list->mutex);
    for (int i = 0; i < list->size; i++) {
        if (list->pdus[i].rnti == rnti) {
            // Shift all PDUs after the removed one to fill the gap
            memmove(&list->pdus[i], &list->pdus[i + 1], 
                    (list->size - i - 1) * sizeof(NFAPI_CRC_INDICATION_PDU_T));
            list->size--;
            break;
        }
    }
    pthread_mutex_unlock(&list->mutex);
}

// Function to find a PDU by RNTI
NFAPI_CRC_INDICATION_PDU_T* pdu_list_find(PDU_List* list, int rnti) {
    pthread_mutex_lock(&list->mutex);
    for (int i = 0; i < list->size; i++) {
        if (list->pdus[i].rnti == rnti) {
            pthread_mutex_unlock(&list->mutex);
            return &list->pdus[i];
        }
    }
    pthread_mutex_unlock(&list->mutex);
    return NULL;
}

// Function to free the PDU list
void pdu_list_free(PDU_List* list) {
    free(list->pdus);
    pthread_cond_destroy(&list->cond);
    pthread_mutex_destroy(&list->mutex);
    free(list);
}
