#include <atomic>
#include <mutex>
#include <condition_variable>
#include <vector>
#include <thread>

class PduManager {
public:
    PduManager(size_t maxPdus, size_t concurrency) : maxPdus_(maxPdus), concurrency_(concurrency),
        pduList_(), pdusGenerated_(0), lock_() {}

    void generateAndManagePdus();

private:
    std::atomic<size_t> maxPdus_;
    size_t concurrency_;
    std::vector<NFAPI_CRC_INDICATION_PDU_T> pduList_;
    std::atomic<size_t> pdusGenerated_;
    std::mutex lock_;
    std::condition_variable cv_;
};

void PduManager::generateAndManagePdus() {
    while (true) {
        std::unique_lock<std::mutex> lock(lock_);
        cv_.wait([this] { return pdusGenerated_ < maxPdus_; });

        for (size_t i = 0; i < concurrency_; ++i) {
            // Create a new PDU
            NFAPI_CRC_INDICATION_PDU_T pdu;
            // ...

            if (!pduList_.push_back(pdu)) {
                break;
            }

            ++pdusGenerated_;
        }

        lock.unlock();
    }
}
