bool nfa_pi_crc_indication_pdu_list_is_full(NFAPI_CRC_INDICATION_PDU_LIST_T *list) {
    return list->size >= list->capacity;
}

NFAPI_CRC_INDICATION_PDU_T *nfa_pi_crc_indication_pdu_list_append(NFAPI_CRC_INDICATION_PDU_LIST_T *list, NFAPI_CRC_INDICATION_PDU_T *pdu) {
    pthread_mutex_lock(&list->lock);
    if (nfa_pi_crc_indication_pdu_list_is_full(list)) {
        // Handle full list condition
        pthread_mutex_unlock(&list->lock);
        return NULL;
    }
    // Add pdu to the end of the list
    list->pdus[list->size] = *pdu;
    list->size++;
    pthread_mutex_unlock(&list->lock);
    return &list->pdus[list->size - 1];
}

bool nfa_pi_crc_indication_pdu_list_remove_last_pdu(NFAPI_CRC_INDICATION_PDU_LIST_T *list) {
    pthread_mutex_lock(&list->lock);
    if (list->size > 0) {
        // Remove the last pdu from the list
        list->size--;
        pthread_mutex_unlock(&list->lock);
        return true;
    }
    pthread_mutex_unlock(&list->lock);
    return false;
}

