class LogEventRecord {
public:
    enum class Severity { DEBUG, INFO, WARN, ERROR, CRITICAL };
    LogEventRecord(uint64_t timestamp, Severity severity, std::string message, std::map<std::string, std::string> metadata)
        : timestamp(timestamp), severity(severity), message(message), metadata(metadata) {}

    uint64_t getTimestamp() const { return timestamp; }
    Severity getSeverity() const { return severity; }
    std::string getMessage() const { return message; }
    std::map<std::string, std::string> getMetadata() const { return metadata; }

private:
    uint64_t timestamp;
    Severity severity;
    std::string message;
    std::map<std::string, std::string> metadata;
};

class LogLibrary {
public:
    LogLibrary(int maxRecordsPerSecond) : maxRecordsPerSecond(maxRecordsPerSecond), records(std::vector<LogEventRecord>()) {}

    void log(LogEventRecord record) {
        if (records.size() >= maxRecordsPerSecond) {
            std::this_thread::sleep_for(std::chrono::milliseconds(1));
        }
        records.push_back(record);
    }

private:
    int maxRecordsPerSecond;
    std::vector<LogEventRecord> records;
};

int main() {
    LogLibrary logLib(1000);

    for (int i = 0; i < 1000; i++) {
        LogEventRecord record((uint64_t)std::chrono::high_resolution_clock::now().time_since_epoch().count(), LogEventRecord::Severity::INFO, "This is a log message", {"key": "value"});
        logLib.log(record);
    }

    return 0;
}
