// Structure definition for NFAPI CRC indication messages
typedef struct {
    int RX_UE_INFORMATION_TAG;
    int RNTI;
    int CRC_INDICATION_REL8_TAG;
    int CRCFLAG;
} NFAPI_CRC_INDICATION_PDU_T;

// Function to deserialize binary file and store data in a list of structures
void process_binary_file(const char* filename, int** data_list, int* data_length) {
    FILE *file = fopen(filename, "rb");
    if (file == NULL) {
        printf("Error opening file!\n");
        return;
    }

    // Initialize variables for processing
    int record_count = 0;
    NFAPI_CRC_INDICATION_PDU_T* data_list_ptr = NULL;

    // Read and process each record in the binary file
    while (1) {
        NFAPI_CRC_INDICATION_PDU_T record;
        fread(&record, sizeof(record), 1, file);

        // Check for invalid or incomplete records
        if (ferror(file) || feof(file)) {
            break;
        }

        // Handle valid record and add to data list
        data_list_ptr = realloc(data_list_ptr, (record_count + 1) * sizeof(NFAPI_CRC_INDICATION_PDU_T));
        memcpy(&data_list_ptr[record_count], &record, sizeof(record));
        record.CRCFLAG = rand() % 2; // Set CRCFLAG randomly
        record_count++;
    }

    fclose(file);

    // Update data list and length
    *data_list = data_list_ptr;
    *data_length = record_count;
}

// Function to print the deserialized data for testing purposes
void print_data(int* data_list, int data_length) {
    printf("Deserialized Data:\n");
    for (int i = 0; i < data_length; i++) {
        NFAPI_CRC_INDICATION_PDU_T record = data_list[i];
        printf("RX_UE_INFORMATION_TAG: %d, RNTI: %d, CRC_INDICATION_REL8_TAG: %d, CRCFLAG: %d\n", 
               record.RX_UE_INFORMATION_TAG, record.RNTI, record.CRC_INDICATION_REL8_TAG, record.CRCFLAG);
    }
}

int main() {
    // Initialize variables for processing
    int data_length = 0;
    int* data_list = NULL;

    // Process binary file and store data in a list of structures
    process_binary_file("data.bin", &data_list, &data_length);

    // Print the deserialized data for testing purposes
    print_data(data_list, data_length);

    // Free allocated memory
    free(data_list);

    return 0;
}
