import logging
from queue import LifoQueue
from threading import Lock, Thread
from collections import deque
from functools import wraps
from os import getpid, getcwd
from time import strftime, localtime, sleep
from heapq import heapify, heappush, heappop
from gc import get_objects

class LoggingSystem:
    def __init__(self):
        self.logger = logging.getLogger(__name__)
        self.config = {
            'logging_level': logging.INFO,
            'memory_threshold': 0.7,
            'resource_limit': 10000,
            'cache_size': 100000,
            'eviction_policy': 'LRU'
        }
        self.cache = deque(maxlen=self.config['cache_size'])
        self.memory_usage = LifoQueue()
        self.resource_usage = set()

    def log_packet(self, metadata):
        if self.config['logging_level'] <= metadata['level']:
            self.logger.info(metadata)

    def process_packet(self, packet):
        if self.is_memory_safe():
            try:
                # processing logic
                pass
            except Exception as e:
                self.handle_error(e)
        else:
            self.scale_resources()

    def is_memory_safe(self):
        return len(get_objects()) <= self.config['memory_threshold'] * 1000

    def scale_resources(self):
        while not self.is_memory_safe():
            sleep(1)
            self.memory_usage.put(getpid())
        self.logger.info('Memory usage scaled')

    def handle_error(self, e):
        self.logger.error(f'Error: {e}')
        if e.__class__.__name__ == 'PacketProcessingError':
            self.scale_resources()

    def get_memory_metrics(self):
        return {
            'max_memory_usage': max(get_objects()),
            'current_memory_usage': len(get_objects())
        }

    def get_resource_metrics(self):
        return {
            'resource_limit': self.config['resource_limit'],
            'resource_usage': len(self.resource_usage)
        }

def threaded(func):
    @wraps(func)
    def wrapper(*args, **kwargs):
        thread = Thread(target=func, args=args, kwargs=kwargs)
        thread.start()
        return thread
    return wrapper

@threaded
def process_packets(packets):
    for packet in packets:
        if not self.process_packet(packet):
            break

if __name__ == '__main__':
    logging.basicConfig(level=logging.INFO)
    system = LoggingSystem()

    # Example usage:
    metadata1 = {'level': logging.INFO, 'data': 'Packet 1'}
    metadata2 = {'level': logging.WARNING, 'data': 'Packet 2'}
    packets = [metadata1, metadata2]
    process_packets(packets)

    print('Memory Metrics:')
    print(system.get_memory_metrics())
    print('Resource Metrics:')
    print(system.get_resource_metrics())

