from flask_retry import Retry
from flask_api import status
from requests.exceptions import ConnectionError
from datetime import datetime
import logging

app = Flask(__name__)
cache = Cache(app)
circuit_breaker = CircuitBreaker(app)

@app.route('/hash', methods=['POST'])
@Retry(maxtries=3, backoff_factor=0.1)
@circuit_breaker(max_errors=5, timeout=30)
def calculate_hashes():
    file_content = request.get_json()['file']
    md5_hash = hashlib.md5(file_content.encode()).hexdigest()
    sha256_hash = hashlib.sha256(file_content.encode()).hexdigest()
    return jsonify({'md5': md5_hash, 'sha256': sha256_hash})

@app.route('/rate_limit', methods=['POST'])
@Retry(maxtries=3, backoff_factor=0.1)
@circuit_breaker(max_errors=5, timeout=30)
def apply_rate_limits():
    user_id = request.get_json()['user_id']
    rate_limit = get_rate_limit(user_id)
    if rate_limit:
        return jsonify({'message': 'Rate limit exceeded'})
    else:
        return jsonify({'message': 'Rate limit applied'})

@app.route('/script', methods=['POST'])
@Retry(maxtries=3, backoff_factor=0.1)
@circuit_breaker(max_errors=5, timeout=30)
def execute_script():
    script_content = request.get_json()['script']
    try:
        exec(script_content)
    except Exception as e:
        return jsonify({'message': str(e)})
    return jsonify({'message': 'Script executed successfully'})

if __name__ == '__main__':
    app.run(debug=True)
