import java.util.concurrent.*;

public class DistributedTaskScheduler {
    private final Map<String, ExecutorService> workerServices = new HashMap<>();
    private final Map<String, JobStorageService> jobStorages = new HashMap<>();
    private final MessagingSystem messagingSystem;
    private final HealthMonitoringAPI healthMonitor;
    private final CachingLayer cachingLayer;

    public DistributedTaskScheduler(MessagingSystem messagingSystem, HealthMonitoringAPI healthMonitor, CachingLayer cachingLayer) {
        this.messagingSystem = messagingSystem;
        this.healthMonitor = healthMonitor;
        this.cachingLayer = cachingLayer;
    }

    public void submitTask(String jobName, String taskDefinition, Map<String, Object> taskConfig) throws InterruptedException {
        ExecutorService workerService = getWorkerService(taskConfig);
        Future<?> taskFuture = workerService.submit(() -> {
            // Execute the task
            JobExecutor.executeJob(taskDefinition, taskConfig);
        });
    }

    public void submitTaskBatch(List<JobDefinition> jobs, Map<String, Object> jobConfig) throws InterruptedException {
        ExecutorService workerService = getWorkerService(jobConfig);
        List<Future<?>> tasks = new ArrayList<>();
        for (JobDefinition job : jobs) {
            Future<?> taskFuture = workerService.submit(() -> {
                // Execute the task
                JobExecutor.executeJob(job.getTaskDefinition(), job.getConfig());
            });
            tasks.add(taskFuture);
        }
    }

    public void cancelTask(String jobName, String taskDefinition) throws InterruptedException {
        ExecutorService workerService = getWorkerService(getJobConfig(taskName));
        Future<?> taskFuture = workerService.submit(() -> {
            // Cancel the task
            JobExecutor.cancelJob(taskDefinition);
        });
    }

    private ExecutorService getWorkerService(Map<String, Object> config) {
        return workerServices.computeIfAbsent(config.get("workerId"), id -> Executors.newFixedThreadPool(5));
    }

    private Map<String, Object> getJobConfig(String jobName) {
        return jobStorages.get(jobName).getJobConfiguration();
    }
}

