// Task Scheduling System
package com.example.taskscheduler;

import java.util.*;

public class TaskScheduler {
    private Map<String, List<Task>> taskRegistry = new HashMap<>();
    private Map<String, TaskWorker> workerRegistry = new HashMap<>();
    private Scheduler scheduler;
    private LoadPredictor loadPredictor;

    public TaskScheduler(Scheduler scheduler, LoadPredictor loadPredictor) {
        this.scheduler = scheduler;
        this.loadPredictor = loadPredictor;
    }

    // Register a task
    public void registerTask(String taskId, String language, byte[] code) {
        Task task = new Task(taskId, language, code);
        taskRegistry.computeIfAbsent(language, k -> new ArrayList<>()).add(task);
    }

    // Start a worker node
    public void startWorkerNode(String workerId, String region) {
        TaskWorker worker = new TaskWorker(workerId, region);
        workerRegistry.put(workerId, worker);
    }

    // Run a task on a specific worker node
    public void runTaskOnWorker(String taskId, String workerId) {
        scheduler.schedule(taskId, workerRegistry.get(workerId));
    }

    // Predict and scale based on load models
    public void scaleWorkers() {
        Map<String, Long> loadMetrics = loadPredictor.predictLoad();
        for (Map.Entry<String, Long> entry : loadMetrics.entrySet()) {
            String region = entry.getKey();
            long load = entry.getValue();
            if (load > 0.5) { // Scale up
                startWorkerNode("worker-" + region, region);
            } else if (load < 0.2) { // Scale down
                stopWorkerNode(workerRegistry.get(region));
            }
        }
    }

    // Task class
    public class Task {
        private String id;
        private String language;
        private byte[] code;

        public Task(String id, String language, byte[] code) {
            this.id = id;
            this.language = language;
            this.code = code;
        }
    }

    // Worker node class
    public class TaskWorker {
        private String id;
        private String region;

        public TaskWorker(String id, String region) {
            this.id = id;
            this.region = region;
        }
    }

    // Scheduler interface
    public interface Scheduler {
        void schedule(String taskId, TaskWorker worker);
    }

    // Load predictor interface
    public interface LoadPredictor {
        Map<String, Long> predictLoad();
    }
}
