// Function to deserialize binary files and validate CRC checksums
NFAPI_CRC_INDICATION_PDU_T* deserialize_file(const char* file_path) {
    // Open the binary file for reading
    FILE* file = fopen(file_path, "rb");
    if (file == NULL) {
        printf("Error opening file: %s\n", file_path);
