```cpp
#include <iostream>
#include <unordered_map>
#include <list>
#include <memory>
#include <mutex>
#include <condition_variable>

class LogicalChannelGroup {
public:
    LogicalChannelGroup(int srsResourceConfigInfo, int frequency, int beamDirection) 
        : srsResourceConfigInfo(srsResourceConfigInfo), frequency(frequency), beamDirection(beamDirection) {}

    int getSRSResourceConfigInfo() const { return srsResourceConfigInfo; }
    int getFrequency() const { return frequency; }
    int getBeamDirection() const { return beamDirection; }

private:
    int srsResourceConfigInfo;
    int frequency;
    int beamDirection;
};

class DynamicLogicalChannelManager {
public:
    void addLCG(const LogicalChannelGroup& lcg) {
        std::unique_lock<std::mutex> lock(mutex_);
        lcgs_.emplace_back(lcg);
        cv_.notify_one();
    }

    void removeLCG(int srsResourceConfigInfo) {
        std::unique_lock<std::mutex> lock(mutex_);
        auto it = std::find_if(lcgs_.begin(), lcgs_.end(),
            [srsResourceConfigInfo](const LogicalChannelGroup& lcg) { return lcg.getSRSResourceConfigInfo() == srsResourceConfigInfo; });
        if (it != lcgs_.end()) {
            lcg_.erase(it);
        }
    }

    void updateLCG(int srsResourceConfigInfo, const LogicalChannelGroup& newLCG) {
        std::unique_lock<std::mutex> lock(mutex_);
        auto it = std::find_if(lcg_.begin(), lcg_.end(),
            [srsResourceConfigInfo](const LogicalChannelGroup& lcg) { return lcg.getSRSResourceConfigInfo() == srsResourceConfigInfo; });
        if (it != lcg_.end()) {
            *it = newLCG;
        }
    }

    void applyChanges() {
        std::unique_lock<std::mutex> lock(mutex_);
        while (!changeBuffer_.empty()) {
            const auto& change = changeBuffer_.front();
            changeBuffer_.pop_front();

            // Apply changes to the actual LCGs
            for (auto& lcg : lcg_) {
                if (lcg.getSRSResourceConfigInfo() == change.srsResourceConfigInfo) {
                    lcg = change.newLCG;
                }
            }

            cv_.notify_one();
        }
    }

    void listenForChanges(std::function<void()> callback) {
        std::unique_lock<std::mutex> lock(mutex_);
        while (true) {
            cv_.wait(lock, [this]() { return !changeBuffer_.empty(); });
            const auto& change = changeBuffer_.front();
            changeBuffer_.pop_front();

            // Apply changes to the actual LCGs
            for (auto& lcg : lcg_) {
                if (lcg.getSRSResourceConfigInfo() == change.srsResourceConfigInfo) {
                    lcg = change.newLCG;
                }
            }

            callback();
        }
    }

private:
    std::list<LogicalChannelGroup> lcg_;
    std::mutex mutex_;
    std::condition_variable cv_;
    std::queue<Change> changeBuffer_;

    struct Change {
        int srsResourceConfigInfo;
        LogicalChannelGroup newLCG;
    };
};
```']

