# Logger setup
logging.basicConfig(filename='activity_logger.log', level=logging.INFO)
logger = logging.getLogger('activity_logger')

# Alerting system
alert_threshold = 5
alert_pattern = 'error'

@app.route('/log', methods=['POST'])
def log_entry():
    data = request.get_json()
    if data:
        logger.info(data)
        redis_client.set('last_log_time', datetime.datetime.now().strftime('%Y-%m-%d %H:%M:%S'))
        return jsonify({'status': 'OK'})
    else:
        return jsonify({'status': 'Invalid log entry'}), 400

@app.route('/alert', methods=['GET'])
def check_alert():
    last_log_time = redis_client.get('last_log_time')
    if last_log_time and (datetime.datetime.now() - datetime.datetime.strptime(last_log_time, '%Y-%m-%d %H:%M:%S')) > alert_threshold:
        return jsonify({'status': 'ALERT', 'message': f'Log entry frequency exceeded threshold ({alert_threshold} seconds) at {last_log_time}'})
    else:
        return jsonify({'status': 'OK'})

@app.route('/tokenize', methods=['POST'])
def tokenize_data():
    data = request.get_json()
    if data:
        tokenized_data = [char.encode('utf-8') for char in data['log_entry']]
        return jsonify({'tokenized_data': tokenized_data})
    else:
        return jsonify({'status': 'Invalid log entry'}), 400

@app.route('/download', methods=['GET'])
def download_log():
    start_time = request.args.get('start_time')
    end_time = request.args.get('end_time')
    if start_time and end_time:
        logs = []
        for log in logger.events:
            timestamp = log.asctime
            if start_time <= timestamp <= end_time:
                logs.append({'timestamp': timestamp, 'log_entry': log.getMessage()})
        return jsonify(logs)
    else:
        return jsonify({'status': 'Invalid time range'}), 400

@app.route('/modify', methods=['POST'])
def modify_log():
    data = request.get_json()
    if data:
        logger.info(data['log_entry'])
        return jsonify({'status': 'OK'})
    else:
        return jsonify({'status': 'Invalid log entry'}), 400

@app.route('/delete', methods=['POST'])
def delete_log():
    data = request.get_json()
    if data:
        logger.info('Log deleted')
        return jsonify({'status': 'OK'})
    else:
        return jsonify({'status': 'Invalid log entry'}), 400

if __name__ == '__main__':
