async def stream_and_persist_sensor_data(data):
    try:
        # Validate incoming data against predefined quality thresholds
        if not validate_data(data):
            raise ValueError("Invalid sensor data")

        # Handle missing or corrupted values
        if "temperature" in data and data["temperature"] is None:
            raise ValueError("Temperature value is missing")

        # Asynchronously persist clean data into a distributed time-series database
