typedef struct {
    pthread_mutex_t mutex; // Mutex for thread safety
    Message* messages; // Array of cached messages
    int message_count; // Number of cached messages
    int max_messages; // Maximum number of cached messages
} Node;

// Function to add a new message to the cache
void add_message(Node* node, int id, time_t timestamp, char status[]) {
    pthread_mutex_lock(&node->mutex);
    if (node->message_count < node->max_messages) {
        Message* new_message = &node->messages[node->message_count++];
        new_message->id = id;
        new_message->timestamp = timestamp;
        strcpy(new_message->status, status);
    } else {
        // Handle cache full situation
    }
    pthread_mutex_unlock(&node->mutex);
}

// Function to update an existing message in the cache
void update_message(Node* node, int id, time_t timestamp, char status[]) {
    pthread_mutex_lock(&node->mutex);
    for (int i = 0; i < node->message_count; i++) {
        if (node->messages[i].id == id) {
            node->messages[i].timestamp = timestamp;
            strcpy(node->messages[i].status, status);
            break;
        }
