#include <condition_variable>
#include <queue>
#include <chrono>

class RateLimitService {
public:
    RateLimitService(size_t maxConcurrentRequests)
        : maxConcurrentRequests_(maxConcurrentRequests),
          requestsPerSecond_(0),
          currentConnections_(0) {}

    void Start() {
        thread_ = std::thread([this]() { this->HandleRequests(); });
    }

    void Stop() {
        thread_.join();
    }

private:
    void HandleRequests() {
        while (true) {
            std::unique_lock<std::mutex> lock(mutex_);
            condition_.wait(lock, [this]() { return !queue_.empty(); });

            auto request = queue_.front();
            queue_.pop();

            if (currentConnections_ < maxConcurrentRequests_) {
                currentConnections_++;
                requestsPerSecond_++;

                // Handle the request
                std::cout << "Handling request: " << request << std::endl;

                // Simulate some processing time
                std::this_thread::sleep_for(std::chrono::milliseconds(50));

                currentConnections_--;
            } else {
                // Reject the request if rate limit exceeded
                std::cout << "Rate limit exceeded. Rejected request: " << request << std::endl;
            }
        }
    }

public:
    void AddRequest(const std::string& request) {
        std::unique_lock<std::mutex> lock(mutex_);
        queue_.push(request);
        condition_.notify_one();
    }

private:
    size_t maxConcurrentRequests_;
    size_t requestsPerSecond_;
    int currentConnections_;
    std::queue<std::string> queue_;
    std::thread thread_;
    std::mutex mutex_;
    std::condition_variable condition_;
};
