#include <iostream>
#include <thread>
#include <mutex>
#include <condition_variable>
#include <queue>
#include <unordered_map>

class RateLimiter {
public:
    RateLimiter(size_t maxRequestsPerSecond, size_t initialCapacity) 
        : maxRequestsPerSecond_(maxRequestsPerSecond), 
          initialCapacity_(initialCapacity),
          currentCapacity_(0),
          nextRefreshTime_(std::chrono::steady_clock::now()),
          queue_(),
          mutex_(),
          cv_()
    {}

    void enqueueRequest() {
        std::unique_lock<std::mutex> lock(mutex_);
        if (queue_.size() >= initialCapacity_) {
            cv_.wait_for(lock, std::chrono::milliseconds(100));
        }
        queue_.push(std::chrono::steady_clock::now());
    }

    bool dequeueRequests() {
        std::unique_lock<std::mutex> lock(mutex_);
        while (!shouldRefresh()) {
            if (queue_.empty()) {
                cv_.wait_for(lock, std::chrono::milliseconds(100));
            }
        }
        return true;
    }

private:
    size_t maxRequestsPerSecond_;
    size_t initialCapacity_;
    size_t currentCapacity_;
    std::chrono::steady_clock::time_point nextRefreshTime_;
    std::queue<std::chrono::steady_clock::time_point> queue_;
    std::mutex mutex_;
    std::condition_variable cv_;

    bool shouldRefresh() {
        return (std::chrono::steady_clock::now() - queue_.front()) > 
               std::chrono::duration_cast<std::chrono::milliseconds>(1.0 / maxRequestsPerSecond_);
    }
};

int main() {
    RateLimiter limiter(100, 10);

    for (size_t i = 0; i < 10000; ++i) {
        if (!limiter.dequeueRequests()) {
            std::cout << "Rate limit exceeded." << std::endl;
            break;
        }
        limiter.enqueueRequest();
    }

    return 0;
}
