    NFAPI_CRC_INDICATION_PDU_T *pdu_t;
    pthread_mutex_t lock;
} cached_ue_context;

cached_ue_context cached_ue_contexts[MAX_CACHED_UE_CONTEXTS];

void *get_ue_context(void *id) {
    int rnti = *(int *)id;
    for (int i = 0; i < MAX_CACHED_UE_CONTEXTS; i++) {
        pthread_mutex_lock(&cached_ue_contexts[i].lock);
        if (cached_ue_contexts[i].pdu_t->RNTI == rnti) {
            pthread_mutex_unlock(&cached_ue_contexts[i].lock);
            return &cached_ue_contexts[i];
        }
        pthread_mutex_unlock(&cached_ue_contexts[i].lock);
    }
    return NULL;
}

void put_ue_context(void *id, NFAPI_CRC_INDICATION_PDU_T *pdu_t) {
    int rnti = *(int *)id;
    for (int i = 0; i < MAX_CACHED_UE_CONTEXTS; i++) {
        pthread_mutex_lock(&cached_ue_contexts[i].lock);
        if (!cached_ue_contexts[i].pdu_t) {
            cached_ue_contexts[i].pdu_t = pdu_t;
            cached_ue_contexts[i].RNTI = rnti;
            pthread_mutex_unlock(&cached_ue_contexts[i].lock);
