#include <iostream>
#include <string>
#include <thread>
#include <mutex>
#include <condition_variable>
#include <queue>
#include <map>
#include <deque>
#include <unordered_map>
#include <chrono>
#include <random>

class RateLimiter {
public:
    void setRate(int rate) {
        std::unique_lock<std::mutex> lock(mutex_);
        rate_ = rate;
    }

    bool tryAcquire() {
        std::unique_lock<std::mutex> lock(mutex_);
        if (acquired_.load(std::memory_order_relaxed)) {
            return false;
        }
        acquired_.store(true, std::memory_order_relaxed);
        std::this_thread::sleep_for(std::chrono::milliseconds(rate_));
        acquired_.store(false, std::memory_order_relaxed);
        return true;
    }

private:
    int rate_;
    std::atomic<bool> acquired_(false);
    mutable std::mutex mutex_;
};

class AnomalyDetector {
public:
    void setThreshold(double threshold) {
        threshold_ = threshold;
    }

    bool isAnomaly(double value) {
        return (value > threshold_);
    }

private:
    double threshold_;
};

class Microservice {
public:
    Microservice(RateLimiter& rateLimiter, AnomalyDetector& anomalyDetector) : 
        rateLimiter_(rateLimiter), anomalyDetector_(anomalyDetector) {}

    void processRequest(int userId, double value) {
        if (!rateLimiter_.tryAcquire()) {
            return; // Rate limit exceeded
        }

        if (anomalyDetector_.isAnomaly(value)) {
            // Anomaly detected, take action
        } else {
            // Normal request processing
        }
    }

private:
    RateLimiter& rateLimiter_;
    AnomalyDetector& anomalyDetector_;
};

int main() {
    // Create instances of RateLimiter and AnomalyDetector
    RateLimiter rateLimiter;
    AnomalyDetector anomalyDetector;

    Microservice microservice(rateLimiter, anomalyDetector);

    // Start processing requests
    for (int i = 0; i < 10000; i++) {
        microservice.processRequest(i, generateRandomValue());
    }

    return 0;
}

double generateRandomValue() {
    static std::random_device rd;
    static std::mt19937 gen(rd());
    static std::normal_distribution<> dis(0.0, 1.0);

    return dis(gen);
}
