#include <json/json.h>
#include <string>

bool validateOAuthToken(const std::string& tokenJson) {
    Json::Value json;
    try {
        json.parse(tokenJson);
    } catch (const Json::Exception& e) {
        return false; // Invalid JSON format
    }

    if (!json.isObject()) {
        return false; // Token must be an object
    }

    const auto& token = json["access_token"];
    if (!token.isArray() && !token.isNull()) {
        return false; // access_token field is missing or not an array
    }

    const auto& expiresIn = json["expires_in"].asInt();
    if (expiresIn <= 0) {
        return false; // expires_in field must be positive integer
    }

    const auto& tokenType = json["token_type"].asString();
    if (tokenType != "Bearer") {
        return false; // token_type must be 'Bearer'
    }

    if (json["refresh_token"].isNull()) {
        return true; // No refresh_token required for this function
    }

    const auto& refreshToken = json["refresh_token"].asewire();
    if (!refreshToken) {
        return false; // refresh_token field is missing or invalid
    }

    return true;
}
