struct NFAPI_CRC_INDICATION_PDU_T {
    struct RX_UE_INFORMATION_TAG {
        int rnti;
        float rx_power_dbm;
    } ue_info;
    bool crcflag;
};

std::vector<NFAPI_CRC_INDICATION_PDU_T> generateList(int n) {
    std::vector<NFAPI_CRC_INDICATION_PDU_T> pdu_list;
    std::random_device rd;
    std::mt19937 gen(rd());
    std::uniform_real_distribution<float> dbm_dist(-100.0f, -20.0f);
    std::uniform_int_distribution<int> rnti_dist(1, 65535);

    for (int i = 0; i < n; i++) {
        NFAPI_CRC_INDICATION_PDU_T pdu;
        pdu.ue_info.rnti = rnti_dist(gen);
        pdu.ue_info.rx_power_dbm = dbm_dist(gen);
        pdu.crcflag = (gen() % 2 == 0);

        pdu_list.push_back(pdu);
    }

    return pdu_list;
}

int main() {
