    std::vector<NFAPI_CRC_INDICATION_PDU_T> pdu_list = generateList(n);

    for (const auto& pdu : pdu_list) {
        std::cout << "RNTI: " << pdu.ue_info.rnti << ", RX Power (dBm): " << pdu.ue_info.rx_power_dbm << ", CRC Flag: " << (pdu.crcflag ? "Set" : "Not Set") << std::endl;
    }

    return 0;
}
