    void setParameter(const std::string& name, double value) {
        // Handle concurrent updates and retries
        if (!setConfigValue(name, value)) {
            // If failed, retry after a delay
            if (retryTimer_) {
                int delay = 100; // milliseconds
                while (delay > 0) {
                    std::this_thread::sleep_for(std::chrono::milliseconds(delay));
                    if (setConfigValue(name, value)) {
                        return;
                    }
                    delay /= 2;
                }
            }
        }
    }

    double getParameter(const std::string& name) {
        // Handle cache misses and database lookups
        if (!cache_.count(name)) {
            // Fetch from distributed cache or database
            double value = fetchFromCacheOrDatabase(name);
            // Store in local cache for future access
            cache_[name] = value;
        }
        return cache_[name];
    }

private:
    bool setConfigValue(const std::string& name, double value) {
        // Check if update is allowed based on rate limiting and authentication
        if (!isUpdateAllowed()) {
            return false;
        }
        // Update parameter in local store
        parameters_[name] = value;
        // Notify listeners of changes
        notifyListeners();
        return true;
    }

    double fetchFromCacheOrDatabase(const std::string& name) {
        // Handle distributed cache and database lookups
        if (isInLocalCache(name)) {
            return getFromLocalCache(name);
        } else {
            return getFromDistributedCache(name); // or getFromDatabase()
