import hashlib
from queue import Queue
import threading
from typing import Dict, List

class HashingService:
    def __init__(self):
        self.md5_hashes = {}
        self.sha256_hashes = {}
        self.concurrent_requests = 0
        self.request_queue = Queue()
        self.hashing_threads = []
        self.file_systems = {
            'cloud_storage': {'api_key': 'your_api_key', 'api_secret': 'your_api_secret'},
            'on_premises_storage': {'username': 'your_username', 'password': 'your_password'}
        }
        self.encrypted_data = {}

    def compute_hashes(self, file_path: str) -> Dict[str, str]:
        md5_hash = hashlib.md5()
        sha256_hash = hashlib.sha256()

        with open(file_path, 'rb') as file:
            for chunk in iter(lambda: file.read(4096), b''):
                md5_hash.update(chunk)
                sha256_hash.update(chunk)

        return {'md5': md5_hash.hexdigest(), 'sha256': sha256_hash.hexdigest()}

    def handle_request(self, request):
        self.concurrent_requests += 1
        try:
            file_path = request['file_path']
            hashes = self.compute_hashes(file_path)
            self.md5_hashes[file_path] = hashes['md5']
            self.sha256_hashes[file_path] = hashes['sha256']
            print(f"Hashes computed for {file_path}")
        except Exception as e:
            print(f"Error processing request: {e}")
        finally:
            self.concurrent_requests -= 1

    def start_hashing(self):
        while not self.request_queue.empty():
            request = self.request_queue.get()
            threading.Thread(target=self.handle_request, args=(request,)).start()

    def add_request(self, file_path):
        self.request_queue.put({'file_path': file_path})

    def get_hashes(self, file_path) -> Dict[str, str]:
        return {'md5': self.md5_hashes.get(file_path), 'sha256': self.sha256_hashes.get(file_path)}

    def close(self):
        for thread in self.hashing_threads:
            thread.join()
        self.request_queue.join()

if __name__ == '__main__':
    service = HashingService()

    # Start the hashing service
    threading.Thread(target=service.start_hashing).start()

    # Add requests to the queue
    service.add_request('file1.txt')
    service.add_request('file2.txt')
    service.add_request('file3.txt')

    # Get hashes for a specific file
    print(service.get_hashes('file1.txt'))

    # Close the hashing service
    service.close()
