using System;
using System.Security.Cryptography;

namespace EncryptionFramework
{
    public class TripleDESCipher
    {
        private readonly DESCryptoServiceProvider _cryptoProvider;

        public TripleDESCipher(byte[] key, byte[] iv)
        {
            _cryptoProvider = new DESCryptoServiceProvider();
            _cryptoProvider.Key = key;
            _cryptoProvider.IV = iv;
        }

        public byte[] Encrypt(byte[] data)
        {
            return _cryptoProvider.CreateEncryptor().TransformFinalBlock(data, 0, data.Length);
        }

        public byte[] Decrypt(byte[] data)
        {
            return _cryptoProvider.CreateDecryptor().TransformFinalBlock(data, 0, data.Length);
        }
    }
}

