using System;
using System.Security.Cryptography;

namespace EncryptionFramework
{
    public class HardwareAcceleratedCipher : TripleDESCipher
    {
        private readonly ICryptoApi _cryptoApi;

        public HardwareAcceleratedCipher(byte[] key, byte[] iv, ICryptoApi cryptoApi)
            : base(key, iv)
        {
            _cryptoApi = cryptoApi;
        }

        public override byte[] Encrypt(byte[] data)
        {
            if (_cryptoApi.IsHardwareTokenAvailable())
                return _cryptoApi.Encrypt(data);
            else
                return base.Encrypt(data);
        }

        public override byte[] Decrypt(byte[] data)
        {
            if (_cryptoApi.IsHardwareTokenAvailable())
                return _cryptoApi.Decrypt(data);
            else
                return base.Decrypt(data);
        }
    }
}
```

**Retry Mechanism for Failed Read Attempts**

```javascript
async function readFileSync(path, retries = 3) {
  try {
    const fileBuffer = await fs.promises.readFile(path);
    return fileBuffer.toString();
  } catch (error) {
    if (retries > 0 && error.code === 'EIO') {
      console.error(`Error reading file: ${path}. Retrying...`);
      return await readFileSync(path, retries - 1);
    }
    throw error;
  }
}
```

