           << ", byte_count=" << stats.byte_count
           << ", error_rate=" << stats.error_rate
           << ", timestamp=" << stats.timestamp;
        return os;
    }
};

class PacketStatPool {
public:
    static const int MAX_PACKET_STATS = 1000;

    PacketStatPool() : packet_stats_(new PacketStats[MAX_PACKET_STATS]),
                      next_available_(0),
                      lock_() {}

    ~PacketStatPool() { delete[] packet_stats_; }

    void addPacketStat(const PacketStats& stats) {
        std::lock_guard<std::mutex> guard(lock_);
        if (next_available_ >= MAX_PACKET_STATS) {
            // Handle full pool
        }
        packet_stats_[next_available_] = stats;
        next_available_++;
    }

    PacketStats getPacketStat(int index) {
        std::lock_guard<std::mutex> guard(lock_);
        return packet_stats_[index];
    }

private:
    PacketStats* packet_stats_;
    int next_available_;
    std::mutex lock_;
};

