    int total_count = 0;
    double weighted_sum = 0.0;
    int last_max_age = 0;

    for (int i = 0; i < count; i++) {
        Transaction transaction = transactions[i];
        if (transaction.id > last_max_age) {
            max_age = transaction.id;
            total_count = 1;
            weighted_sum += transaction.value;
        } else if (transaction.id <= max_age + 3 && transaction.id >= last_max_age - 3) {
            total_count++;
            weighted_sum += transaction.value;
        }

        last_max_age = transaction.id;

        if (weighted_sum > 0.5) {
            *max_weight_sum_id = transaction.id;
            return 1;
        }
    }

